#define QRT_QWEN36_LAYER_DESCRIPTOR_COUNT \
    (sizeof(QRT_QWEN36_LAYER_DESCRIPTORS) / sizeof(QRT_QWEN36_LAYER_DESCRIPTORS[0]))

static const qrt_qwen36_layer_descriptor_t *qrt_qwen36_layer_descriptor(size_t layer_index) {
    if (layer_index >= QRT_QWEN36_LAYER_DESCRIPTOR_COUNT ||
        QRT_QWEN36_LAYER_DESCRIPTORS[layer_index].layer_index != layer_index) {
        return NULL;
    }
    return &QRT_QWEN36_LAYER_DESCRIPTORS[layer_index];
}

static int qrt_qwen36_validate_layer_descriptor_helper(uint64_t *out_hash, size_t *out_count) {
    uint64_t hash = UINT64_C(1469598103934665603);
    size_t layer;

    if (out_hash == NULL || out_count == NULL || QRT_QWEN36_LAYER_DESCRIPTOR_COUNT < 4u) {
        return 0;
    }
    for (layer = 0u; layer < QRT_QWEN36_LAYER_DESCRIPTOR_COUNT; ++layer) {
        const qrt_qwen36_layer_descriptor_t *desc = qrt_qwen36_layer_descriptor(layer);
        const char *const *attention_tensors = NULL;
        size_t attention_tensor_count = 0u;
        size_t tensor_idx;
        uint32_t layer_index;
        uint32_t attention_kind;

        if (desc == NULL) {
            return 0;
        }
        {
            const char *const common_tensors[] = {
                desc->input_norm_tensor,
                desc->post_attention_norm_tensor,
                desc->moe_router_tensor,
                desc->moe_expert_gate_up_tensor,
                desc->moe_expert_down_tensor,
                desc->moe_shared_gate_tensor,
                desc->moe_shared_gate_proj_tensor,
                desc->moe_shared_up_proj_tensor,
                desc->moe_shared_down_tensor
            };
            const char *const linear_attention_tensors[] = {
                desc->qkv_tensor,
                desc->z_tensor,
                desc->a_tensor,
                desc->b_tensor,
                desc->conv_tensor,
                desc->a_log_tensor,
                desc->dt_bias_tensor,
                desc->linear_norm_tensor,
                desc->out_proj_tensor
            };
            const char *const full_attention_tensors[] = {
                desc->self_q_tensor,
                desc->self_k_tensor,
                desc->self_v_tensor,
                desc->self_o_tensor,
                desc->self_q_norm_tensor,
                desc->self_k_norm_tensor
            };

            if (desc->attention_kind == QRT_QWEN36_ATTENTION_LINEAR) {
                attention_tensors = linear_attention_tensors;
                attention_tensor_count =
                    sizeof(linear_attention_tensors) / sizeof(linear_attention_tensors[0]);
            } else if (desc->attention_kind == QRT_QWEN36_ATTENTION_FULL) {
                attention_tensors = full_attention_tensors;
                attention_tensor_count =
                    sizeof(full_attention_tensors) / sizeof(full_attention_tensors[0]);
            } else {
                return 0;
            }

            layer_index = desc->layer_index;
            attention_kind = (uint32_t)desc->attention_kind;
            hash = qrt_fnv1a64_update_bytes(hash, &layer_index, sizeof(layer_index));
            hash = qrt_fnv1a64_update_bytes(hash, &attention_kind, sizeof(attention_kind));
            for (tensor_idx = 0u;
                 tensor_idx < sizeof(common_tensors) / sizeof(common_tensors[0]);
                 ++tensor_idx) {
                const char *tensor = common_tensors[tensor_idx];
                if (tensor == NULL || tensor[0] == '\0') {
                    return 0;
                }
                hash = qrt_fnv1a64_update_bytes(hash, tensor, strlen(tensor) + 1u);
            }
            for (tensor_idx = 0u; tensor_idx < attention_tensor_count; ++tensor_idx) {
                const char *tensor = attention_tensors[tensor_idx];
                if (tensor == NULL || tensor[0] == '\0') {
                    return 0;
                }
                hash = qrt_fnv1a64_update_bytes(hash, tensor, strlen(tensor) + 1u);
            }
        }
    }
    *out_hash = hash;
    *out_count = QRT_QWEN36_LAYER_DESCRIPTOR_COUNT;
    return 1;
}

