typedef struct qrt_moe_expert_cache_entry_t {
    uint16_t *gate_up;
    uint16_t *down;
    uint64_t gate_up_fnv1a64;
    uint64_t down_fnv1a64;
    int loaded;
} qrt_moe_expert_cache_entry_t;

typedef struct qrt_tensor_location_t {
    char shard[QRT_LOAD_PATH_CAPACITY];
    uint64_t header_len;
    uint64_t data_begin;
    uint64_t data_end;
} qrt_tensor_location_t;

struct qrt_tensor_location_cache_entry_t {
    char *tensor_name;
    qrt_tensor_location_t location;
};

#ifdef _WIN32
struct qrt_win32_shard_read_cache_entry_t {
    char shard[QRT_LOAD_PATH_CAPACITY];
    HANDLE file_handle;
    uint64_t file_size;
};
#endif

static void qrt_engine_free_tensor_location_cache(qrt_engine_t *engine) {
    size_t index;

    if (engine == NULL || engine->tensor_location_cache_entries == NULL) {
        return;
    }
    for (index = 0u; index < engine->tensor_location_cache_entry_count; ++index) {
        free(engine->tensor_location_cache_entries[index].tensor_name);
    }
    free(engine->tensor_location_cache_entries);
    engine->tensor_location_cache_entries = NULL;
    engine->tensor_location_cache_entry_count = 0u;
    engine->tensor_location_cache_entry_capacity = 0u;
}

