static void qrt_qwen36_store_layer0_prefill_chunk_dim_selected_trace(
    uint32_t *row_indices,
    uint32_t *token_indices,
    float *values,
    uint32_t *value_bits,
    const uint32_t *rows,
    size_t row_count,
    size_t trace_token_count,
    const float *source_rows,
    size_t source_feature_count,
    size_t source_dim,
    int key_expanded
) {
    size_t token_index;
    size_t row_item;
    const size_t token_capacity =
        (size_t)QRT_QWEN36_LAYER0_PREFILL_CHUNK_INPUT_TRACE_TOKEN_COUNT;
    const size_t value_head_group =
        (size_t)QRT_QWEN36_LAYER0_LINEAR_ATTN_VALUE_HEADS /
        (size_t)QRT_QWEN36_LAYER0_LINEAR_ATTN_KEY_HEADS;

    if (row_indices == NULL || token_indices == NULL || values == NULL ||
        value_bits == NULL || rows == NULL || source_rows == NULL) {
        return;
    }

    for (token_index = 0u; token_index < token_capacity; ++token_index) {
        token_indices[token_index] = (uint32_t)token_index;
    }
    for (row_item = 0u; row_item < row_count; ++row_item) {
        const uint32_t row = rows[row_item];
        const size_t source_head =
            key_expanded ? (size_t)row / value_head_group : (size_t)row;
        size_t dim;

        row_indices[row_item] = row;
        if ((source_head + 1u) * source_dim > source_feature_count) {
            continue;
        }
        for (token_index = 0u;
             token_index < trace_token_count && token_index < token_capacity;
             ++token_index) {
            const float *source =
                source_rows + token_index * source_feature_count +
                source_head * source_dim;
            for (dim = 0u; dim < source_dim; ++dim) {
                const float value = source[dim];
                const size_t flat_index =
                    (row_item * token_capacity + token_index) * source_dim + dim;
                values[flat_index] = value;
                value_bits[flat_index] = qrt_float_to_bits(value);
            }
        }
    }
}

static void qrt_qwen36_store_layer0_prefill_chunk_gate_selected_trace(
    uint32_t *row_indices,
    uint32_t *token_indices,
    float *values,
    uint32_t *value_bits,
    const uint32_t *rows,
    size_t row_count,
    size_t trace_token_count,
    const float *source_rows
) {
    size_t token_index;
    size_t row_item;
    const size_t token_capacity =
        (size_t)QRT_QWEN36_LAYER0_PREFILL_CHUNK_INPUT_TRACE_TOKEN_COUNT;

    if (row_indices == NULL || token_indices == NULL || values == NULL ||
        value_bits == NULL || rows == NULL || source_rows == NULL) {
        return;
    }

    for (token_index = 0u; token_index < token_capacity; ++token_index) {
        token_indices[token_index] = (uint32_t)token_index;
    }
    for (row_item = 0u; row_item < row_count; ++row_item) {
        const uint32_t row = rows[row_item];
        row_indices[row_item] = row;
        if (row >= (uint32_t)QRT_QWEN36_LAYER0_LINEAR_ATTN_GATE_ELEMENTS) {
            continue;
        }
        for (token_index = 0u;
             token_index < trace_token_count && token_index < token_capacity;
             ++token_index) {
            const float value =
                source_rows
                    [token_index *
                         (size_t)QRT_QWEN36_LAYER0_LINEAR_ATTN_GATE_ELEMENTS +
                     (size_t)row];
            const size_t flat_index = row_item * token_capacity + token_index;
            values[flat_index] = value;
            value_bits[flat_index] = qrt_float_to_bits(value);
        }
    }
}

static void qrt_qwen36_store_layer0_prefill_chunk_gate_input_selected_trace(
    uint32_t *row_indices,
    float *a_values,
    uint32_t *a_value_bits,
    float *a_plus_dt_values,
    uint32_t *a_plus_dt_value_bits,
    const uint32_t *rows,
    size_t row_count,
    size_t trace_token_count,
    const float *a_rows,
    const uint16_t *dt_bias
) {
    size_t token_index;
    size_t row_item;
    const size_t token_capacity =
        (size_t)QRT_QWEN36_LAYER0_PREFILL_CHUNK_INPUT_TRACE_TOKEN_COUNT;

    if (row_indices == NULL || a_values == NULL || a_value_bits == NULL ||
        a_plus_dt_values == NULL || a_plus_dt_value_bits == NULL ||
        rows == NULL || a_rows == NULL || dt_bias == NULL) {
        return;
    }

    for (row_item = 0u; row_item < row_count; ++row_item) {
        const uint32_t row = rows[row_item];
        const float dt = row < (uint32_t)QRT_QWEN36_LAYER0_LINEAR_ATTN_GATE_ELEMENTS
            ? qrt_bf16_to_float(dt_bias[row])
            : 0.0f;
        row_indices[row_item] = row;
        if (row >= (uint32_t)QRT_QWEN36_LAYER0_LINEAR_ATTN_GATE_ELEMENTS) {
            continue;
        }
        for (token_index = 0u;
             token_index < trace_token_count && token_index < token_capacity;
             ++token_index) {
            const float a =
                a_rows
                    [token_index *
                         (size_t)QRT_QWEN36_LAYER0_LINEAR_ATTN_GATE_ELEMENTS +
                     (size_t)row];
            const float a_plus_dt = a + dt;
            const size_t flat_index = row_item * token_capacity + token_index;
            a_values[flat_index] = a;
            a_value_bits[flat_index] = qrt_float_to_bits(a);
            a_plus_dt_values[flat_index] = a_plus_dt;
            a_plus_dt_value_bits[flat_index] = qrt_float_to_bits(a_plus_dt);
        }
    }
}

static void qrt_qwen36_store_layer0_prefill_chunk_state_row_hashes(
    uint64_t *row_hashes,
    const float *state
) {
    size_t row;
    const size_t key_dim =
        (size_t)QRT_QWEN36_LAYER0_LINEAR_ATTN_KEY_DIM;
    const size_t row_count =
        (size_t)QRT_QWEN36_LAYER0_PREFILL_CHUNK_STATE_ROW_HASH_COUNT;

    if (row_hashes == NULL || state == NULL) {
        return;
    }

    for (row = 0u; row < row_count; ++row) {
        row_hashes[row] = qrt_fnv1a64_f32(state + row * key_dim, key_dim);
    }
}

static void qrt_qwen36_store_layer0_prefill_chunk_state_selected_trace(
    qrt_engine_t *engine,
    const float *state
) {
    static const uint32_t rows[
        QRT_QWEN36_LAYER0_PREFILL_CHUNK_STATE_TRACE_ROW_COUNT
    ] = {
        0u, 1u, 2u, 3u, 4u, 5u, 6u, 7u,
        8u, 9u, 10u, 11u, 12u, 13u, 14u, 15u,
        16u, 17u, 18u, 19u, 20u, 21u, 22u, 23u,
        24u, 25u, 26u, 27u, 28u, 29u, 30u, 31u
    };
    const size_t key_dim = (size_t)QRT_QWEN36_LAYER0_LINEAR_ATTN_KEY_DIM;
    const size_t state_row_count =
        (size_t)QRT_QWEN36_LAYER0_PREFILL_CHUNK_STATE_ROW_HASH_COUNT;
    size_t row_item;

    if (engine == NULL || state == NULL) {
        return;
    }

    for (row_item = 0u;
         row_item <
         (size_t)QRT_QWEN36_LAYER0_PREFILL_CHUNK_STATE_TRACE_ROW_COUNT;
         ++row_item) {
        const uint32_t row = rows[row_item];
        size_t dim;
        engine
            ->baseline_plain_block_trace_layer0_prefill_chunk_state_selected_row_indices
                [row_item] = row;
        if ((size_t)row >= state_row_count) {
            continue;
        }
        for (dim = 0u; dim < key_dim; ++dim) {
            const float value = state[(size_t)row * key_dim + dim];
            const size_t flat_index = row_item * key_dim + dim;
            engine
                ->baseline_plain_block_trace_layer0_prefill_chunk_state_selected_values
                    [flat_index] = value;
            engine
                ->baseline_plain_block_trace_layer0_prefill_chunk_state_selected_value_bits
                    [flat_index] = qrt_float_to_bits(value);
        }
    }
}

