static float qrt_gate_softplus_f32(float value) {
    float softplus;
    if (value > 0.0f) {
        softplus = value + logf(1.0f + expf(-value));
    } else {
        softplus = logf(1.0f + expf(value));
    }
    if (!(value <= 20.0f)) {
        softplus = value;
    }
    return softplus;
}

static int qrt_layer0_gate_rows_cpu(
    const float *a_rows,
    const float *b_rows,
    const uint16_t *a_log,
    const uint16_t *dt_bias,
    float *g_rows,
    float *beta_rows
) {
    size_t head;

    if (a_rows == NULL || b_rows == NULL || a_log == NULL || dt_bias == NULL ||
        g_rows == NULL || beta_rows == NULL) {
        return 0;
    }

    for (head = 0u; head < (size_t)QRT_QWEN36_LAYER0_LINEAR_ATTN_GATE_ELEMENTS; ++head) {
        float a = a_rows[head] + qrt_bf16_to_float(dt_bias[head]);
        float b = b_rows[head];
        float g = -expf(qrt_bf16_to_float(a_log[head])) * qrt_gate_softplus_f32(a);
        float beta = 1.0f / (1.0f + expf(-b));
        if (g != g || beta != beta) {
            return 0;
        }
        g_rows[head] = g;
        beta_rows[head] = qrt_bf16_to_float(qrt_float_to_bf16(beta));
    }

    return 1;
}

