    const qrt_qwen36_layer_descriptor_t *desc;
    const float *a_projection;
    const float *b_projection;
    const uint16_t *a_log;
    const uint16_t *dt_bias;
    float *gate_g;
    float *gate_beta;
    uint64_t *gate_elapsed_ns;
    uint64_t *gate_g_hash;
    uint64_t *gate_beta_hash;
    uint64_t *last_gate_g_hash;
    uint64_t *last_gate_beta_hash;
    size_t *gate_materialized_count;
    const char *gate_stage;
    const char *gate_failure;
