static qrt_status_t
qrt_qwen36_apply_descriptor_layer_body_full_attention_qkv(
    qrt_engine_t *engine,
    const qrt_qwen36_layer_descriptor_t *desc,
    const float *input_norm_rows,
    size_t input_token_count,
    uint16_t *qkv_weight,
    float *qkv_projection_output,
    qrt_qwen36_descriptor_layer_body_full_attention_qkv_result_t *out_result
) {
    uint64_t start_ns;
    uint64_t qkv_start_ns;
    uint64_t weight_hash = UINT64_C(0);
    uint16_t *q_weight;
    uint16_t *k_weight;
    uint16_t *v_weight;
    size_t input_norm_elements;
    size_t token_index;
    qrt_status_t status;

    if (engine == NULL || desc == NULL ||
        desc->attention_kind != QRT_QWEN36_ATTENTION_FULL ||
        desc->self_q_tensor == NULL || desc->self_k_tensor == NULL ||
        desc->self_v_tensor == NULL || input_norm_rows == NULL ||
        input_token_count == 0u || qkv_weight == NULL ||
        qkv_projection_output == NULL || out_result == NULL) {
        return QRT_STATUS_INVALID_ARGUMENT;
    }
    if (input_token_count > SIZE_MAX / (size_t)QRT_QWEN36_HIDDEN_SIZE ||
        input_token_count >
            SIZE_MAX / (size_t)QRT_QWEN36_LAYER3_SELF_ATTN_QKV_ROWS) {
        return QRT_STATUS_INVALID_ARGUMENT;
    }

    memset(out_result, 0, sizeof(*out_result));
    start_ns = qrt_now_ns();
    qkv_start_ns = start_ns;
    out_result->qkv_projection_hash = UINT64_C(1469598103934665603);
    input_norm_elements =
        input_token_count * (size_t)QRT_QWEN36_HIDDEN_SIZE;
    out_result->input_norm_hash =
        qrt_fnv1a64_f32(input_norm_rows, input_norm_elements);

    q_weight = qkv_weight;
    k_weight =
        q_weight + (size_t)QRT_QWEN36_LAYER3_SELF_ATTN_Q_WEIGHT_ELEMENTS;
    v_weight =
        k_weight + (size_t)QRT_QWEN36_LAYER3_SELF_ATTN_K_WEIGHT_ELEMENTS;

    status = qrt_materialize_layer0_linear_projection_weight(
        engine,
        desc->self_q_tensor,
        q_weight,
        (size_t)QRT_QWEN36_LAYER3_SELF_ATTN_Q_WEIGHT_ELEMENTS,
        &weight_hash,
        &out_result->qkv_projection_weight_bytes_read
    );
    if (status == QRT_STATUS_OK) {
        status = qrt_materialize_layer0_linear_projection_weight(
            engine,
            desc->self_k_tensor,
            k_weight,
            (size_t)QRT_QWEN36_LAYER3_SELF_ATTN_K_WEIGHT_ELEMENTS,
            &weight_hash,
            &out_result->qkv_projection_weight_bytes_read
        );
    }
    if (status == QRT_STATUS_OK) {
        status = qrt_materialize_layer0_linear_projection_weight(
            engine,
            desc->self_v_tensor,
            v_weight,
            (size_t)QRT_QWEN36_LAYER3_SELF_ATTN_V_WEIGHT_ELEMENTS,
            &weight_hash,
            &out_result->qkv_projection_weight_bytes_read
        );
    }
    if (status != QRT_STATUS_OK) {
        out_result->qkv_elapsed_ns =
            qrt_elapsed_ns(qkv_start_ns, qrt_now_ns());
        out_result->elapsed_ns = qrt_elapsed_ns(start_ns, qrt_now_ns());
        qrt_engine_set_token_request_failure(
            engine,
            "hprefix_descriptor_layer_body_full_attention_qkv_weight",
            "H-PREFIX descriptor full-attention body could not materialize Q/K/V projection weights"
        );
        return status;
    }
    out_result->qkv_projection_weight_hash = qrt_fnv1a64_bytes(
        qkv_weight,
        (size_t)QRT_QWEN36_LAYER3_SELF_ATTN_QKV_WEIGHT_BYTES
    );

    for (token_index = 0u; token_index < input_token_count; ++token_index) {
        const float *input_norm =
            input_norm_rows + token_index * (size_t)QRT_QWEN36_HIDDEN_SIZE;
        float *q_projection =
            qkv_projection_output +
            token_index * (size_t)QRT_QWEN36_LAYER3_SELF_ATTN_QKV_ROWS;
        float *k_projection =
            q_projection + (size_t)QRT_QWEN36_LAYER3_SELF_ATTN_Q_ROWS;
        float *v_projection =
            k_projection + (size_t)QRT_QWEN36_LAYER3_SELF_ATTN_K_ROWS;

        if (!qrt_layer0_linear_projection_cpu(
                q_weight,
                (size_t)QRT_QWEN36_LAYER3_SELF_ATTN_Q_ROWS,
                input_norm,
                (size_t)QRT_QWEN36_HIDDEN_SIZE,
                q_projection
            ) ||
            !qrt_layer0_linear_projection_cpu(
                k_weight,
                (size_t)QRT_QWEN36_LAYER3_SELF_ATTN_K_ROWS,
                input_norm,
                (size_t)QRT_QWEN36_HIDDEN_SIZE,
                k_projection
            ) ||
            !qrt_layer0_linear_projection_cpu(
                v_weight,
                (size_t)QRT_QWEN36_LAYER3_SELF_ATTN_V_ROWS,
                input_norm,
                (size_t)QRT_QWEN36_HIDDEN_SIZE,
                v_projection
            )) {
            out_result->qkv_elapsed_ns =
                qrt_elapsed_ns(qkv_start_ns, qrt_now_ns());
            out_result->elapsed_ns = qrt_elapsed_ns(start_ns, qrt_now_ns());
            qrt_engine_set_token_request_failure(
                engine,
                "hprefix_descriptor_layer_body_full_attention_qkv",
                "H-PREFIX descriptor full-attention body Q/K/V projection produced an invalid value"
            );
            return QRT_STATUS_UNSUPPORTED;
        }

        out_result->qkv_projection_hash = qrt_fnv1a64_update_bytes(
            out_result->qkv_projection_hash,
            q_projection,
            (size_t)QRT_QWEN36_LAYER3_SELF_ATTN_QKV_ROWS *
                sizeof(q_projection[0])
        );
        out_result->last_qkv_projection_hash = qrt_fnv1a64_f32(
            q_projection,
            (size_t)QRT_QWEN36_LAYER3_SELF_ATTN_QKV_ROWS
        );
        out_result->materialized_count += 1u;
    }
    out_result->qkv_elapsed_ns = qrt_elapsed_ns(qkv_start_ns, qrt_now_ns());

    out_result->output_hidden_hash = qrt_fnv1a64_bytes(
        "Qwen3.6/H-PREFIX-INT-001/descriptor-layer-body-full-attention-qkv-output-v1",
        sizeof(
            "Qwen3.6/H-PREFIX-INT-001/descriptor-layer-body-full-attention-qkv-output-v1"
        )
    );
    out_result->output_hidden_hash = qrt_fnv1a64_update_bytes(
        out_result->output_hidden_hash,
        &desc->layer_index,
        sizeof(desc->layer_index)
    );
    out_result->output_hidden_hash = qrt_fnv1a64_update_bytes(
        out_result->output_hidden_hash,
        &input_token_count,
        sizeof(input_token_count)
    );
    out_result->output_hidden_hash = qrt_fnv1a64_update_bytes(
        out_result->output_hidden_hash,
        &out_result->input_norm_hash,
        sizeof(out_result->input_norm_hash)
    );
    out_result->output_hidden_hash = qrt_fnv1a64_update_bytes(
        out_result->output_hidden_hash,
        &out_result->qkv_projection_hash,
        sizeof(out_result->qkv_projection_hash)
    );
    out_result->output_hidden_hash = qrt_fnv1a64_update_bytes(
        out_result->output_hidden_hash,
        &out_result->last_qkv_projection_hash,
        sizeof(out_result->last_qkv_projection_hash)
    );
    out_result->output_hidden_hash = qrt_fnv1a64_update_bytes(
        out_result->output_hidden_hash,
        &out_result->materialized_count,
        sizeof(out_result->materialized_count)
    );

    out_result->body_digest = qrt_fnv1a64_bytes(
        "Qwen3.6/H-PREFIX-INT-001/descriptor-layer-body-full-attention-qkv-v1",
        sizeof(
            "Qwen3.6/H-PREFIX-INT-001/descriptor-layer-body-full-attention-qkv-v1"
        )
    );
    out_result->body_digest = qrt_fnv1a64_update_bytes(
        out_result->body_digest,
        &desc->layer_index,
        sizeof(desc->layer_index)
    );
    out_result->body_digest = qrt_fnv1a64_update_bytes(
        out_result->body_digest,
        &input_token_count,
        sizeof(input_token_count)
    );
    out_result->body_digest = qrt_fnv1a64_update_bytes(
        out_result->body_digest,
        &out_result->input_norm_hash,
        sizeof(out_result->input_norm_hash)
    );
    out_result->body_digest = qrt_fnv1a64_update_bytes(
        out_result->body_digest,
        &out_result->qkv_projection_hash,
        sizeof(out_result->qkv_projection_hash)
    );
    out_result->body_digest = qrt_fnv1a64_update_bytes(
        out_result->body_digest,
        &out_result->last_qkv_projection_hash,
        sizeof(out_result->last_qkv_projection_hash)
    );
    out_result->body_digest = qrt_fnv1a64_update_bytes(
        out_result->body_digest,
        &out_result->qkv_projection_weight_hash,
        sizeof(out_result->qkv_projection_weight_hash)
    );
    out_result->body_digest = qrt_fnv1a64_update_bytes(
        out_result->body_digest,
        &out_result->qkv_projection_weight_bytes_read,
        sizeof(out_result->qkv_projection_weight_bytes_read)
    );
    out_result->body_digest = qrt_fnv1a64_update_bytes(
        out_result->body_digest,
        &out_result->output_hidden_hash,
        sizeof(out_result->output_hidden_hash)
    );
    out_result->body_digest = qrt_fnv1a64_update_bytes(
        out_result->body_digest,
        desc->self_q_tensor,
        strlen(desc->self_q_tensor) + 1u
    );
    out_result->body_digest = qrt_fnv1a64_update_bytes(
        out_result->body_digest,
        desc->self_k_tensor,
        strlen(desc->self_k_tensor) + 1u
    );
    out_result->body_digest = qrt_fnv1a64_update_bytes(
        out_result->body_digest,
        desc->self_v_tensor,
        strlen(desc->self_v_tensor) + 1u
    );
    out_result->elapsed_ns = qrt_elapsed_ns(start_ns, qrt_now_ns());
    return QRT_STATUS_OK;
}

