static int qrt_layer0_moe_expert_gate_up_projection_scalar_block4_range_cpu(
    const uint16_t *gate_up_weight,
    const float *input,
    float *gate_values,
    float *up_values,
    size_t inter_begin,
    size_t inter_end
) {
    size_t inter;

    if (gate_up_weight == NULL || input == NULL ||
        gate_values == NULL || up_values == NULL ||
        inter_begin >= inter_end ||
        inter_end > (size_t)QRT_QWEN36_MOE_EXPERT_INTERMEDIATE) {
        return 0;
    }

    inter = inter_begin;
    for (;
         inter + 3u < inter_end;
         inter += 4u) {
        size_t col;
        const uint16_t *gate_row0 =
            gate_up_weight + (inter + 0u) * (size_t)QRT_QWEN36_HIDDEN_SIZE;
        const uint16_t *gate_row1 =
            gate_up_weight + (inter + 1u) * (size_t)QRT_QWEN36_HIDDEN_SIZE;
        const uint16_t *gate_row2 =
            gate_up_weight + (inter + 2u) * (size_t)QRT_QWEN36_HIDDEN_SIZE;
        const uint16_t *gate_row3 =
            gate_up_weight + (inter + 3u) * (size_t)QRT_QWEN36_HIDDEN_SIZE;
        const uint16_t *up_row0 =
            gate_up_weight +
            ((size_t)QRT_QWEN36_MOE_EXPERT_INTERMEDIATE + inter + 0u) *
                (size_t)QRT_QWEN36_HIDDEN_SIZE;
        const uint16_t *up_row1 =
            gate_up_weight +
            ((size_t)QRT_QWEN36_MOE_EXPERT_INTERMEDIATE + inter + 1u) *
                (size_t)QRT_QWEN36_HIDDEN_SIZE;
        const uint16_t *up_row2 =
            gate_up_weight +
            ((size_t)QRT_QWEN36_MOE_EXPERT_INTERMEDIATE + inter + 2u) *
                (size_t)QRT_QWEN36_HIDDEN_SIZE;
        const uint16_t *up_row3 =
            gate_up_weight +
            ((size_t)QRT_QWEN36_MOE_EXPERT_INTERMEDIATE + inter + 3u) *
                (size_t)QRT_QWEN36_HIDDEN_SIZE;
        float gate0 = 0.0f;
        float gate1 = 0.0f;
        float gate2 = 0.0f;
        float gate3 = 0.0f;
        float up0 = 0.0f;
        float up1 = 0.0f;
        float up2 = 0.0f;
        float up3 = 0.0f;
        const float *input_ptr = input;
        const uint16_t *gate_ptr0 = gate_row0;
        const uint16_t *gate_ptr1 = gate_row1;
        const uint16_t *gate_ptr2 = gate_row2;
        const uint16_t *gate_ptr3 = gate_row3;
        const uint16_t *up_ptr0 = up_row0;
        const uint16_t *up_ptr1 = up_row1;
        const uint16_t *up_ptr2 = up_row2;
        const uint16_t *up_ptr3 = up_row3;

        for (col = 0u; col < (size_t)QRT_QWEN36_HIDDEN_SIZE; ++col) {
            const float input_value = *input_ptr++;
            gate0 += input_value * qrt_bf16_to_float_hot(*gate_ptr0++);
            gate1 += input_value * qrt_bf16_to_float_hot(*gate_ptr1++);
            gate2 += input_value * qrt_bf16_to_float_hot(*gate_ptr2++);
            gate3 += input_value * qrt_bf16_to_float_hot(*gate_ptr3++);
            up0 += input_value * qrt_bf16_to_float_hot(*up_ptr0++);
            up1 += input_value * qrt_bf16_to_float_hot(*up_ptr1++);
            up2 += input_value * qrt_bf16_to_float_hot(*up_ptr2++);
            up3 += input_value * qrt_bf16_to_float_hot(*up_ptr3++);
        }
        if (gate0 != gate0 || up0 != up0 ||
            gate1 != gate1 || up1 != up1 ||
            gate2 != gate2 || up2 != up2 ||
            gate3 != gate3 || up3 != up3) {
            return 0;
        }
        gate_values[inter + 0u] = gate0;
        up_values[inter + 0u] = up0;
        gate_values[inter + 1u] = gate1;
        up_values[inter + 1u] = up1;
        gate_values[inter + 2u] = gate2;
        up_values[inter + 2u] = up2;
        gate_values[inter + 3u] = gate3;
        up_values[inter + 3u] = up3;
    }
    for (; inter < inter_end; ++inter) {
        size_t col;
        const uint16_t *gate_row =
            gate_up_weight + inter * (size_t)QRT_QWEN36_HIDDEN_SIZE;
        const uint16_t *up_row =
            gate_up_weight +
            ((size_t)QRT_QWEN36_MOE_EXPERT_INTERMEDIATE + inter) *
                (size_t)QRT_QWEN36_HIDDEN_SIZE;
        float gate = 0.0f;
        float up = 0.0f;
        for (col = 0u; col < (size_t)QRT_QWEN36_HIDDEN_SIZE; ++col) {
            const float input_value = input[col];
            gate += input_value * qrt_bf16_to_float_hot(gate_row[col]);
            up += input_value * qrt_bf16_to_float_hot(up_row[col]);
        }
        if (gate != gate || up != up) {
            return 0;
        }
        gate_values[inter] = gate;
        up_values[inter] = up;
    }

    return 1;
}

