static int qrt_layer0_moe_expert_down_projection_scalar_block4_range_cpu(
    const uint16_t *down_weight,
    const float *activated,
    float scale,
    float *output,
    size_t row_begin,
    size_t row_end
) {
    size_t row;

    if (down_weight == NULL || activated == NULL || output == NULL ||
        row_begin >= row_end ||
        row_end > (size_t)QRT_QWEN36_HIDDEN_SIZE) {
        return 0;
    }

    row = row_begin;
    for (;
         row + 3u < row_end;
         row += 4u) {
        size_t col;
        const uint16_t *down_row0 =
            down_weight + row * (size_t)QRT_QWEN36_MOE_EXPERT_INTERMEDIATE;
        const uint16_t *down_row1 =
            down_weight +
            (row + 1u) * (size_t)QRT_QWEN36_MOE_EXPERT_INTERMEDIATE;
        const uint16_t *down_row2 =
            down_weight +
            (row + 2u) * (size_t)QRT_QWEN36_MOE_EXPERT_INTERMEDIATE;
        const uint16_t *down_row3 =
            down_weight +
            (row + 3u) * (size_t)QRT_QWEN36_MOE_EXPERT_INTERMEDIATE;
        float value0 = 0.0f;
        float value1 = 0.0f;
        float value2 = 0.0f;
        float value3 = 0.0f;
        const float *activated_ptr = activated;
        const uint16_t *down_ptr0 = down_row0;
        const uint16_t *down_ptr1 = down_row1;
        const uint16_t *down_ptr2 = down_row2;
        const uint16_t *down_ptr3 = down_row3;
        for (col = 0u; col < (size_t)QRT_QWEN36_MOE_EXPERT_INTERMEDIATE; ++col) {
            const float activated_value = *activated_ptr++;
            value0 += activated_value * qrt_bf16_to_float_hot(*down_ptr0++);
            value1 += activated_value * qrt_bf16_to_float_hot(*down_ptr1++);
            value2 += activated_value * qrt_bf16_to_float_hot(*down_ptr2++);
            value3 += activated_value * qrt_bf16_to_float_hot(*down_ptr3++);
        }
        if (value0 != value0 || value1 != value1 ||
            value2 != value2 || value3 != value3) {
            return 0;
        }
        output[row + 0u] += (float)((double)scale * (double)value0);
        output[row + 1u] += (float)((double)scale * (double)value1);
        output[row + 2u] += (float)((double)scale * (double)value2);
        output[row + 3u] += (float)((double)scale * (double)value3);
        if (output[row + 0u] != output[row + 0u] ||
            output[row + 1u] != output[row + 1u] ||
            output[row + 2u] != output[row + 2u] ||
            output[row + 3u] != output[row + 3u]) {
            return 0;
        }
    }
    for (; row < row_end; ++row) {
        size_t col;
        const uint16_t *down_row =
            down_weight + row * (size_t)QRT_QWEN36_MOE_EXPERT_INTERMEDIATE;
        float value = 0.0f;
        for (col = 0u; col < (size_t)QRT_QWEN36_MOE_EXPERT_INTERMEDIATE; ++col) {
            value += activated[col] * qrt_bf16_to_float_hot(down_row[col]);
        }
        if (value != value) {
            return 0;
        }
        output[row] += (float)((double)scale * (double)value);
        if (output[row] != output[row]) {
            return 0;
        }
    }

    return 1;
}

