static int qrt_layer0_moe_expert_accumulate_cpu_timed(
    const uint16_t *gate_up_weight,
    const uint16_t *down_weight,
    const float *input,
    float scale,
    float *output,
    uint64_t *gate_up_activation_elapsed_ns,
    uint64_t *gate_up_projection_elapsed_ns,
    uint64_t *activation_elapsed_ns,
    uint64_t *down_projection_elapsed_ns
) {
    float activated[QRT_QWEN36_MOE_EXPERT_INTERMEDIATE];
    float gate_values[QRT_QWEN36_MOE_EXPERT_INTERMEDIATE];
    float up_values[QRT_QWEN36_MOE_EXPERT_INTERMEDIATE];
    size_t inter;
    uint64_t operation_start_ns;
    uint64_t gate_up_activation_start_ns;

    if (gate_up_weight == NULL || down_weight == NULL || input == NULL || output == NULL) {
        return 0;
    }

    gate_up_activation_start_ns = qrt_now_ns();
    operation_start_ns = gate_up_activation_start_ns;
    if (!qrt_layer0_moe_expert_gate_up_projection_block4_cpu(
            gate_up_weight,
            input,
            gate_values,
            up_values
        )) {
        return 0;
    }
    if (gate_up_projection_elapsed_ns != NULL) {
        *gate_up_projection_elapsed_ns +=
            qrt_elapsed_ns(operation_start_ns, qrt_now_ns());
    }

    operation_start_ns = qrt_now_ns();
    for (inter = 0u; inter < (size_t)QRT_QWEN36_MOE_EXPERT_INTERMEDIATE; ++inter) {
        const float gate = gate_values[inter];
        const float up = up_values[inter];
        activated[inter] = (float)((double)gate / (1.0 + exp(-(double)gate))) * up;
        if (activated[inter] != activated[inter]) {
            return 0;
        }
    }
    if (activation_elapsed_ns != NULL) {
        *activation_elapsed_ns +=
            qrt_elapsed_ns(operation_start_ns, qrt_now_ns());
    }
    if (gate_up_activation_elapsed_ns != NULL) {
        *gate_up_activation_elapsed_ns +=
            qrt_elapsed_ns(gate_up_activation_start_ns, qrt_now_ns());
    }

    operation_start_ns = qrt_now_ns();
    if (!qrt_layer0_moe_expert_down_projection_block4_cpu(
            down_weight,
            activated,
            scale,
            output
        )) {
        return 0;
    }
    if (down_projection_elapsed_ns != NULL) {
        *down_projection_elapsed_ns +=
            qrt_elapsed_ns(operation_start_ns, qrt_now_ns());
    }

    return 1;
}

typedef struct qrt_qwen36_moe_expert_kernel_timing_t {
    uint64_t gate_up_activation_elapsed_ns;
    uint64_t gate_up_projection_elapsed_ns;
    uint64_t activation_elapsed_ns;
    uint64_t down_projection_elapsed_ns;
} qrt_qwen36_moe_expert_kernel_timing_t;

static int qrt_qwen36_moe_expert_scalar_kernel(
    const uint16_t *gate_up_weight,
    const uint16_t *down_weight,
    const float *input,
    float scale,
    float *output,
    qrt_qwen36_moe_expert_kernel_timing_t *out_timing
) {
    qrt_qwen36_moe_expert_kernel_timing_t timing;

    memset(&timing, 0, sizeof(timing));
    if (!qrt_layer0_moe_expert_accumulate_cpu_timed(
            gate_up_weight,
            down_weight,
            input,
            scale,
            output,
            &timing.gate_up_activation_elapsed_ns,
            &timing.gate_up_projection_elapsed_ns,
            &timing.activation_elapsed_ns,
            &timing.down_projection_elapsed_ns
        )) {
        return 0;
    }
    if (out_timing != NULL) {
        out_timing->gate_up_activation_elapsed_ns +=
            timing.gate_up_activation_elapsed_ns;
        out_timing->gate_up_projection_elapsed_ns +=
            timing.gate_up_projection_elapsed_ns;
        out_timing->activation_elapsed_ns += timing.activation_elapsed_ns;
        out_timing->down_projection_elapsed_ns +=
            timing.down_projection_elapsed_ns;
    }
    return 1;
}

static int qrt_layer0_moe_expert_accumulate_cpu(
    const uint16_t *gate_up_weight,
    const uint16_t *down_weight,
    const float *input,
    float scale,
    float *output
) {
    return qrt_qwen36_moe_expert_scalar_kernel(
        gate_up_weight,
        down_weight,
        input,
        scale,
        output,
        NULL
    );
}

