typedef struct qrt_win32_prefill_descriptor_batch_early_entry_context_t {
    qrt_engine_t *engine;
    size_t prefill_tokens;
    size_t output_token_capacity;
    qrt_qwen36_prefill_descriptor_batch_result_t continuation_descriptor_result;
    unsigned int continuation_descriptor_result_captured;
} qrt_win32_prefill_descriptor_batch_early_entry_context_t;

static qrt_status_t
qrt_win32_prefill_descriptor_batch_hip_early_entry_continuation(
    const qrt_qwen36_layer1_frontier_buffer_export_t *frontier,
    void *user_data,
    qrt_qwen36_layer1_frontier_continuation_result_t *out_result
) {
    qrt_win32_prefill_descriptor_batch_early_entry_context_t *context =
        (qrt_win32_prefill_descriptor_batch_early_entry_context_t *)user_data;
    qrt_qwen36_prefill_descriptor_batch_result_t descriptor_batch_result;
    uint64_t continuation_start_ns;
    uint64_t continuation_execute_start_ns;
    uint64_t continuation_execute_elapsed_ns;
    uint64_t report_store_start_ns;
    uint64_t report_store_elapsed_ns;
    uint64_t continuation_elapsed_ns;
    int continuation_ok;
    qrt_status_t status;

    if (context == NULL || context->engine == NULL || frontier == NULL ||
        out_result == NULL) {
        return QRT_STATUS_INVALID_ARGUMENT;
    }
    memset(out_result, 0, sizeof(*out_result));
    memset(&descriptor_batch_result, 0, sizeof(descriptor_batch_result));

    status = qrt_engine_store_baseline_product_q8192_frontier_export(
        context->engine,
        frontier,
        context->prefill_tokens,
        1u
    );
    if (status != QRT_STATUS_OK) {
        qrt_engine_set_token_request_failure(
            context->engine,
            "prefill_descriptor_batch_early_frontier_store",
            "early-entry frontier export could not be stored in the resident report"
        );
        return status;
    }

    context->engine
        ->baseline_product_q8192_layer1_frontier_continuation_attached = 1u;
    context->engine
        ->baseline_product_q8192_layer1_frontier_continuation_attempted = 1u;
    continuation_start_ns = qrt_now_ns();
    continuation_execute_start_ns = qrt_now_ns();
    continuation_ok = qrt_win32_prefill_descriptor_batch_hip_execute(
        context->engine,
        frontier,
        context->prefill_tokens,
        QRT_QWEN36_PREFILL_DESCRIPTOR_BATCH_FLAG_NONE,
        NULL,
        0u,
        context->output_token_capacity,
        &descriptor_batch_result
    );
    continuation_execute_elapsed_ns =
        qrt_elapsed_ns(continuation_execute_start_ns, qrt_now_ns());
    descriptor_batch_result.timing
        .descriptor_c_continuation_execute_wall_clock_ns =
        continuation_execute_elapsed_ns;
    report_store_start_ns = qrt_now_ns();
    status = continuation_ok ? QRT_STATUS_OK : QRT_STATUS_UNSUPPORTED;
    context->engine
        ->baseline_product_q8192_layer1_frontier_continuation_status = status;
    context->engine
        ->baseline_product_q8192_layer1_frontier_descriptor_batch_digest_fnv1a64 =
        descriptor_batch_result.descriptor_batch_digest_fnv1a64;
    qrt_engine_store_baseline_product_q8192_descriptor_batch_timing(
        context->engine,
        &descriptor_batch_result
    );
    (void)snprintf(
        context->engine
            ->baseline_product_q8192_layer1_frontier_descriptor_batch_missing_field,
        sizeof(context->engine
                   ->baseline_product_q8192_layer1_frontier_descriptor_batch_missing_field),
        "%s",
        descriptor_batch_result.first_missing_runtime_context_field
    );
    (void)snprintf(
        context->engine
            ->baseline_product_q8192_layer1_frontier_descriptor_batch_failure_stage,
        sizeof(context->engine
                   ->baseline_product_q8192_layer1_frontier_descriptor_batch_failure_stage),
        "%s",
        descriptor_batch_result.failure_stage
    );
    (void)snprintf(
        context->engine
            ->baseline_product_q8192_layer1_frontier_descriptor_batch_failure,
        sizeof(context->engine
            ->baseline_product_q8192_layer1_frontier_descriptor_batch_failure),
        "%s",
        descriptor_batch_result.failure
    );
    report_store_elapsed_ns =
        qrt_elapsed_ns(report_store_start_ns, qrt_now_ns());
    descriptor_batch_result.timing
        .descriptor_c_continuation_report_store_wall_clock_ns =
        report_store_elapsed_ns;
    context->engine
        ->baseline_product_q8192_layer1_frontier_descriptor_batch_timing
        .descriptor_c_continuation_execute_wall_clock_ns =
        continuation_execute_elapsed_ns;
    context->engine
        ->baseline_product_q8192_layer1_frontier_descriptor_batch_timing
        .descriptor_c_continuation_report_store_wall_clock_ns =
        report_store_elapsed_ns;
    continuation_elapsed_ns = qrt_elapsed_ns(continuation_start_ns, qrt_now_ns());
    context->engine
        ->baseline_product_q8192_layer1_frontier_continuation_elapsed_ns =
        continuation_elapsed_ns;
    descriptor_batch_result.timing
        .descriptor_c_continuation_total_wall_clock_ns =
        continuation_elapsed_ns;
    context->engine
        ->baseline_product_q8192_layer1_frontier_descriptor_batch_timing
        .descriptor_c_continuation_total_wall_clock_ns =
        continuation_elapsed_ns;
    context->engine
        ->baseline_product_q8192_layer1_frontier_continuation_digest_fnv1a64 =
        descriptor_batch_result.continuation.digest_fnv1a64;
    context->engine
        ->baseline_product_q8192_layer1_frontier_continuation_completed =
        continuation_ok && descriptor_batch_result.completed != 0u ? 1u : 0u;
    context->continuation_descriptor_result = descriptor_batch_result;
    context->continuation_descriptor_result_captured = 1u;

    if (!continuation_ok || descriptor_batch_result.completed == 0u) {
        return status;
    }
    *out_result = descriptor_batch_result.continuation;
    return QRT_STATUS_OK;
}

static int qrt_win32_prefill_descriptor_batch_hip_execute(
    qrt_engine_t *engine,
    const qrt_qwen36_layer1_frontier_buffer_export_t *frontier,
    size_t prefill_tokens,
    uint32_t flags,
    const uint32_t *input_tokens,
    size_t input_token_count,
    size_t output_token_capacity,
    qrt_qwen36_prefill_descriptor_batch_result_t *out_result
) {
    qrt_qwen36_prefill_descriptor_batch_request_t request;
    qrt_win32_prefill_descriptor_batch_early_entry_context_t
        early_entry_context;

    if (out_result != NULL) {
        memset(out_result, 0, sizeof(*out_result));
    }
    if (engine == NULL || out_result == NULL || engine->model_path == NULL ||
        !engine->prefill_descriptor_batch_hip_requested) {
        return 0;
    }
    if ((flags & QRT_QWEN36_PREFILL_DESCRIPTOR_BATCH_FLAG_EARLY_ENTRY) == 0u &&
        frontier == NULL) {
        return 0;
    }
    if (!qrt_win32_prefill_descriptor_batch_hip_backend_load(engine) ||
        engine->prefill_descriptor_batch_hip_run == NULL) {
        return 0;
    }

    memset(&request, 0, sizeof(request));
    memset(&early_entry_context, 0, sizeof(early_entry_context));
    request.frontier = frontier;
    request.model_dir = engine->model_path;
    request.resident_engine = engine;
    request.prefill_tokens = prefill_tokens;
    request.flags = flags;
    request.input_tokens = input_tokens;
    request.input_token_count = input_token_count;
    request.prefix_cache_state_attached =
        engine->prefix_cache_state_attached ? 1u : 0u;
    request.prefix_cache_cached_prefix_tokens =
        engine->prefix_cache_cached_prefix_tokens;
    request.prefix_cache_suffix_tokens = engine->prefix_cache_suffix_tokens;
    request.prefix_cache_executed_input_tokens =
        engine->prefix_cache_executed_input_tokens;
    request.prefix_cache_output_token_capacity =
        engine->prefix_cache_output_token_capacity;
    request.output_token_capacity = output_token_capacity;
    request.prefix_cache_state_digest_fnv1a64 =
        engine->prefix_cache_state_digest_fnv1a64;
    request.prefix_cache_position_digest_fnv1a64 =
        engine->prefix_cache_position_digest_fnv1a64;
    if ((flags & QRT_QWEN36_PREFILL_DESCRIPTOR_BATCH_FLAG_EARLY_ENTRY) != 0u) {
        early_entry_context.engine = engine;
        early_entry_context.prefill_tokens = prefill_tokens;
        early_entry_context.output_token_capacity = output_token_capacity;
        request.early_entry_continuation_callback =
            qrt_win32_prefill_descriptor_batch_hip_early_entry_continuation;
        request.early_entry_continuation_user_data = &early_entry_context;
    }

    if (!engine->prefill_descriptor_batch_hip_run(&request, out_result)) {
        (void)snprintf(
            engine->prefill_descriptor_batch_hip_failure,
            sizeof(engine->prefill_descriptor_batch_hip_failure),
            "%s",
            out_result->failure[0] != '\0'
                ? out_result->failure
                : "prefill descriptor batch HIP run failed"
        );
        return 0;
    }
    if ((flags & QRT_QWEN36_PREFILL_DESCRIPTOR_BATCH_FLAG_EARLY_ENTRY) != 0u &&
        early_entry_context.continuation_descriptor_result_captured != 0u) {
        const qrt_qwen36_prefill_descriptor_batch_result_t *continuation =
            &early_entry_context.continuation_descriptor_result;
        qrt_qwen36_prefill_descriptor_batch_result_t early_entry_frontier =
            *out_result;
        *out_result = *continuation;
        out_result->wall_clock_ns = early_entry_frontier.wall_clock_ns;
        out_result->layer1_frontier_token_count =
            early_entry_frontier.layer1_frontier_token_count;
        out_result->layer1_frontier_source_window_token_count =
            early_entry_frontier.layer1_frontier_source_window_token_count;
        out_result->layer1_frontier_hidden_value_count =
            early_entry_frontier.layer1_frontier_hidden_value_count;
        out_result->layer1_frontier_token_ids_fnv1a64 =
            early_entry_frontier.layer1_frontier_token_ids_fnv1a64;
        out_result->layer1_frontier_source_window_token_ids_fnv1a64 =
            early_entry_frontier.layer1_frontier_source_window_token_ids_fnv1a64;
        out_result->layer1_frontier_hidden_values_fnv1a64 =
            early_entry_frontier.layer1_frontier_hidden_values_fnv1a64;
        out_result->layer1_frontier_digest_fnv1a64 =
            early_entry_frontier.layer1_frontier_digest_fnv1a64;
        out_result->layer1_frontier_last_output_fnv1a64 =
            early_entry_frontier.layer1_frontier_last_output_fnv1a64;
        out_result->layer1_frontier_product_path =
            early_entry_frontier.layer1_frontier_product_path;
        out_result->layer1_frontier_layer0_source_stage_count =
            early_entry_frontier.layer1_frontier_layer0_source_stage_count;
        memcpy(
            out_result->layer1_frontier_layer0_source_stage_token_counts,
            early_entry_frontier
                .layer1_frontier_layer0_source_stage_token_counts,
            sizeof(out_result
                       ->layer1_frontier_layer0_source_stage_token_counts)
        );
        memcpy(
            out_result->layer1_frontier_layer0_source_stage_digest_fnv1a64,
            early_entry_frontier
                .layer1_frontier_layer0_source_stage_digest_fnv1a64,
            sizeof(out_result
                       ->layer1_frontier_layer0_source_stage_digest_fnv1a64)
        );
        memcpy(
            out_result->layer1_frontier_layer0_source_stage_last_fnv1a64,
            early_entry_frontier
                .layer1_frontier_layer0_source_stage_last_fnv1a64,
            sizeof(out_result
                       ->layer1_frontier_layer0_source_stage_last_fnv1a64)
        );
        out_result->layer1_frontier_stage_count =
            early_entry_frontier.layer1_frontier_stage_count;
        memcpy(
            out_result->layer1_frontier_stage_token_counts,
            early_entry_frontier.layer1_frontier_stage_token_counts,
            sizeof(out_result->layer1_frontier_stage_token_counts)
        );
        memcpy(
            out_result->layer1_frontier_stage_digest_fnv1a64,
            early_entry_frontier.layer1_frontier_stage_digest_fnv1a64,
            sizeof(out_result->layer1_frontier_stage_digest_fnv1a64)
        );
        memcpy(
            out_result->layer1_frontier_stage_last_fnv1a64,
            early_entry_frontier.layer1_frontier_stage_last_fnv1a64,
            sizeof(out_result->layer1_frontier_stage_last_fnv1a64)
        );
        out_result->early_entry_resident_engine_reused =
            early_entry_frontier.early_entry_resident_engine_reused;
        out_result->early_entry_scratch_engine_created =
            early_entry_frontier.early_entry_scratch_engine_created;
        out_result->early_entry_engine_context_elapsed_ns =
            early_entry_frontier.early_entry_engine_context_elapsed_ns;
        out_result->output_token_capacity =
            continuation->output_token_capacity;
        out_result->output_token_count = continuation->output_token_count;
        memcpy(
            out_result->output_tokens,
            continuation->output_tokens,
            sizeof(out_result->output_tokens)
        );
        out_result->output_tokens_fnv1a64 =
            continuation->output_tokens_fnv1a64;
        out_result->output_head_input_hidden_fnv1a64 =
            continuation->output_head_input_hidden_fnv1a64;
        out_result->output_sequence_elapsed_ns =
            continuation->output_sequence_elapsed_ns;
        out_result->output_sequence_tpot_elapsed_ns =
            continuation->output_sequence_tpot_elapsed_ns;
        out_result->output_sequence_tpot_sample_count =
            continuation->output_sequence_tpot_sample_count;
        out_result->output_sequence_prefill_sample_count =
            continuation->output_sequence_prefill_sample_count;
        out_result->output_sequence_decode_token_count =
            continuation->output_sequence_decode_token_count;
        out_result->output_sequence_autoregressive_decode =
            continuation->output_sequence_autoregressive_decode;
        out_result->output_sequence_decode_state_exported =
            continuation->output_sequence_decode_state_exported;
        (void)snprintf(
            out_result->output_sequence_decode_missing_field,
            sizeof(out_result->output_sequence_decode_missing_field),
            "%s",
            continuation->output_sequence_decode_missing_field
        );
        out_result->output_sequence_decode_state_digest_fnv1a64 =
            continuation->output_sequence_decode_state_digest_fnv1a64;
        out_result->output_sequence_decode_state_token_count =
            continuation->output_sequence_decode_state_token_count;
        out_result->output_sequence_decode_state_position =
            continuation->output_sequence_decode_state_position;
        out_result->output_sequence_decode_state_token_id =
            continuation->output_sequence_decode_state_token_id;
        out_result->output_sequence_decode_state_token_loop_digest_fnv1a64 =
            continuation
                ->output_sequence_decode_state_token_loop_digest_fnv1a64;
        out_result
            ->output_sequence_decode_state_output_head_input_hidden_fnv1a64 =
            continuation
                ->output_sequence_decode_state_output_head_input_hidden_fnv1a64;
        out_result->output_sequence_decode_state_prefix_state_digest_fnv1a64 =
            continuation
                ->output_sequence_decode_state_prefix_state_digest_fnv1a64;
        out_result
            ->output_sequence_decode_state_prefix_position_digest_fnv1a64 =
            continuation
                ->output_sequence_decode_state_prefix_position_digest_fnv1a64;
        out_result->output_sequence_decode_state_cache_payload_exported =
            continuation->output_sequence_decode_state_cache_payload_exported;
        out_result
            ->output_sequence_decode_state_cache_payload_digest_fnv1a64 =
            continuation
                ->output_sequence_decode_state_cache_payload_digest_fnv1a64;
        out_result->output_sequence_decode_state_cache_layer_count =
            continuation->output_sequence_decode_state_cache_layer_count;
        out_result->output_sequence_decode_state_cache_token_count =
            continuation->output_sequence_decode_state_cache_token_count;
    }
    if (out_result->completed == 0u) {
        (void)snprintf(
            engine->prefill_descriptor_batch_hip_failure,
            sizeof(engine->prefill_descriptor_batch_hip_failure),
            "%s",
            out_result->failure[0] != '\0'
                ? out_result->failure
                : "prefill descriptor batch HIP run did not complete"
        );
        return 0;
    }
    return 1;
}

static qrt_status_t qrt_qwen36_try_direct_descriptor_batch_prefill_request(
    qrt_engine_t *engine,
    const uint32_t *input_tokens,
    size_t input_token_count,
    uint32_t *output_tokens,
    size_t output_token_capacity,
    size_t *out_output_token_count,
    uint64_t request_start_ns,
    int *out_handled
) {
    qrt_qwen36_prefill_descriptor_batch_result_t early_entry_result;
    unsigned int descriptor_path_required;
    uint64_t early_entry_start_ns;
    uint64_t elapsed_ns;
    uint64_t first_output_elapsed_ns;
    int early_entry_ok;

    if (out_handled != NULL) {
        *out_handled = 0;
    }
    if (engine == NULL || input_tokens == NULL || output_tokens == NULL ||
        out_output_token_count == NULL || out_handled == NULL) {
        return QRT_STATUS_INVALID_ARGUMENT;
    }
    if (!engine->prefill_descriptor_batch_hip_requested ||
        engine->prefix_cache_state_attached) {
        return QRT_STATUS_OK;
    }
    descriptor_path_required =
        engine->qwen36_descriptor_request_path_required ? 1u : 0u;
    if (engine->prefill_descriptor_batch_skip_early_entry ||
        output_token_capacity != 1u) {
        if (descriptor_path_required == 0u) {
            return QRT_STATUS_OK;
        }
        const char *failure_stage =
            engine->prefill_descriptor_batch_skip_early_entry
                ? "prefill_descriptor_batch_early_entry_disabled"
                : "prefill_descriptor_batch_direct_decode_missing";
        const char *failure =
            engine->prefill_descriptor_batch_skip_early_entry
                ? "required descriptor request path cannot fall back to the scalar request loop when direct HIP early entry is disabled"
                : "required cold descriptor request path is wired for single-token TTFT; helper-owned cold autoregressive decode must be added before requesting multiple output tokens";
        *out_handled = 1;
        qrt_engine_set_token_request_failure(
            engine,
            failure_stage,
            failure
        );
        elapsed_ns = qrt_elapsed_ns(request_start_ns, qrt_now_ns());
        engine->last_request_elapsed_ns = elapsed_ns;
        engine->request_elapsed_ns += elapsed_ns;
        if (engine->request_count == 1u) {
            engine->first_request_elapsed_ns = elapsed_ns;
        }
        return QRT_STATUS_UNSUPPORTED;
    }

    *out_handled = (int)descriptor_path_required;
    memset(&early_entry_result, 0, sizeof(early_entry_result));
    engine->baseline_product_q8192_prefill_descriptor_batch_early_entry_attempted =
        1u;
    early_entry_start_ns = qrt_now_ns();
    early_entry_ok = qrt_win32_prefill_descriptor_batch_hip_execute(
        engine,
        NULL,
        input_token_count,
        QRT_QWEN36_PREFILL_DESCRIPTOR_BATCH_FLAG_EARLY_ENTRY,
        input_tokens,
        input_token_count,
        output_token_capacity,
        &early_entry_result
    );
    if (!early_entry_ok && early_entry_result.failure_stage[0] == '\0' &&
        engine->prefill_descriptor_batch_hip_failure[0] != '\0') {
        (void)snprintf(
            early_entry_result.failure_stage,
            sizeof(early_entry_result.failure_stage),
            "%s",
            "prefill_descriptor_batch_hip_load"
        );
        (void)snprintf(
            early_entry_result.failure,
            sizeof(early_entry_result.failure),
            "%s",
            engine->prefill_descriptor_batch_hip_failure
        );
    }

    engine->baseline_product_q8192_prefill_descriptor_batch_early_entry_status =
        early_entry_ok ? QRT_STATUS_OK : QRT_STATUS_UNSUPPORTED;
    engine
        ->baseline_product_q8192_prefill_descriptor_batch_early_entry_completed =
        early_entry_ok && early_entry_result.completed != 0u ? 1u : 0u;
    engine->baseline_product_q8192_prefill_descriptor_batch_early_entry_elapsed_ns =
        qrt_elapsed_ns(early_entry_start_ns, qrt_now_ns());
    engine
        ->baseline_product_q8192_prefill_descriptor_batch_early_entry_digest_fnv1a64 =
        early_entry_result.descriptor_batch_digest_fnv1a64;
    engine
        ->baseline_product_q8192_prefill_descriptor_batch_early_entry_resident_engine_reused =
        early_entry_result.early_entry_resident_engine_reused;
    engine
        ->baseline_product_q8192_prefill_descriptor_batch_early_entry_scratch_engine_created =
        early_entry_result.early_entry_scratch_engine_created;
    engine
        ->baseline_product_q8192_prefill_descriptor_batch_early_entry_engine_context_elapsed_ns =
        early_entry_result.early_entry_engine_context_elapsed_ns;
    (void)snprintf(
        engine
            ->baseline_product_q8192_prefill_descriptor_batch_early_entry_missing_field,
        sizeof(engine
                   ->baseline_product_q8192_prefill_descriptor_batch_early_entry_missing_field),
        "%s",
        early_entry_result.first_missing_runtime_context_field
    );
    (void)snprintf(
        engine
            ->baseline_product_q8192_prefill_descriptor_batch_early_entry_failure_stage,
        sizeof(engine
                   ->baseline_product_q8192_prefill_descriptor_batch_early_entry_failure_stage),
        "%s",
        early_entry_result.failure_stage
    );
    (void)snprintf(
        engine
            ->baseline_product_q8192_prefill_descriptor_batch_early_entry_failure,
        sizeof(engine
                   ->baseline_product_q8192_prefill_descriptor_batch_early_entry_failure),
        "%s",
        early_entry_result.failure
    );

    if (early_entry_ok && early_entry_result.completed != 0u) {
        engine
            ->baseline_product_q8192_layer1_frontier_descriptor_batch_digest_fnv1a64 =
            early_entry_result.descriptor_batch_digest_fnv1a64;
        qrt_engine_store_baseline_product_q8192_descriptor_batch_timing(
            engine,
            &early_entry_result
        );
        (void)snprintf(
            engine
                ->baseline_product_q8192_layer1_frontier_descriptor_batch_missing_field,
            sizeof(engine
                       ->baseline_product_q8192_layer1_frontier_descriptor_batch_missing_field),
            "%s",
            early_entry_result.first_missing_runtime_context_field
        );
        (void)snprintf(
            engine
                ->baseline_product_q8192_layer1_frontier_descriptor_batch_failure_stage,
            sizeof(engine
                       ->baseline_product_q8192_layer1_frontier_descriptor_batch_failure_stage),
            "%s",
            early_entry_result.failure_stage
        );
        (void)snprintf(
            engine
                ->baseline_product_q8192_layer1_frontier_descriptor_batch_failure,
            sizeof(engine
                       ->baseline_product_q8192_layer1_frontier_descriptor_batch_failure),
            "%s",
            early_entry_result.failure
        );
        engine->baseline_product_q8192_layer1_frontier_continuation_attached =
            1u;
        engine->baseline_product_q8192_layer1_frontier_continuation_attempted =
            1u;
        engine->baseline_product_q8192_layer1_frontier_continuation_status =
            QRT_STATUS_OK;
        engine->baseline_product_q8192_layer1_frontier_continuation_elapsed_ns =
            early_entry_result.wall_clock_ns;
        engine
            ->baseline_product_q8192_layer1_frontier_continuation_digest_fnv1a64 =
            early_entry_result.continuation.digest_fnv1a64;
        engine->baseline_product_q8192_layer1_frontier_continuation_completed =
            early_entry_result.continuation.output_token_emitted != 0u ? 1u
                                                                       : 0u;
        if (early_entry_result.layer1_frontier_product_path != 0u &&
            early_entry_result.layer1_frontier_token_count > 0u &&
            early_entry_result.layer1_frontier_hidden_value_count ==
                early_entry_result.layer1_frontier_token_count *
                    (size_t)QRT_QWEN36_HIDDEN_SIZE &&
            early_entry_result.layer1_frontier_digest_fnv1a64 != UINT64_C(0)) {
            engine->baseline_product_q8192_layer1_frontier_context_token_count =
                input_token_count;
            engine->baseline_product_q8192_layer1_frontier_context_match = 1u;
            engine->baseline_product_q8192_layer1_frontier_token_count =
                early_entry_result.layer1_frontier_token_count;
            engine
                ->baseline_product_q8192_layer1_frontier_source_window_token_count =
                early_entry_result.layer1_frontier_source_window_token_count;
            engine->baseline_product_q8192_layer1_frontier_hidden_value_count =
                early_entry_result.layer1_frontier_hidden_value_count;
            engine->baseline_product_q8192_layer1_frontier_token_ids_fnv1a64 =
                early_entry_result.layer1_frontier_token_ids_fnv1a64;
            engine
                ->baseline_product_q8192_layer1_frontier_source_window_token_ids_fnv1a64 =
                early_entry_result.layer1_frontier_source_window_token_ids_fnv1a64;
            engine
                ->baseline_product_q8192_layer1_frontier_buffer_hidden_values_fnv1a64 =
                early_entry_result.layer1_frontier_hidden_values_fnv1a64;
            engine->baseline_product_q8192_layer1_frontier_digest_fnv1a64 =
                early_entry_result.layer1_frontier_digest_fnv1a64;
            engine->baseline_product_q8192_layer1_frontier_last_output_fnv1a64 =
                early_entry_result.layer1_frontier_last_output_fnv1a64;
            engine
                ->baseline_product_q8192_layer1_frontier_linear_core_state_reset =
                0u;
            engine->baseline_product_q8192_layer1_frontier_output_head_skipped =
                0u;
            engine->baseline_product_q8192_layer1_frontier_complete = 1u;
            engine->baseline_product_q8192_layer1_frontier_product_path = 1u;
            engine->baseline_product_q8192_layer0_source_stage_count =
                early_entry_result.layer1_frontier_layer0_source_stage_count;
            memcpy(
                engine->baseline_product_q8192_layer0_source_stage_token_counts,
                early_entry_result
                    .layer1_frontier_layer0_source_stage_token_counts,
                sizeof(engine
                           ->baseline_product_q8192_layer0_source_stage_token_counts)
            );
            memcpy(
                engine->baseline_product_q8192_layer0_source_stage_digest_fnv1a64,
                early_entry_result
                    .layer1_frontier_layer0_source_stage_digest_fnv1a64,
                sizeof(engine
                           ->baseline_product_q8192_layer0_source_stage_digest_fnv1a64)
            );
            memcpy(
                engine->baseline_product_q8192_layer0_source_stage_last_fnv1a64,
                early_entry_result
                    .layer1_frontier_layer0_source_stage_last_fnv1a64,
                sizeof(engine
                           ->baseline_product_q8192_layer0_source_stage_last_fnv1a64)
            );
            engine->baseline_product_q8192_layer1_frontier_stage_count =
                early_entry_result.layer1_frontier_stage_count;
            memcpy(
                engine->baseline_product_q8192_layer1_frontier_stage_token_counts,
                early_entry_result.layer1_frontier_stage_token_counts,
                sizeof(engine
                           ->baseline_product_q8192_layer1_frontier_stage_token_counts)
            );
            memcpy(
                engine->baseline_product_q8192_layer1_frontier_stage_digest_fnv1a64,
                early_entry_result.layer1_frontier_stage_digest_fnv1a64,
                sizeof(engine
                           ->baseline_product_q8192_layer1_frontier_stage_digest_fnv1a64)
            );
            memcpy(
                engine->baseline_product_q8192_layer1_frontier_stage_last_fnv1a64,
                early_entry_result.layer1_frontier_stage_last_fnv1a64,
                sizeof(engine
                           ->baseline_product_q8192_layer1_frontier_stage_last_fnv1a64)
            );
        }
    }

    if (!early_entry_ok || early_entry_result.completed == 0u ||
        early_entry_result.continuation.output_token_emitted == 0u ||
        early_entry_result.continuation.output_token_id >=
            (uint32_t)QRT_QWEN36_VOCAB_SIZE) {
        if (descriptor_path_required == 0u) {
            return QRT_STATUS_OK;
        }
        qrt_engine_set_token_request_failure(
            engine,
            early_entry_result.failure_stage[0] != '\0'
                ? early_entry_result.failure_stage
                : "prefill_descriptor_batch_early_entry",
            early_entry_result.failure[0] != '\0'
                ? early_entry_result.failure
                : "direct descriptor-batch request prefill did not emit a token"
        );
        elapsed_ns = qrt_elapsed_ns(request_start_ns, qrt_now_ns());
        engine->last_request_elapsed_ns = elapsed_ns;
        engine->request_elapsed_ns += elapsed_ns;
        if (engine->request_count == 1u) {
            engine->first_request_elapsed_ns = elapsed_ns;
        }
        return QRT_STATUS_UNSUPPORTED;
    }

    *out_handled = 1;
    output_tokens[0] = early_entry_result.continuation.output_token_id;
    *out_output_token_count = 1u;
    engine->baseline_product_q8192_layer1_frontier_output_head_skipped = 0u;
    engine->baseline_output_head_token_emitted = 1;
    engine->baseline_output_head_sampled_token_id =
        early_entry_result.continuation.output_token_id;
    memset(
        engine->baseline_output_head_topk_token_ids,
        0,
        sizeof(engine->baseline_output_head_topk_token_ids)
    );
    memset(
        engine->baseline_output_head_topk_logits,
        0,
        sizeof(engine->baseline_output_head_topk_logits)
    );
    engine->baseline_output_head_topk_token_ids[0] =
        early_entry_result.continuation.output_token_id;
    engine->baseline_output_head_topk_logits[0] =
        early_entry_result.continuation.output_logit;
    engine->baseline_output_head_logits_fnv1a64 =
        early_entry_result.continuation.lm_head_logits_fnv1a64;
    engine->baseline_output_head_sampler_fnv1a64 =
        early_entry_result.continuation.sampler_fnv1a64;
    engine->baseline_output_head_input_hidden_fnv1a64 =
        early_entry_result.output_head_input_hidden_fnv1a64;
    engine->last_request_descriptor_output_prefill_sample_count =
        early_entry_result.output_sequence_prefill_sample_count;
    engine->last_request_descriptor_output_decode_token_count =
        early_entry_result.output_sequence_decode_token_count;
    engine->last_request_descriptor_output_autoregressive_decode =
        early_entry_result.output_sequence_autoregressive_decode;
    engine->last_request_descriptor_decode_state_exported =
        early_entry_result.output_sequence_decode_state_exported;
    (void)snprintf(
        engine->last_request_descriptor_decode_missing_field,
        sizeof(engine->last_request_descriptor_decode_missing_field),
        "%s",
        early_entry_result.output_sequence_decode_missing_field
    );
    engine->last_request_descriptor_decode_state_digest_fnv1a64 =
        early_entry_result.output_sequence_decode_state_digest_fnv1a64;
    engine->last_request_descriptor_decode_state_token_count =
        early_entry_result.output_sequence_decode_state_token_count;
    engine->last_request_descriptor_decode_state_position =
        early_entry_result.output_sequence_decode_state_position;
    engine->last_request_descriptor_decode_state_token_id =
        early_entry_result.output_sequence_decode_state_token_id;
    engine->last_request_descriptor_decode_state_token_loop_digest_fnv1a64 =
        early_entry_result.output_sequence_decode_state_token_loop_digest_fnv1a64;
    engine
        ->last_request_descriptor_decode_state_output_head_input_hidden_fnv1a64 =
        early_entry_result
            .output_sequence_decode_state_output_head_input_hidden_fnv1a64;
    engine->last_request_descriptor_decode_state_prefix_state_digest_fnv1a64 =
        early_entry_result.output_sequence_decode_state_prefix_state_digest_fnv1a64;
    engine
        ->last_request_descriptor_decode_state_prefix_position_digest_fnv1a64 =
        early_entry_result
            .output_sequence_decode_state_prefix_position_digest_fnv1a64;
    engine->last_request_descriptor_decode_state_cache_payload_exported =
        early_entry_result.output_sequence_decode_state_cache_payload_exported;
    engine->last_request_descriptor_decode_state_cache_payload_digest_fnv1a64 =
        early_entry_result.output_sequence_decode_state_cache_payload_digest_fnv1a64;
    engine->last_request_descriptor_decode_state_cache_layer_count =
        early_entry_result.output_sequence_decode_state_cache_layer_count;
    engine->last_request_descriptor_decode_state_cache_token_count =
        early_entry_result.output_sequence_decode_state_cache_token_count;
    engine->last_request_descriptor_decode_input_surface_exported =
        early_entry_result.output_sequence_decode_input_surface_exported;
    engine->last_request_descriptor_decode_input_surface_digest_fnv1a64 =
        early_entry_result.output_sequence_decode_input_surface_digest_fnv1a64;
    engine->last_request_descriptor_decode_input_surface_token_embedding_fnv1a64 =
        early_entry_result
            .output_sequence_decode_input_surface_token_embedding_fnv1a64;
    engine->last_request_descriptor_decode_input_surface_token_count =
        early_entry_result.output_sequence_decode_input_surface_token_count;
    engine->last_request_descriptor_decode_input_surface_position =
        early_entry_result.output_sequence_decode_input_surface_position;
    engine->last_request_descriptor_decode_input_surface_token_id =
        early_entry_result.output_sequence_decode_input_surface_token_id;
    engine
        ->last_request_descriptor_decode_input_surface_cache_payload_digest_fnv1a64 =
        early_entry_result
            .output_sequence_decode_input_surface_cache_payload_digest_fnv1a64;

    first_output_elapsed_ns = qrt_elapsed_ns(request_start_ns, qrt_now_ns());
    engine->last_request_ttft_elapsed_ns = first_output_elapsed_ns;
    engine->last_request_tpot_elapsed_ns = UINT64_C(0);
    engine->last_request_tpot_sample_count = 0u;
    engine->last_request_output_token_count = 1u;
    engine->baseline_prompt_context_token_count = input_token_count;
    engine->baseline_prompt_state_position = input_token_count - 1u;
    engine->baseline_prompt_last_input_token = input_tokens[input_token_count - 1u];
    engine->baseline_prompt_state_sequence_token_loop = 0u;
    engine->baseline_prompt_state_full_sequence_prefill = 1u;
    engine->baseline_prompt_sequence_processed_token_count = input_token_count;
    engine->baseline_prompt_sequence_digest_fnv1a64 =
        early_entry_result.descriptor_batch_digest_fnv1a64;
    engine->baseline_prompt_sequence_elapsed_ns =
        early_entry_result.wall_clock_ns;
    engine->baseline_request_handoff_request_digest_fnv1a64 =
        early_entry_result.descriptor_batch_digest_fnv1a64;
    engine->baseline_request_handoff_last_input_token_count = input_token_count;
    engine->baseline_request_handoff_last_output_token_capacity =
        output_token_capacity;
    engine->baseline_request_handoff_last_input_token =
        input_tokens[input_token_count - 1u];
    engine->qwen36_layer_descriptor_helper_applied = 1;
    engine->qwen36_layer_descriptor_helper_fnv1a64 =
        early_entry_result.descriptor_batch_digest_fnv1a64;
    engine->qwen36_layer_descriptor_helper_layer_count =
        (size_t)QRT_QWEN36_LAYER_COUNT;
    engine->qwen36_layer_descriptor_helper_elapsed_ns +=
        engine
            ->baseline_product_q8192_prefill_descriptor_batch_early_entry_elapsed_ns;

    elapsed_ns = qrt_elapsed_ns(request_start_ns, qrt_now_ns());
    engine->last_request_elapsed_ns = elapsed_ns;
    engine->request_elapsed_ns += elapsed_ns;
    if (engine->request_count == 1u) {
        engine->first_request_elapsed_ns = elapsed_ns;
    }
    return QRT_STATUS_OK;
}

static void qrt_win32_prefill_descriptor_batch_decode_set_failure(
    qrt_qwen36_prefill_descriptor_batch_decode_result_t *result,
    const char *missing_field,
    const char *failure_stage,
    const char *failure
) {
    if (result == NULL) {
        return;
    }
    (void)snprintf(
        result->first_missing_runtime_context_field,
        sizeof(result->first_missing_runtime_context_field),
        "%s",
        missing_field != NULL ? missing_field : ""
    );
    (void)snprintf(
        result->output_sequence_decode_missing_field,
        sizeof(result->output_sequence_decode_missing_field),
        "%s",
        missing_field != NULL ? missing_field : ""
    );
    (void)snprintf(
        result->failure_stage,
        sizeof(result->failure_stage),
        "%s",
        failure_stage != NULL ? failure_stage : ""
    );
    (void)snprintf(
        result->failure,
        sizeof(result->failure),
        "%s",
        failure != NULL ? failure : ""
    );
}

static int qrt_qwen36_descriptor_decode_cache_payload_view_attach(
    const qrt_qwen36_plain_sequence_state_t *state,
    const qrt_qwen36_prefill_descriptor_batch_result_t *prefill_result,
    qrt_qwen36_prefill_descriptor_batch_decode_request_t *request
) {
    qrt_qwen36_decode_cache_payload_view_t *view;
    const qrt_qwen36_baseline_plan_t *plan;
    const size_t linear_ring_elements =
        (size_t)QRT_QWEN36_LAYER0_LINEAR_ATTN_CONV_KERNEL *
        (size_t)QRT_QWEN36_LAYER0_LINEAR_ATTN_QKV_ROWS;
    const size_t linear_core_state_elements =
        (size_t)QRT_QWEN36_LAYER0_LINEAR_ATTN_VALUE_FEATURES *
        (size_t)QRT_QWEN36_LAYER0_LINEAR_ATTN_KEY_DIM;
    const size_t full_kv_token_elements =
        (size_t)QRT_QWEN36_LAYER3_SELF_ATTN_KV_TOKEN_FEATURES;
    const size_t full_kv_window_elements =
        (size_t)QRT_PREFIX_CACHE_FULL_KV_WINDOW_TOKENS *
        full_kv_token_elements;
    uint64_t view_digest;
    size_t layer_index;

    if (state == NULL || prefill_result == NULL || request == NULL ||
        prefill_result->output_sequence_decode_state_cache_payload_exported ==
            0u ||
        prefill_result->output_sequence_decode_state_cache_payload_digest_fnv1a64 ==
            UINT64_C(0) ||
        prefill_result->output_sequence_decode_state_cache_layer_count !=
            (size_t)QRT_QWEN36_LAYER_COUNT ||
        prefill_result->output_sequence_decode_state_cache_token_count == 0u ||
        state->prefix_full_kv_compressed_enabled == 0u ||
        state->prefix_full_kv_compressed_value_payload_enabled == 0u ||
        state->prefix_full_kv_compressed_block_count == 0u) {
        return 0;
    }

    plan = qrt_qwen36_baseline_plan();
    if (plan == NULL || plan->layer_count != QRT_QWEN36_LAYER_COUNT) {
        return 0;
    }

    view = &request->decode_state_cache_payload_view;
    memset(view, 0, sizeof(*view));
    view->layer_count = plan->layer_count;
    view->token_count =
        prefill_result->output_sequence_decode_state_cache_token_count;
    view->prompt_token_capacity = state->prompt_token_capacity;
    view->linear_ring_elements = linear_ring_elements;
    view->linear_core_state_elements = linear_core_state_elements;
    view->full_kv_history_token_elements = full_kv_token_elements;
    view->full_kv_window_elements = full_kv_window_elements;
    view->full_kv_compressed_block_count =
        state->prefix_full_kv_compressed_block_count;
    view->full_kv_compressed_block_tokens =
        state->prefix_full_kv_compressed_block_tokens;
    view->full_kv_compressed_covered_tokens =
        state->prefix_full_kv_compressed_covered_tokens;
    view->full_kv_compressed_value_payload_stride_bytes =
        sizeof(state->prefix_full_kv_compressed_value_payloads[0][0]);
    view->prefix_full_kv_compressed_enabled =
        state->prefix_full_kv_compressed_enabled;
    view->prefix_full_kv_compressed_value_payload_enabled =
        state->prefix_full_kv_compressed_value_payload_enabled;

    view_digest = qrt_fnv1a64_bytes(
        "Qwen3.6/H-PREFIX-INT-001/descriptor-decode-cache-payload-view-v1",
        sizeof(
            "Qwen3.6/H-PREFIX-INT-001/descriptor-decode-cache-payload-view-v1"
        ) - 1u
    );
    view_digest = qrt_fnv1a64_update_bytes(
        view_digest,
        &view->layer_count,
        sizeof(view->layer_count)
    );
    view_digest = qrt_fnv1a64_update_bytes(
        view_digest,
        &view->token_count,
        sizeof(view->token_count)
    );
    view_digest = qrt_fnv1a64_update_bytes(
        view_digest,
        &view->prompt_token_capacity,
        sizeof(view->prompt_token_capacity)
    );
    view_digest = qrt_fnv1a64_update_bytes(
        view_digest,
        &prefill_result->output_sequence_decode_state_cache_payload_digest_fnv1a64,
        sizeof(prefill_result
                   ->output_sequence_decode_state_cache_payload_digest_fnv1a64)
    );

    for (layer_index = 0u; layer_index < plan->layer_count; ++layer_index) {
        const qrt_qwen36_baseline_layer_descriptor_t *desc =
            qrt_qwen36_baseline_layer_descriptor((unsigned int)layer_index);
        uint64_t first_payload_hash;
        uint64_t second_payload_hash;
        uint32_t attention_kind;

        if (desc == NULL || desc->layer_index != layer_index) {
            return 0;
        }
        attention_kind = (uint32_t)desc->attention_kind;
        if (desc->attention_kind == QRT_QWEN36_BASELINE_ATTENTION_LINEAR) {
            if (state->linear_qkv_rings[layer_index] == NULL ||
                state->linear_core_states[layer_index] == NULL) {
                return 0;
            }
            view->linear_qkv_rings[layer_index] =
                state->linear_qkv_rings[layer_index];
            view->linear_core_states[layer_index] =
                state->linear_core_states[layer_index];
            first_payload_hash = qrt_fnv1a64_f32(
                state->linear_qkv_rings[layer_index],
                linear_ring_elements
            );
            second_payload_hash = qrt_fnv1a64_f32(
                state->linear_core_states[layer_index],
                linear_core_state_elements
            );
            ++view->linear_layer_count;
        } else if (desc->attention_kind == QRT_QWEN36_BASELINE_ATTENTION_FULL) {
            if (state->full_kv_histories[layer_index] == NULL ||
                state->prefix_full_kv_windows[layer_index] == NULL ||
                state->prefix_full_kv_compressed_block_digests[layer_index] ==
                    NULL ||
                state->prefix_full_kv_compressed_value_payloads[layer_index] ==
                    NULL) {
                return 0;
            }
            view->full_kv_histories[layer_index] =
                state->full_kv_histories[layer_index];
            view->prefix_full_kv_windows[layer_index] =
                state->prefix_full_kv_windows[layer_index];
            view->prefix_full_kv_compressed_block_digests[layer_index] =
                state->prefix_full_kv_compressed_block_digests[layer_index];
            view->prefix_full_kv_compressed_value_payloads[layer_index] =
                state->prefix_full_kv_compressed_value_payloads[layer_index];
            first_payload_hash = qrt_fnv1a64_f32(
                state->prefix_full_kv_windows[layer_index],
                full_kv_window_elements
            );
            second_payload_hash = qrt_fnv1a64_update_bytes(
                UINT64_C(1469598103934665603),
                state->prefix_full_kv_compressed_value_payloads[layer_index],
                state->prefix_full_kv_compressed_block_count *
                    sizeof(state->prefix_full_kv_compressed_value_payloads
                               [layer_index][0])
            );
            ++view->full_attention_layer_count;
        } else {
            return 0;
        }

        view_digest = qrt_fnv1a64_update_bytes(
            view_digest,
            &layer_index,
            sizeof(layer_index)
        );
        view_digest = qrt_fnv1a64_update_bytes(
            view_digest,
            &attention_kind,
            sizeof(attention_kind)
        );
        view_digest = qrt_fnv1a64_update_bytes(
            view_digest,
            &first_payload_hash,
            sizeof(first_payload_hash)
        );
        view_digest = qrt_fnv1a64_update_bytes(
            view_digest,
            &second_payload_hash,
            sizeof(second_payload_hash)
        );
    }

    if (view->linear_layer_count != (size_t)QRT_QWEN36_LINEAR_ATTENTION_LAYERS ||
        view->full_attention_layer_count !=
            (size_t)QRT_QWEN36_FULL_ATTENTION_LAYERS ||
        view_digest == UINT64_C(1469598103934665603)) {
        memset(view, 0, sizeof(*view));
        return 0;
    }
    view->payload_view_digest_fnv1a64 = view_digest;
    request->decode_state_cache_payload_view_attached = 1u;
    return 1;
}

static int qrt_win32_prefill_descriptor_batch_hip_decode_execute(
    qrt_engine_t *engine,
    size_t prefill_tokens,
    size_t output_token_capacity,
    const qrt_qwen36_prefill_descriptor_batch_result_t *prefill_result,
    const qrt_qwen36_plain_sequence_state_t *sequence_state,
    qrt_qwen36_prefill_descriptor_batch_decode_result_t *out_result
) {
    qrt_qwen36_prefill_descriptor_batch_decode_request_t request;

    if (out_result != NULL) {
        memset(out_result, 0, sizeof(*out_result));
    }
    if (engine == NULL || prefill_result == NULL || out_result == NULL ||
        engine->model_path == NULL || output_token_capacity == 0u) {
        return 0;
    }
    if (engine->prefill_descriptor_batch_hip_decode == NULL) {
        out_result->output_token_capacity = output_token_capacity;
        out_result->output_sequence_decode_state_exported =
            prefill_result->output_sequence_decode_state_exported;
        out_result->output_sequence_decode_state_digest_fnv1a64 =
            prefill_result->output_sequence_decode_state_digest_fnv1a64;
        out_result->output_sequence_decode_state_token_count =
            prefill_result->output_sequence_decode_state_token_count;
        out_result->output_sequence_decode_state_position =
            prefill_result->output_sequence_decode_state_position;
        out_result->output_sequence_decode_state_token_id =
            prefill_result->output_sequence_decode_state_token_id;
        out_result->output_sequence_decode_state_token_loop_digest_fnv1a64 =
            prefill_result
                ->output_sequence_decode_state_token_loop_digest_fnv1a64;
        out_result
            ->output_sequence_decode_state_output_head_input_hidden_fnv1a64 =
            prefill_result
                ->output_sequence_decode_state_output_head_input_hidden_fnv1a64;
        out_result->output_sequence_decode_state_prefix_state_digest_fnv1a64 =
            prefill_result
                ->output_sequence_decode_state_prefix_state_digest_fnv1a64;
        out_result
            ->output_sequence_decode_state_prefix_position_digest_fnv1a64 =
            prefill_result
                ->output_sequence_decode_state_prefix_position_digest_fnv1a64;
        out_result->output_sequence_decode_state_cache_payload_exported =
            prefill_result->output_sequence_decode_state_cache_payload_exported;
        out_result
            ->output_sequence_decode_state_cache_payload_digest_fnv1a64 =
            prefill_result
                ->output_sequence_decode_state_cache_payload_digest_fnv1a64;
        out_result->output_sequence_decode_state_cache_layer_count =
            prefill_result->output_sequence_decode_state_cache_layer_count;
        out_result->output_sequence_decode_state_cache_token_count =
            prefill_result->output_sequence_decode_state_cache_token_count;
        out_result->output_sequence_decode_input_surface_exported =
            prefill_result->output_sequence_decode_input_surface_exported;
        out_result->output_sequence_decode_input_surface_digest_fnv1a64 =
            prefill_result->output_sequence_decode_input_surface_digest_fnv1a64;
        out_result
            ->output_sequence_decode_input_surface_token_embedding_fnv1a64 =
            prefill_result
                ->output_sequence_decode_input_surface_token_embedding_fnv1a64;
        out_result->output_sequence_decode_input_surface_token_count =
            prefill_result->output_sequence_decode_input_surface_token_count;
        out_result->output_sequence_decode_input_surface_position =
            prefill_result->output_sequence_decode_input_surface_position;
        out_result->output_sequence_decode_input_surface_token_id =
            prefill_result->output_sequence_decode_input_surface_token_id;
        out_result
            ->output_sequence_decode_input_surface_cache_payload_digest_fnv1a64 =
            prefill_result
                ->output_sequence_decode_input_surface_cache_payload_digest_fnv1a64;
        qrt_win32_prefill_descriptor_batch_decode_set_failure(
            out_result,
            "descriptor_autoregressive_decode_loop_export",
            "prefill_descriptor_batch_decode_export",
            "descriptor-batch HIP DLL has no helper-owned autoregressive decode export"
        );
        return 0;
    }

    memset(&request, 0, sizeof(request));
    request.model_dir = engine->model_path;
    request.resident_engine = engine;
    request.prefill_tokens = prefill_tokens;
    request.output_token_capacity = output_token_capacity;
    request.initial_output_token_id =
        prefill_result->output_token_count > 0u
            ? prefill_result->output_tokens[0]
            : prefill_result->continuation.output_token_id;
    request.output_head_input_hidden_fnv1a64 =
        prefill_result->output_head_input_hidden_fnv1a64;
    request.prefix_cache_state_attached =
        engine->prefix_cache_state_attached ? 1u : 0u;
    request.prefix_cache_cached_prefix_tokens =
        engine->prefix_cache_cached_prefix_tokens;
    request.prefix_cache_suffix_tokens = engine->prefix_cache_suffix_tokens;
    request.prefix_cache_executed_input_tokens =
        engine->prefix_cache_executed_input_tokens;
    request.prefix_cache_output_token_capacity =
        engine->prefix_cache_output_token_capacity;
    request.prefix_cache_state_digest_fnv1a64 =
        engine->prefix_cache_state_digest_fnv1a64;
    request.prefix_cache_position_digest_fnv1a64 =
        engine->prefix_cache_position_digest_fnv1a64;
    request.decode_state_exported =
        prefill_result->output_sequence_decode_state_exported;
    request.decode_state_digest_fnv1a64 =
        prefill_result->output_sequence_decode_state_digest_fnv1a64;
    request.decode_state_token_count =
        prefill_result->output_sequence_decode_state_token_count;
    request.decode_state_position =
        prefill_result->output_sequence_decode_state_position;
    request.decode_state_token_id =
        prefill_result->output_sequence_decode_state_token_id;
    request.decode_state_token_loop_digest_fnv1a64 =
        prefill_result->output_sequence_decode_state_token_loop_digest_fnv1a64;
    request.decode_state_output_head_input_hidden_fnv1a64 =
        prefill_result
            ->output_sequence_decode_state_output_head_input_hidden_fnv1a64;
    request.decode_state_prefix_state_digest_fnv1a64 =
        prefill_result->output_sequence_decode_state_prefix_state_digest_fnv1a64;
    request.decode_state_prefix_position_digest_fnv1a64 =
        prefill_result
            ->output_sequence_decode_state_prefix_position_digest_fnv1a64;
    request.decode_state_cache_payload_exported =
        prefill_result->output_sequence_decode_state_cache_payload_exported;
    request.decode_state_cache_payload_digest_fnv1a64 =
        prefill_result
            ->output_sequence_decode_state_cache_payload_digest_fnv1a64;
    request.decode_state_cache_layer_count =
        prefill_result->output_sequence_decode_state_cache_layer_count;
    request.decode_state_cache_token_count =
        prefill_result->output_sequence_decode_state_cache_token_count;
    (void)qrt_qwen36_descriptor_decode_cache_payload_view_attach(
        sequence_state,
        prefill_result,
        &request
    );

    return engine->prefill_descriptor_batch_hip_decode(&request, out_result);
}

static int qrt_qwen36_prefill_descriptor_batch_timing_recorded(
    const qrt_qwen36_prefill_descriptor_batch_timing_t *timing
) {
    size_t index;
    if (timing == NULL) {
        return 0;
    }
    if (timing->descriptor_layer_stack_wall_clock_ns != UINT64_C(0) ||
        timing->layer_stack_host_materialized_output_bytes != UINT64_C(0) ||
        timing->layer_stack_host_materialized_stage_count != UINT64_C(0) ||
        timing->layer_stack_resident_d2d_linear_core_state_lookup_count !=
            UINT64_C(0) ||
        timing->layer_stack_resident_d2d_linear_core_state_store_count !=
            UINT64_C(0) ||
        timing->layer_stack_resident_d2d_linear_core_state_h2d_saved_bytes !=
            UINT64_C(0) ||
        timing->full_attention_resident_core_call_count != UINT64_C(0) ||
        timing->full_attention_resident_core_kernel_ns != UINT64_C(0) ||
        timing->full_attention_resident_core_score_scratch_call_count !=
            UINT64_C(0) ||
        timing->routed_expert_profiled_gate_up_avg_ns_sum != UINT64_C(0) ||
        timing->routed_expert_profiled_down_avg_ns_sum != UINT64_C(0) ||
        timing->routed_expert_profiled_gate_up_phase_count != 0u ||
        timing->routed_expert_profiled_down_phase_count != 0u ||
        timing->compact_device_layout_full_prepack_requested != 0u ||
        timing->compact_device_layout_full_prepack_elapsed_ns !=
            UINT64_C(0) ||
        timing->compact_device_layout_full_preload_elapsed_ns !=
            UINT64_C(0)) {
        return 1;
    }
    for (index = 0u;
         index < QRT_QWEN36_PREFILL_DESCRIPTOR_BATCH_TIMING_BUCKET_COUNT;
         ++index) {
        if (timing->layer_stack_wall_clock_bucket_elapsed_ns[index] !=
                UINT64_C(0) ||
            timing->layer_stack_wall_clock_bucket_call_count[index] != 0u ||
            timing->layer_stack_host_materialized_output_bytes_by_bucket
                    [index] != UINT64_C(0) ||
            timing->layer_stack_host_materialized_stage_count_by_bucket
                    [index] != 0u) {
            return 1;
        }
    }
    return 0;
}

static void qrt_qwen36_prefill_descriptor_batch_merge_decode_result(
    qrt_qwen36_prefill_descriptor_batch_result_t *prefill_result,
    const qrt_qwen36_prefill_descriptor_batch_decode_result_t *decode_result
) {
    if (prefill_result == NULL || decode_result == NULL) {
        return;
    }
    if (decode_result->completed != 0u &&
        decode_result->output_token_count > 0u) {
        size_t copy_count = decode_result->output_token_count;
        if (copy_count > (size_t)QRT_PREFIX_CACHE_TARGET_OUTPUT_TOKENS) {
            copy_count = (size_t)QRT_PREFIX_CACHE_TARGET_OUTPUT_TOKENS;
        }
        prefill_result->output_token_capacity =
            decode_result->output_token_capacity;
        prefill_result->output_token_count = copy_count;
        memcpy(
            prefill_result->output_tokens,
            decode_result->output_tokens,
            copy_count * sizeof(prefill_result->output_tokens[0])
        );
        prefill_result->output_tokens_fnv1a64 =
            decode_result->output_tokens_fnv1a64;
        prefill_result->output_sequence_elapsed_ns =
            decode_result->output_sequence_elapsed_ns;
        prefill_result->output_sequence_tpot_elapsed_ns =
            decode_result->output_sequence_tpot_elapsed_ns;
        prefill_result->output_sequence_tpot_sample_count =
            decode_result->output_sequence_tpot_sample_count;
        prefill_result->output_sequence_prefill_sample_count =
            decode_result->output_sequence_prefill_sample_count;
        prefill_result->output_sequence_decode_token_count =
            decode_result->output_sequence_decode_token_count;
        prefill_result->output_sequence_autoregressive_decode =
            decode_result->output_sequence_autoregressive_decode;
    }
    if (decode_result->output_sequence_decode_state_exported != 0u) {
        prefill_result->output_sequence_decode_state_exported =
            decode_result->output_sequence_decode_state_exported;
        prefill_result->output_sequence_decode_state_digest_fnv1a64 =
            decode_result->output_sequence_decode_state_digest_fnv1a64;
        prefill_result->output_sequence_decode_state_token_count =
            decode_result->output_sequence_decode_state_token_count;
        prefill_result->output_sequence_decode_state_position =
            decode_result->output_sequence_decode_state_position;
        prefill_result->output_sequence_decode_state_token_id =
            decode_result->output_sequence_decode_state_token_id;
        prefill_result
            ->output_sequence_decode_state_token_loop_digest_fnv1a64 =
            decode_result
                ->output_sequence_decode_state_token_loop_digest_fnv1a64;
        prefill_result
            ->output_sequence_decode_state_output_head_input_hidden_fnv1a64 =
            decode_result
                ->output_sequence_decode_state_output_head_input_hidden_fnv1a64;
        prefill_result
            ->output_sequence_decode_state_prefix_state_digest_fnv1a64 =
            decode_result
                ->output_sequence_decode_state_prefix_state_digest_fnv1a64;
        prefill_result
            ->output_sequence_decode_state_prefix_position_digest_fnv1a64 =
            decode_result
                ->output_sequence_decode_state_prefix_position_digest_fnv1a64;
        prefill_result
            ->output_sequence_decode_state_cache_payload_exported =
            decode_result
                ->output_sequence_decode_state_cache_payload_exported;
        prefill_result
            ->output_sequence_decode_state_cache_payload_digest_fnv1a64 =
            decode_result
                ->output_sequence_decode_state_cache_payload_digest_fnv1a64;
        prefill_result->output_sequence_decode_state_cache_layer_count =
            decode_result->output_sequence_decode_state_cache_layer_count;
        prefill_result->output_sequence_decode_state_cache_token_count =
            decode_result->output_sequence_decode_state_cache_token_count;
    }
    if (decode_result->output_sequence_decode_input_surface_exported != 0u) {
        prefill_result->output_sequence_decode_input_surface_exported =
            decode_result->output_sequence_decode_input_surface_exported;
        prefill_result->output_sequence_decode_input_surface_digest_fnv1a64 =
            decode_result->output_sequence_decode_input_surface_digest_fnv1a64;
        prefill_result
            ->output_sequence_decode_input_surface_token_embedding_fnv1a64 =
            decode_result
                ->output_sequence_decode_input_surface_token_embedding_fnv1a64;
        prefill_result->output_sequence_decode_input_surface_token_count =
            decode_result->output_sequence_decode_input_surface_token_count;
        prefill_result->output_sequence_decode_input_surface_position =
            decode_result->output_sequence_decode_input_surface_position;
        prefill_result->output_sequence_decode_input_surface_token_id =
            decode_result->output_sequence_decode_input_surface_token_id;
        prefill_result
            ->output_sequence_decode_input_surface_cache_payload_digest_fnv1a64 =
            decode_result
                ->output_sequence_decode_input_surface_cache_payload_digest_fnv1a64;
    }
    if (qrt_qwen36_prefill_descriptor_batch_timing_recorded(
            &decode_result->timing)) {
        memcpy(
            &prefill_result->timing,
            &decode_result->timing,
            sizeof(prefill_result->timing)
        );
    }
    if (decode_result->first_missing_runtime_context_field[0] != '\0') {
        (void)snprintf(
            prefill_result->output_sequence_decode_missing_field,
            sizeof(prefill_result->output_sequence_decode_missing_field),
            "%s",
            decode_result->first_missing_runtime_context_field
        );
    } else if (decode_result->output_sequence_decode_missing_field[0] != '\0') {
        (void)snprintf(
            prefill_result->output_sequence_decode_missing_field,
            sizeof(prefill_result->output_sequence_decode_missing_field),
            "%s",
            decode_result->output_sequence_decode_missing_field
        );
    }
}

static int qrt_win32_selected_moe_gateup_hip_backend_load(qrt_engine_t *engine) {
    const char *dll_path;
    FARPROC compute_proc;
    FARPROC preload_proc;
    FARPROC down_compute_proc;
    FARPROC down_preload_proc;
    FARPROC release_proc;

    if (engine == NULL ||
        (!engine->baseline_plain_block_moe_expert_gate_up_projection_hip_requested &&
         !engine->baseline_plain_block_moe_expert_down_projection_hip_requested)) {
        return 0;
    }
    if ((!engine->baseline_plain_block_moe_expert_gate_up_projection_hip_requested ||
         (engine->selected_moe_gateup_hip_compute != NULL &&
          engine->selected_moe_gateup_hip_preload != NULL)) &&
        (!engine->baseline_plain_block_moe_expert_down_projection_hip_requested ||
         (engine->selected_moe_down_hip_compute != NULL &&
          engine->selected_moe_down_hip_preload != NULL)) &&
        engine->selected_moe_gateup_hip_release != NULL) {
        if (engine->baseline_plain_block_moe_expert_gate_up_projection_hip_requested) {
            engine->baseline_plain_block_moe_expert_gate_up_projection_hip_enabled = 1;
        }
        if (engine->baseline_plain_block_moe_expert_down_projection_hip_requested) {
            engine->baseline_plain_block_moe_expert_down_projection_hip_enabled = 1;
        }
        return 1;
    }
    if (engine->selected_moe_gateup_hip_load_attempted) {
        return 0;
    }
    engine->selected_moe_gateup_hip_load_attempted = 1;
    dll_path = getenv("QRT_SELECTED_MOE_GATEUP_HIP_DLL");
    if (dll_path == NULL || dll_path[0] == '\0') {
        dll_path = "qrt_selected_moe_gateup_hip.dll";
    }
    engine->selected_moe_gateup_hip_module = LoadLibraryA(dll_path);
    if (engine->selected_moe_gateup_hip_module == NULL) {
        (void)snprintf(
            engine->selected_moe_gateup_hip_failure,
            sizeof(engine->selected_moe_gateup_hip_failure),
            "LoadLibraryA failed for %s",
            dll_path
        );
        return 0;
    }

    compute_proc = GetProcAddress(
        engine->selected_moe_gateup_hip_module,
        "qrt_selected_moe_gateup_hip_compute_v1"
    );
    preload_proc = GetProcAddress(
        engine->selected_moe_gateup_hip_module,
        "qrt_selected_moe_gateup_hip_preload_v1"
    );
    down_compute_proc = GetProcAddress(
        engine->selected_moe_gateup_hip_module,
        "qrt_selected_moe_down_hip_compute_v1"
    );
    down_preload_proc = GetProcAddress(
        engine->selected_moe_gateup_hip_module,
        "qrt_selected_moe_down_hip_preload_v1"
    );
    release_proc = GetProcAddress(
        engine->selected_moe_gateup_hip_module,
        "qrt_selected_moe_gateup_hip_release_v1"
    );
    if (release_proc == NULL ||
        (engine->baseline_plain_block_moe_expert_gate_up_projection_hip_requested &&
         (compute_proc == NULL || preload_proc == NULL)) ||
        (engine->baseline_plain_block_moe_expert_down_projection_hip_requested &&
         (down_compute_proc == NULL || down_preload_proc == NULL))) {
        (void)snprintf(
            engine->selected_moe_gateup_hip_failure,
            sizeof(engine->selected_moe_gateup_hip_failure),
            "%s",
            "selected MoE gate/up HIP DLL missing required exports"
        );
        qrt_win32_selected_moe_gateup_hip_backend_unload(engine);
        return 0;
    }
    engine->selected_moe_gateup_hip_compute =
        (qrt_win32_selected_moe_gateup_hip_compute_fn_t)compute_proc;
    engine->selected_moe_gateup_hip_preload =
        (qrt_win32_selected_moe_gateup_hip_preload_fn_t)preload_proc;
    engine->selected_moe_down_hip_compute =
        (qrt_win32_selected_moe_down_hip_compute_fn_t)down_compute_proc;
    engine->selected_moe_down_hip_preload =
        (qrt_win32_selected_moe_down_hip_preload_fn_t)down_preload_proc;
    engine->selected_moe_gateup_hip_release =
        (qrt_win32_selected_moe_gateup_hip_release_fn_t)release_proc;
    if (engine->baseline_plain_block_moe_expert_gate_up_projection_hip_requested) {
        engine->baseline_plain_block_moe_expert_gate_up_projection_hip_enabled = 1;
    }
    if (engine->baseline_plain_block_moe_expert_down_projection_hip_requested) {
        engine->baseline_plain_block_moe_expert_down_projection_hip_enabled = 1;
    }
    return 1;
}

static int qrt_win32_selected_moe_gateup_hip_preload_weight(
    qrt_engine_t *engine,
    const uint16_t *gate_up_weight,
    size_t weight_bytes
) {
    uint64_t upload_ns = UINT64_C(0);
    uint64_t upload_bytes = UINT64_C(0);
    char failure[QRT_LOAD_ERROR_CAPACITY];

    if (engine == NULL || gate_up_weight == NULL || weight_bytes == 0u ||
        !engine->baseline_plain_block_moe_expert_gate_up_projection_hip_requested) {
        return 0;
    }
    if (!qrt_win32_selected_moe_gateup_hip_backend_load(engine) ||
        engine->selected_moe_gateup_hip_preload == NULL) {
        ++engine
            ->baseline_plain_block_moe_expert_gate_up_projection_hip_preload_failure_count;
        return 0;
    }

    failure[0] = '\0';
    if (!engine->selected_moe_gateup_hip_preload(
            gate_up_weight,
            weight_bytes,
            &upload_ns,
            &upload_bytes,
            failure,
            sizeof(failure)
        )) {
        ++engine
            ->baseline_plain_block_moe_expert_gate_up_projection_hip_preload_failure_count;
        (void)snprintf(
            engine->selected_moe_gateup_hip_failure,
            sizeof(engine->selected_moe_gateup_hip_failure),
            "%s",
            failure[0] != '\0' ? failure : "selected MoE gate/up HIP preload failed"
        );
        return 0;
    }

    ++engine->baseline_plain_block_moe_expert_gate_up_projection_hip_preload_count;
    engine->baseline_plain_block_moe_expert_gate_up_projection_hip_preload_elapsed_ns +=
        upload_ns;
    engine->baseline_plain_block_moe_expert_gate_up_projection_hip_preload_bytes +=
        upload_bytes;
    return 1;
}

