static int qrt_win32_selected_moe_gateup_hip_run(
    qrt_engine_t *engine,
    qrt_qwen36_moe_selected_compute_state_t *states,
    size_t route_count
) {
    const uint16_t *gate_up_weights[QRT_QWEN36_MOE_TOP_K];
    float *gate_values[QRT_QWEN36_MOE_TOP_K];
    float *up_values[QRT_QWEN36_MOE_TOP_K];
    uint64_t upload_ns = UINT64_C(0);
    uint64_t kernel_ns = UINT64_C(0);
    uint64_t output_copy_ns = UINT64_C(0);
    uint64_t upload_bytes = UINT64_C(0);
    char failure[QRT_LOAD_ERROR_CAPACITY];
    size_t route;

    if (engine == NULL || states == NULL || route_count == 0u ||
        route_count > (size_t)QRT_QWEN36_MOE_TOP_K ||
        !engine->baseline_plain_block_moe_expert_gate_up_projection_hip_requested) {
        return 0;
    }
    if (!qrt_win32_selected_moe_gateup_hip_backend_load(engine)) {
        ++engine->baseline_plain_block_moe_expert_gate_up_projection_hip_fallback_count;
        return 0;
    }
    for (route = 0u; route < route_count; ++route) {
        gate_up_weights[route] = states[route].gate_up_weight;
        gate_values[route] = states[route].gate_values;
        up_values[route] = states[route].up_values;
        if (gate_up_weights[route] == NULL ||
            gate_values[route] == NULL ||
            up_values[route] == NULL) {
            ++engine
                ->baseline_plain_block_moe_expert_gate_up_projection_hip_fallback_count;
            return 0;
        }
    }

    failure[0] = '\0';
    if (!engine->selected_moe_gateup_hip_compute(
            gate_up_weights,
            states[0].input,
            gate_values,
            up_values,
            route_count,
            &upload_ns,
            &kernel_ns,
            &output_copy_ns,
            &upload_bytes,
            failure,
            sizeof(failure)
        )) {
        ++engine->baseline_plain_block_moe_expert_gate_up_projection_hip_fallback_count;
        (void)snprintf(
            engine->selected_moe_gateup_hip_failure,
            sizeof(engine->selected_moe_gateup_hip_failure),
            "%s",
            failure[0] != '\0' ? failure : "selected MoE gate/up HIP compute failed"
        );
        return 0;
    }

    ++engine->baseline_plain_block_moe_expert_gate_up_projection_hip_dispatch_count;
    engine->baseline_plain_block_moe_expert_gate_up_projection_hip_upload_elapsed_ns +=
        upload_ns;
    engine->baseline_plain_block_moe_expert_gate_up_projection_hip_kernel_elapsed_ns +=
        kernel_ns;
    engine
        ->baseline_plain_block_moe_expert_gate_up_projection_hip_output_copy_elapsed_ns +=
        output_copy_ns;
    engine->baseline_plain_block_moe_expert_gate_up_projection_hip_upload_bytes +=
        upload_bytes;
    return 1;
}

