static void qrt_qwen36_copy_trace_sample_f32(
    float *out_sample,
    const float *values,
    size_t value_count
) {
    size_t index;

    if (out_sample == NULL) {
        return;
    }

    for (index = 0u; index < (size_t)QRT_QWEN36_TRACE_SAMPLE_COUNT; ++index) {
        out_sample[index] =
            values != NULL && index < value_count ? values[index] : 0.0f;
    }
}

static void qrt_qwen36_store_trace_stats_f32(
    size_t *out_numel,
    float *out_min,
    float *out_max,
    float *out_mean,
    float *out_rms,
    float *out_max_abs,
    const float *values,
    size_t value_count
) {
    if (out_numel == NULL || out_min == NULL || out_max == NULL ||
        out_mean == NULL || out_rms == NULL || out_max_abs == NULL) {
        return;
    }

    *out_numel = 0u;
    *out_min = 0.0f;
    *out_max = 0.0f;
    *out_mean = 0.0f;
    *out_rms = 0.0f;
    *out_max_abs = 0.0f;

    if (qrt_f32_vector_distribution(
            values,
            value_count,
            out_min,
            out_max,
            out_mean,
            out_rms,
            out_max_abs
        )) {
        *out_numel = value_count;
    }
}

static int qrt_qwen36_apply_descriptor_block_handoff(
    const float *input_hidden,
    uint64_t descriptor_digest,
    uint64_t block_integration_digest,
    float *out_hidden,
    uint64_t *out_layer_handoff_hashes,
    uint64_t *out_initial_hidden_hash,
    uint64_t *out_final_hidden_hash,
    uint64_t *out_handoff_digest,
    unsigned int *out_handoff_layer_count,
    unsigned int *out_buffer_swap_count
) {
    const qrt_qwen36_baseline_plan_t *plan;
    float *scratch = NULL;
    float *current_hidden;
    float *next_hidden;
    uint64_t handoff_digest = UINT64_C(1469598103934665603);
    unsigned int handoff_layer_count = 0u;
    unsigned int buffer_swap_count = 0u;
    unsigned int layer_index;
    size_t hidden_index;

    if (input_hidden == NULL || out_hidden == NULL ||
        descriptor_digest == 0u || block_integration_digest == 0u ||
        out_initial_hidden_hash == NULL || out_final_hidden_hash == NULL ||
        out_handoff_digest == NULL || out_handoff_layer_count == NULL ||
        out_buffer_swap_count == NULL) {
        return 0;
    }

    plan = qrt_qwen36_baseline_plan();
    if (plan == NULL || plan->layer_count != QRT_QWEN36_LAYER_COUNT ||
        plan->hidden_size != QRT_QWEN36_HIDDEN_SIZE) {
        return 0;
    }

    scratch =
        (float *)malloc((size_t)QRT_QWEN36_HIDDEN_SIZE * sizeof(float));
    if (scratch == NULL) {
        return 0;
    }

    memcpy(
        out_hidden,
        input_hidden,
        (size_t)QRT_QWEN36_HIDDEN_SIZE * sizeof(float)
    );
    memset(scratch, 0, (size_t)QRT_QWEN36_HIDDEN_SIZE * sizeof(float));
    current_hidden = out_hidden;
    next_hidden = scratch;

    *out_initial_hidden_hash =
        qrt_fnv1a64_f32(current_hidden, (size_t)QRT_QWEN36_HIDDEN_SIZE);
    handoff_digest = qrt_fnv1a64_update_bytes(
        handoff_digest,
        &descriptor_digest,
        sizeof(descriptor_digest)
    );
    handoff_digest = qrt_fnv1a64_update_bytes(
        handoff_digest,
        &block_integration_digest,
        sizeof(block_integration_digest)
    );
    handoff_digest = qrt_fnv1a64_update_bytes(
        handoff_digest,
        out_initial_hidden_hash,
        sizeof(*out_initial_hidden_hash)
    );

    for (layer_index = 0u; layer_index < plan->layer_count; ++layer_index) {
        const qrt_qwen36_baseline_layer_descriptor_t *desc =
            qrt_qwen36_baseline_layer_descriptor(layer_index);
        const uint64_t input_handoff_hash =
            qrt_fnv1a64_f32(current_hidden, (size_t)QRT_QWEN36_HIDDEN_SIZE);
        uint64_t layer_digest = UINT64_C(1469598103934665603);
        uint64_t layer_seed;
        uint64_t output_handoff_hash;
        float kind_delta;

        if (desc == NULL || desc->layer_index != layer_index ||
            desc->hidden_size != QRT_QWEN36_HIDDEN_SIZE ||
            desc->has_moe != 1u || desc->has_shared_expert != 1u) {
            free(scratch);
            return 0;
        }

        kind_delta =
            desc->attention_kind == QRT_QWEN36_BASELINE_ATTENTION_FULL
                ? 0.00048828125f
                : 0.000244140625f;
        layer_seed =
            descriptor_digest ^
            (block_integration_digest + ((uint64_t)layer_index << 32)) ^
            ((uint64_t)desc->module_count << 48);

        for (hidden_index = 0u;
             hidden_index < (size_t)QRT_QWEN36_HIDDEN_SIZE;
             ++hidden_index) {
            const unsigned int shift =
                (unsigned int)((hidden_index + layer_index) & 31u);
            const float slot_delta =
                (float)(hidden_index % 17u) * 0.0000152587890625f;
            const float block_delta =
                (float)((int)((layer_seed >> shift) & UINT64_C(31)) - 16) *
                0.00000095367431640625f;
            const float value =
                current_hidden[hidden_index] +
                ((float)(layer_index + 1u) * 0.000030517578125f) +
                kind_delta +
                slot_delta +
                block_delta;
            next_hidden[hidden_index] =
                qrt_bf16_to_float(qrt_float_to_bf16(value));
        }

        output_handoff_hash =
            qrt_fnv1a64_f32(next_hidden, (size_t)QRT_QWEN36_HIDDEN_SIZE);
        if (out_layer_handoff_hashes != NULL) {
            out_layer_handoff_hashes[layer_index] = output_handoff_hash;
        }

        layer_digest = qrt_fnv1a64_update_bytes(
            layer_digest,
            &desc->layer_index,
            sizeof(desc->layer_index)
        );
        layer_digest = qrt_fnv1a64_update_bytes(
            layer_digest,
            &desc->attention_kind,
            sizeof(desc->attention_kind)
        );
        layer_digest = qrt_fnv1a64_update_bytes(
            layer_digest,
            &desc->module_count,
            sizeof(desc->module_count)
        );
        layer_digest = qrt_fnv1a64_update_bytes(
            layer_digest,
            &input_handoff_hash,
            sizeof(input_handoff_hash)
        );
        layer_digest = qrt_fnv1a64_update_bytes(
            layer_digest,
            &output_handoff_hash,
            sizeof(output_handoff_hash)
        );
        handoff_digest = qrt_fnv1a64_update_bytes(
            handoff_digest,
            &layer_digest,
            sizeof(layer_digest)
        );

        {
            float *swap = current_hidden;
            current_hidden = next_hidden;
            next_hidden = swap;
        }
        ++handoff_layer_count;
        ++buffer_swap_count;
    }

    if (current_hidden != out_hidden) {
        memcpy(
            out_hidden,
            current_hidden,
            (size_t)QRT_QWEN36_HIDDEN_SIZE * sizeof(float)
        );
    }

    *out_final_hidden_hash =
        qrt_fnv1a64_f32(out_hidden, (size_t)QRT_QWEN36_HIDDEN_SIZE);
    handoff_digest = qrt_fnv1a64_update_bytes(
        handoff_digest,
        &handoff_layer_count,
        sizeof(handoff_layer_count)
    );
    handoff_digest = qrt_fnv1a64_update_bytes(
        handoff_digest,
        &buffer_swap_count,
        sizeof(buffer_swap_count)
    );
    handoff_digest = qrt_fnv1a64_update_bytes(
        handoff_digest,
        out_final_hidden_hash,
        sizeof(*out_final_hidden_hash)
    );
    *out_handoff_digest = handoff_digest;
    *out_handoff_layer_count = handoff_layer_count;
    *out_buffer_swap_count = buffer_swap_count;

    free(scratch);
    return 1;
}

#define QRT_QWEN36_PLAIN_LINEAR_ATTENTION_OUTPUT_MODULES 9u
#define QRT_QWEN36_PLAIN_FULL_ATTENTION_OUTPUT_MODULES 5u
#define QRT_QWEN36_PLAIN_POST_ATTENTION_OUTPUT_MODULES 1u
#define QRT_QWEN36_PLAIN_MOE_OUTPUT_MODULES 4u

static int qrt_qwen36_is_full_attention_layer(unsigned int layer_index) {
    return (layer_index % 4u) == 3u;
}

static unsigned int qrt_qwen36_plain_linear_attention_layers_for_limit(
    unsigned int layer_limit
) {
    unsigned int layer_index;
    unsigned int count = 0u;
    if (layer_limit > QRT_QWEN36_LAYER_COUNT) {
        layer_limit = QRT_QWEN36_LAYER_COUNT;
    }
    for (layer_index = 0u; layer_index < layer_limit; ++layer_index) {
        if (!qrt_qwen36_is_full_attention_layer(layer_index)) {
            ++count;
        }
    }
    return count;
}

static unsigned int qrt_qwen36_plain_full_attention_layers_for_limit(
    unsigned int layer_limit
) {
    if (layer_limit > QRT_QWEN36_LAYER_COUNT) {
        layer_limit = QRT_QWEN36_LAYER_COUNT;
    }
    return layer_limit -
        qrt_qwen36_plain_linear_attention_layers_for_limit(layer_limit);
}

static unsigned int qrt_qwen36_plain_expected_module_output_count(
    unsigned int layer_count,
    unsigned int linear_attention_layer_count,
    unsigned int full_attention_layer_count
) {
    return layer_count +
        (linear_attention_layer_count *
            QRT_QWEN36_PLAIN_LINEAR_ATTENTION_OUTPUT_MODULES) +
        (full_attention_layer_count *
            QRT_QWEN36_PLAIN_FULL_ATTENTION_OUTPUT_MODULES) +
        (layer_count * QRT_QWEN36_PLAIN_POST_ATTENTION_OUTPUT_MODULES) +
        (layer_count * QRT_QWEN36_PLAIN_MOE_OUTPUT_MODULES);
}

static int qrt_qwen36_plain_executor_counts_match(
    unsigned int layer_count,
    unsigned int module_output_count,
    unsigned int input_norm_layer_count,
    unsigned int attention_module_output_count,
    unsigned int linear_attention_layer_count,
    unsigned int full_attention_layer_count,
    unsigned int post_attention_norm_layer_count,
    unsigned int moe_layer_count,
    unsigned int moe_module_output_count,
    unsigned int expected_layer_count,
    unsigned int expected_linear_attention_layer_count,
    unsigned int expected_full_attention_layer_count
) {
    const unsigned int expected_attention_module_output_count =
        (expected_linear_attention_layer_count *
            QRT_QWEN36_PLAIN_LINEAR_ATTENTION_OUTPUT_MODULES) +
        (expected_full_attention_layer_count *
            QRT_QWEN36_PLAIN_FULL_ATTENTION_OUTPUT_MODULES);
    const unsigned int expected_module_output_count =
        qrt_qwen36_plain_expected_module_output_count(
            expected_layer_count,
            expected_linear_attention_layer_count,
            expected_full_attention_layer_count
        );

    return layer_count == expected_layer_count &&
        input_norm_layer_count == expected_layer_count &&
        linear_attention_layer_count == expected_linear_attention_layer_count &&
        full_attention_layer_count == expected_full_attention_layer_count &&
        post_attention_norm_layer_count == expected_layer_count &&
        moe_layer_count == expected_layer_count &&
        attention_module_output_count == expected_attention_module_output_count &&
        moe_module_output_count ==
            expected_layer_count * QRT_QWEN36_PLAIN_MOE_OUTPUT_MODULES &&
        module_output_count == expected_module_output_count;
}

static int qrt_qwen36_u32_array_contains(
    const uint32_t *values,
    size_t count,
    uint32_t value
) {
    size_t index;
    for (index = 0u; index < count; ++index) {
        if (values[index] == value) {
            return 1;
        }
    }
    return 0;
}

static qrt_status_t qrt_qwen36_selected_tokens_for_context(
    size_t context_tokens,
    uint32_t *out_tokens,
    size_t token_capacity,
    size_t *out_token_count
) {
    uint32_t candidates[4];
    size_t candidate_index;
    size_t count = 0u;

    if (out_tokens == NULL || out_token_count == NULL ||
        context_tokens == 0u || context_tokens > UINT32_MAX ||
        token_capacity < 4u) {
        return QRT_STATUS_INVALID_ARGUMENT;
    }

    candidates[0] = 0u;
    candidates[1] = (uint32_t)(context_tokens / 3u);
    candidates[2] = (uint32_t)((context_tokens * 2u) / 3u);
    candidates[3] = (uint32_t)(context_tokens - 1u);

    for (candidate_index = 0u; candidate_index < 4u; ++candidate_index) {
        if (!qrt_qwen36_u32_array_contains(
                out_tokens,
                count,
                candidates[candidate_index]
            )) {
            out_tokens[count] = candidates[candidate_index];
            ++count;
        }
    }
    *out_token_count = count;
    return QRT_STATUS_OK;
}

static qrt_status_t qrt_qwen36_selected_window_tokens_for_targets(
    const uint32_t *target_tokens,
    size_t target_token_count,
    uint32_t *out_tokens,
    size_t token_capacity,
    size_t *out_token_count
) {
    size_t target_index;
    size_t count = 0u;

    if (target_tokens == NULL || out_tokens == NULL ||
        out_token_count == NULL || target_token_count == 0u) {
        return QRT_STATUS_INVALID_ARGUMENT;
    }

    for (target_index = 0u; target_index < target_token_count; ++target_index) {
        const uint32_t token = target_tokens[target_index];
        const uint32_t begin =
            token >= (uint32_t)(QRT_QWEN36_LAYER0_LINEAR_ATTN_CONV_KERNEL - 1u)
                ? token -
                      (uint32_t)(QRT_QWEN36_LAYER0_LINEAR_ATTN_CONV_KERNEL - 1u)
                : 0u;
        uint32_t current;
        for (current = begin; current <= token; ++current) {
            if (!qrt_qwen36_u32_array_contains(out_tokens, count, current)) {
                if (count >= token_capacity) {
                    return QRT_STATUS_OUT_OF_MEMORY;
                }
                out_tokens[count] = current;
                ++count;
            }
        }
    }
    *out_token_count = count;
    return QRT_STATUS_OK;
}

static qrt_status_t qrt_qwen36_layer1_frontier_tokens_for_final_targets(
    const uint32_t *final_target_tokens,
    size_t final_target_token_count,
    uint32_t *out_tokens,
    size_t token_capacity,
    size_t *out_token_count,
    uint64_t *out_token_ids_hash
) {
    uint32_t current[QRT_QWEN36_PRODUCT_Q8192_LAYER1_FRONTIER_TOKEN_CAPACITY];
    uint32_t next[QRT_QWEN36_PRODUCT_Q8192_LAYER1_FRONTIER_TOKEN_CAPACITY];
    size_t current_count;
    size_t next_count = 0u;
    unsigned int layer_index;
    qrt_status_t status;

    if (final_target_tokens == NULL || final_target_token_count == 0u ||
        out_tokens == NULL || out_token_count == NULL ||
        out_token_ids_hash == NULL ||
        final_target_token_count >
            QRT_QWEN36_PRODUCT_Q8192_LAYER1_FRONTIER_TOKEN_CAPACITY ||
        token_capacity < QRT_QWEN36_PRODUCT_Q8192_LAYER1_FRONTIER_TOKEN_CAPACITY) {
        return QRT_STATUS_INVALID_ARGUMENT;
    }

    memset(current, 0, sizeof(current));
    memset(next, 0, sizeof(next));
    memcpy(
        current,
        final_target_tokens,
        final_target_token_count * sizeof(current[0])
    );
    current_count = final_target_token_count;

    for (layer_index = QRT_QWEN36_PRODUCT_Q8192_DESCRIPTOR_FINAL_LAYER_INDEX - 1u;
         layer_index > 1u;
         --layer_index) {
        if (qrt_qwen36_is_full_attention_layer(layer_index)) {
            continue;
        }
        memset(next, 0, sizeof(next));
        next_count = 0u;
        status = qrt_qwen36_selected_window_tokens_for_targets(
            current,
            current_count,
            next,
            QRT_QWEN36_PRODUCT_Q8192_LAYER1_FRONTIER_TOKEN_CAPACITY,
            &next_count
        );
        if (status != QRT_STATUS_OK) {
            return status;
        }
        memcpy(current, next, next_count * sizeof(current[0]));
        current_count = next_count;
    }

    memcpy(out_tokens, current, current_count * sizeof(out_tokens[0]));
    *out_token_count = current_count;
    *out_token_ids_hash = qrt_fnv1a64_update_bytes(
        UINT64_C(1469598103934665603),
        out_tokens,
        current_count * sizeof(out_tokens[0])
    );
    return QRT_STATUS_OK;
}

typedef struct qrt_qwen36_plain_layer_tensor_names_t {
    char input_norm[QRT_QWEN36_TENSOR_NAME_CAPACITY];
    char linear_qkv[QRT_QWEN36_TENSOR_NAME_CAPACITY];
    char linear_z[QRT_QWEN36_TENSOR_NAME_CAPACITY];
    char linear_a[QRT_QWEN36_TENSOR_NAME_CAPACITY];
    char linear_b[QRT_QWEN36_TENSOR_NAME_CAPACITY];
    char linear_conv[QRT_QWEN36_TENSOR_NAME_CAPACITY];
    char linear_a_log[QRT_QWEN36_TENSOR_NAME_CAPACITY];
    char linear_dt_bias[QRT_QWEN36_TENSOR_NAME_CAPACITY];
    char linear_norm[QRT_QWEN36_TENSOR_NAME_CAPACITY];
    char linear_out_proj[QRT_QWEN36_TENSOR_NAME_CAPACITY];
    char full_q[QRT_QWEN36_TENSOR_NAME_CAPACITY];
    char full_k[QRT_QWEN36_TENSOR_NAME_CAPACITY];
    char full_v[QRT_QWEN36_TENSOR_NAME_CAPACITY];
    char full_o[QRT_QWEN36_TENSOR_NAME_CAPACITY];
    char full_q_norm[QRT_QWEN36_TENSOR_NAME_CAPACITY];
    char full_k_norm[QRT_QWEN36_TENSOR_NAME_CAPACITY];
    char post_attention_norm[QRT_QWEN36_TENSOR_NAME_CAPACITY];
    char moe_router[QRT_QWEN36_TENSOR_NAME_CAPACITY];
    char moe_expert_gate_up[QRT_QWEN36_TENSOR_NAME_CAPACITY];
    char moe_expert_down[QRT_QWEN36_TENSOR_NAME_CAPACITY];
    char moe_shared_gate[QRT_QWEN36_TENSOR_NAME_CAPACITY];
    char moe_shared_gate_proj[QRT_QWEN36_TENSOR_NAME_CAPACITY];
    char moe_shared_up_proj[QRT_QWEN36_TENSOR_NAME_CAPACITY];
    char moe_shared_down[QRT_QWEN36_TENSOR_NAME_CAPACITY];
} qrt_qwen36_plain_layer_tensor_names_t;

static void qrt_qwen36_plain_digest_hash(
    uint64_t *digest,
    const char *module_name,
    uint64_t hash
) {
    if (digest == NULL || module_name == NULL) {
        return;
    }
    *digest = qrt_fnv1a64_update_bytes(
        *digest,
        module_name,
        strlen(module_name) + 1u
    );
    *digest = qrt_fnv1a64_update_bytes(*digest, &hash, sizeof(hash));
}

static uint64_t qrt_qwen36_plain_combine_hash_pair(
    uint64_t first_hash,
    uint64_t second_hash
) {
    uint64_t digest = UINT64_C(1469598103934665603);
    digest = qrt_fnv1a64_update_bytes(digest, &first_hash, sizeof(first_hash));
    digest = qrt_fnv1a64_update_bytes(digest, &second_hash, sizeof(second_hash));
    return digest;
}

static uint64_t qrt_qwen36_plain_combine_hash_triple(
    uint64_t first_hash,
    uint64_t second_hash,
    uint64_t third_hash
) {
    uint64_t digest = UINT64_C(1469598103934665603);
    digest = qrt_fnv1a64_update_bytes(digest, &first_hash, sizeof(first_hash));
    digest = qrt_fnv1a64_update_bytes(digest, &second_hash, sizeof(second_hash));
    digest = qrt_fnv1a64_update_bytes(digest, &third_hash, sizeof(third_hash));
    return digest;
}

static void qrt_qwen36_product_q8192_reset_stage_digests(
    size_t stage_count,
    size_t *stage_token_counts,
    uint64_t *stage_digests,
    uint64_t *stage_last_hashes
) {
    size_t stage_index;

    if (stage_token_counts == NULL || stage_digests == NULL ||
        stage_last_hashes == NULL) {
        return;
    }
    for (stage_index = 0u; stage_index < stage_count; ++stage_index) {
        stage_token_counts[stage_index] = 0u;
        stage_digests[stage_index] = UINT64_C(1469598103934665603);
        stage_last_hashes[stage_index] = UINT64_C(0);
    }
}

static void qrt_engine_clear_baseline_product_q8192_frontier_buffer(
    qrt_engine_t *engine
) {
    size_t stage_index;

    if (engine == NULL) {
        return;
    }
    free(engine->baseline_product_q8192_layer1_frontier_buffer_token_ids);
    free(engine->baseline_product_q8192_layer1_frontier_buffer_hidden_values);
    engine->baseline_product_q8192_layer1_frontier_buffer_token_ids = NULL;
    engine->baseline_product_q8192_layer1_frontier_buffer_hidden_values = NULL;
    engine->baseline_product_q8192_layer1_frontier_buffer_hidden_values_fnv1a64 =
        UINT64_C(0);
    for (stage_index = 0u;
         stage_index <
             (size_t)QRT_QWEN36_PRODUCT_Q8192_LAYER0_SOURCE_STAGE_COUNT;
         ++stage_index) {
        free(engine->baseline_product_q8192_layer0_source_stage_values
                 [stage_index]);
        engine->baseline_product_q8192_layer0_source_stage_values
            [stage_index] = NULL;
        engine->baseline_product_q8192_layer0_source_stage_value_bytes
            [stage_index] = 0u;
        engine->baseline_product_q8192_layer0_source_stage_value_types
            [stage_index] = QRT_QWEN36_SOURCE_VALUE_TYPE_NONE;
        engine->baseline_product_q8192_layer0_source_stage_values_present
            [stage_index] = 0u;
    }
}

static void qrt_qwen36_product_q8192_update_stage_digest_arrays(
    size_t stage_count,
    size_t *stage_token_counts,
    uint64_t *stage_digests,
    uint64_t *stage_last_hashes,
    size_t stage_index,
    unsigned int layer_index,
    size_t token_position,
    uint64_t stage_hash
) {
    if (stage_token_counts == NULL || stage_digests == NULL ||
        stage_last_hashes == NULL || stage_index >= stage_count) {
        return;
    }
    stage_digests[stage_index] =
        qrt_fnv1a64_update_bytes(
            stage_digests[stage_index],
            &layer_index,
            sizeof(layer_index)
        );
    stage_digests[stage_index] =
        qrt_fnv1a64_update_bytes(
            stage_digests[stage_index],
            &token_position,
            sizeof(token_position)
        );
    stage_digests[stage_index] =
        qrt_fnv1a64_update_bytes(
            stage_digests[stage_index],
            &stage_hash,
            sizeof(stage_hash)
        );
    stage_last_hashes[stage_index] = stage_hash;
    ++stage_token_counts[stage_index];
}

static int qrt_qwen36_product_q8192_source_window_contains(
    const qrt_qwen36_plain_sequence_state_t *state,
    size_t token_position
) {
    size_t token_index;

    if (state == NULL || token_position > UINT32_MAX) {
        return 0;
    }
    for (token_index = 0u;
         token_index <
            state->product_q8192_layer1_frontier_source_window_token_count;
         ++token_index) {
        if ((size_t)state->product_q8192_layer1_frontier_source_window_tokens
                [token_index] == token_position) {
            return 1;
        }
    }
    return 0;
}

static const char *qrt_qwen36_product_q8192_layer0_source_stage_name(
    size_t stage
) {
    static const char *const names[QRT_QWEN36_PRODUCT_Q8192_LAYER0_SOURCE_STAGE_COUNT] = {
        "seed_input_hidden",
        "qkv",
        "qkv_ring",
        "z",
        "a",
        "b",
        "conv",
        "postconv_q",
        "postconv_k",
        "postconv_v",
        "gate_g",
        "gate_g_bf16",
        "gate_beta",
        "core_state_input",
        "core",
        "gated",
        "out",
        "residual_hidden",
        "post_attention",
        "router_logits",
        "router_topk_ids",
        "router_topk_weights",
        "routed_output",
        "shared_output",
        "combined_moe",
        "output_hidden"
    };
    return stage < (size_t)QRT_QWEN36_PRODUCT_Q8192_LAYER0_SOURCE_STAGE_COUNT
        ? names[stage]
        : "unknown";
}

static uint64_t qrt_qwen36_product_q8192_layer0_source_stage_table_digest(
    const size_t *token_counts,
    const uint64_t *stage_digests,
    const uint64_t *stage_lasts
) {
    uint64_t digest = qrt_fnv1a64_bytes(
        "Qwen3.6/product-q8192/layer0-source-stage-export-v1",
        sizeof("Qwen3.6/product-q8192/layer0-source-stage-export-v1")
    );
    size_t stage;

    if (token_counts == NULL || stage_digests == NULL ||
        stage_lasts == NULL) {
        return UINT64_C(0);
    }
    for (stage = 0u;
         stage < (size_t)QRT_QWEN36_PRODUCT_Q8192_LAYER0_SOURCE_STAGE_COUNT;
         ++stage) {
        digest = qrt_fnv1a64_update_bytes(digest, &stage, sizeof(stage));
        digest = qrt_fnv1a64_update_bytes(
            digest,
            &token_counts[stage],
            sizeof(token_counts[stage])
        );
        digest = qrt_fnv1a64_update_bytes(
            digest,
            &stage_digests[stage],
            sizeof(stage_digests[stage])
        );
        digest = qrt_fnv1a64_update_bytes(
            digest,
            &stage_lasts[stage],
            sizeof(stage_lasts[stage])
        );
    }
    return digest;
}

static void qrt_qwen36_fill_layer0_source_stage_exports(
    qrt_qwen36_layer0_source_stage_export_t *stages,
    size_t stage_capacity,
    const size_t *token_counts,
    const uint64_t *stage_digests,
    const uint64_t *stage_lasts,
    uint8_t *const *stage_values,
    const size_t *stage_value_bytes,
    const uint32_t *stage_value_types,
    const unsigned int *stage_values_present
) {
    size_t stage;
    const size_t stage_count =
        (size_t)QRT_QWEN36_PRODUCT_Q8192_LAYER0_SOURCE_STAGE_COUNT;

    if (stages == NULL || stage_capacity < stage_count ||
        token_counts == NULL || stage_digests == NULL ||
        stage_lasts == NULL) {
        return;
    }
    for (stage = 0u; stage < stage_count; ++stage) {
        stages[stage].stage_id = (uint32_t)stage;
        stages[stage].stage_name =
            qrt_qwen36_product_q8192_layer0_source_stage_name(stage);
        stages[stage].values = stage_values != NULL
            ? stage_values[stage]
            : NULL;
        stages[stage].value_bytes = stage_value_bytes != NULL
            ? stage_value_bytes[stage]
            : 0u;
        stages[stage].token_count = token_counts[stage];
        stages[stage].digest_fnv1a64 = stage_digests[stage];
        stages[stage].last_fnv1a64 = stage_lasts[stage];
        stages[stage].value_type = stage_value_types != NULL
            ? stage_value_types[stage]
            : QRT_QWEN36_SOURCE_VALUE_TYPE_NONE;
        stages[stage].values_present =
            stage_values_present != NULL && stage_values_present[stage] != 0u &&
                    stages[stage].values != NULL &&
                    stages[stage].value_bytes != 0u
                ? 1u
                : 0u;
    }
}

static int qrt_qwen36_product_q8192_layer0_source_stage_needs_values(
    qrt_qwen36_product_q8192_layer0_source_stage_t stage
) {
    return stage == QRT_QWEN36_PRODUCT_Q8192_LAYER0_SOURCE_STAGE_RESIDUAL_HIDDEN ||
           stage == QRT_QWEN36_PRODUCT_Q8192_LAYER0_SOURCE_STAGE_POST_ATTENTION ||
           stage == QRT_QWEN36_PRODUCT_Q8192_LAYER0_SOURCE_STAGE_ROUTER_LOGITS ||
           stage == QRT_QWEN36_PRODUCT_Q8192_LAYER0_SOURCE_STAGE_ROUTER_TOPK_IDS ||
           stage == QRT_QWEN36_PRODUCT_Q8192_LAYER0_SOURCE_STAGE_ROUTER_TOPK_WEIGHTS;
}

static qrt_status_t qrt_qwen36_product_q8192_store_layer0_source_stage_values(
    qrt_qwen36_plain_sequence_state_t *state,
    qrt_qwen36_product_q8192_layer0_source_stage_t stage,
    unsigned int layer_index,
    size_t token_position,
    const void *values,
    size_t value_bytes,
    uint32_t value_type
) {
    const size_t stage_index = (size_t)stage;
    size_t next_token_count;
    uint8_t *stage_values;

    if (state == NULL ||
        state->product_q8192_layer1_frontier_enabled == 0u ||
        layer_index != 0u ||
        !qrt_qwen36_product_q8192_source_window_contains(state, token_position)) {
        return QRT_STATUS_OK;
    }
    if (stage_index >=
            (size_t)QRT_QWEN36_PRODUCT_Q8192_LAYER0_SOURCE_STAGE_COUNT ||
        values == NULL || value_bytes == 0u ||
        state->product_q8192_layer1_frontier_source_window_token_count == 0u) {
        return QRT_STATUS_INVALID_ARGUMENT;
    }
    if (!qrt_qwen36_product_q8192_layer0_source_stage_needs_values(stage)) {
        return QRT_STATUS_OK;
    }
    if (state->product_q8192_layer0_source_stage_value_stride_bytes
            [stage_index] == 0u) {
        const size_t capacity =
            state->product_q8192_layer1_frontier_source_window_token_count;
        if (capacity > SIZE_MAX / value_bytes) {
            return QRT_STATUS_OUT_OF_MEMORY;
        }
        state->product_q8192_layer0_source_stage_values[stage_index] =
            (uint8_t *)malloc(capacity * value_bytes);
        if (state->product_q8192_layer0_source_stage_values[stage_index] ==
                NULL) {
            return QRT_STATUS_OUT_OF_MEMORY;
        }
        state->product_q8192_layer0_source_stage_value_stride_bytes
            [stage_index] = value_bytes;
        state->product_q8192_layer0_source_stage_value_types[stage_index] =
            value_type;
    }
    if (state->product_q8192_layer0_source_stage_value_stride_bytes
                [stage_index] != value_bytes ||
        state->product_q8192_layer0_source_stage_value_types[stage_index] !=
            value_type) {
        return QRT_STATUS_UNSUPPORTED;
    }

    next_token_count =
        state->product_q8192_layer0_source_stage_value_token_counts
            [stage_index];
    if (next_token_count >=
        state->product_q8192_layer1_frontier_source_window_token_count) {
        return QRT_STATUS_UNSUPPORTED;
    }
    stage_values =
        state->product_q8192_layer0_source_stage_values[stage_index];
    memcpy(
        stage_values + next_token_count * value_bytes,
        values,
        value_bytes
    );
    state->product_q8192_layer0_source_stage_value_token_counts[stage_index] =
        next_token_count + 1u;
    state->product_q8192_layer0_source_stage_value_bytes[stage_index] =
        (next_token_count + 1u) * value_bytes;
    state->product_q8192_layer0_source_stage_values_present[stage_index] = 1u;
    return QRT_STATUS_OK;
}

static qrt_status_t qrt_qwen36_product_q8192_store_layer0_source_stage_f32(
    qrt_qwen36_plain_sequence_state_t *state,
    qrt_qwen36_product_q8192_layer0_source_stage_t stage,
    unsigned int layer_index,
    size_t token_position,
    const float *values,
    size_t value_count
) {
    if (value_count > SIZE_MAX / sizeof(values[0])) {
        return QRT_STATUS_OUT_OF_MEMORY;
    }
    return qrt_qwen36_product_q8192_store_layer0_source_stage_values(
        state,
        stage,
        layer_index,
        token_position,
        values,
        value_count * sizeof(values[0]),
        QRT_QWEN36_SOURCE_VALUE_TYPE_F32
    );
}

static qrt_status_t qrt_qwen36_product_q8192_store_layer0_source_stage_u32(
    qrt_qwen36_plain_sequence_state_t *state,
    qrt_qwen36_product_q8192_layer0_source_stage_t stage,
    unsigned int layer_index,
    size_t token_position,
    const uint32_t *values,
    size_t value_count
) {
    if (value_count > SIZE_MAX / sizeof(values[0])) {
        return QRT_STATUS_OUT_OF_MEMORY;
    }
    return qrt_qwen36_product_q8192_store_layer0_source_stage_values(
        state,
        stage,
        layer_index,
        token_position,
        values,
        value_count * sizeof(values[0]),
        QRT_QWEN36_SOURCE_VALUE_TYPE_U32
    );
}

static qrt_status_t qrt_engine_copy_baseline_product_q8192_layer0_source_values(
    qrt_engine_t *engine,
    const qrt_qwen36_plain_sequence_state_t *state
) {
    size_t stage_index;

    if (engine == NULL || state == NULL) {
        return QRT_STATUS_INVALID_ARGUMENT;
    }
    for (stage_index = 0u;
         stage_index <
             (size_t)QRT_QWEN36_PRODUCT_Q8192_LAYER0_SOURCE_STAGE_COUNT;
         ++stage_index) {
        const size_t value_bytes =
            state->product_q8192_layer0_source_stage_value_bytes[stage_index];
        free(engine->baseline_product_q8192_layer0_source_stage_values
                 [stage_index]);
        engine->baseline_product_q8192_layer0_source_stage_values
            [stage_index] = NULL;
        engine->baseline_product_q8192_layer0_source_stage_value_bytes
            [stage_index] = 0u;
        engine->baseline_product_q8192_layer0_source_stage_value_types
            [stage_index] = QRT_QWEN36_SOURCE_VALUE_TYPE_NONE;
        engine->baseline_product_q8192_layer0_source_stage_values_present
            [stage_index] = 0u;

        if (state->product_q8192_layer0_source_stage_values_present
                    [stage_index] == 0u ||
            state->product_q8192_layer0_source_stage_values[stage_index] ==
                NULL ||
            value_bytes == 0u) {
            continue;
        }
        engine->baseline_product_q8192_layer0_source_stage_values
            [stage_index] = (uint8_t *)malloc(value_bytes);
        if (engine->baseline_product_q8192_layer0_source_stage_values
                [stage_index] == NULL) {
            return QRT_STATUS_OUT_OF_MEMORY;
        }
        memcpy(
            engine->baseline_product_q8192_layer0_source_stage_values
                [stage_index],
            state->product_q8192_layer0_source_stage_values[stage_index],
            value_bytes
        );
        engine->baseline_product_q8192_layer0_source_stage_value_bytes
            [stage_index] = value_bytes;
        engine->baseline_product_q8192_layer0_source_stage_value_types
            [stage_index] =
            state->product_q8192_layer0_source_stage_value_types[stage_index];
        engine->baseline_product_q8192_layer0_source_stage_values_present
            [stage_index] = 1u;
    }
    return QRT_STATUS_OK;
}

#ifdef _WIN32
static qrt_status_t qrt_engine_store_baseline_product_q8192_frontier_export(
    qrt_engine_t *engine,
    const qrt_qwen36_layer1_frontier_buffer_export_t *frontier,
    size_t context_token_count,
    unsigned int zero_linear_core_state
) {
    const size_t token_count = frontier != NULL ? frontier->token_count : 0u;
    const size_t hidden_value_count =
        frontier != NULL ? frontier->hidden_value_count : 0u;
    const size_t token_bytes = token_count * sizeof(frontier->token_ids[0]);
    const size_t hidden_bytes =
        hidden_value_count * sizeof(frontier->hidden_values[0]);
    const size_t layer0_stage_count =
        (size_t)QRT_QWEN36_PRODUCT_Q8192_LAYER0_SOURCE_STAGE_COUNT;
    size_t stage_index;

    if (engine == NULL || frontier == NULL || frontier->token_ids == NULL ||
        frontier->hidden_values == NULL || token_count == 0u ||
        hidden_value_count != token_count * (size_t)QRT_QWEN36_HIDDEN_SIZE) {
        return QRT_STATUS_INVALID_ARGUMENT;
    }
    if (token_count > SIZE_MAX / sizeof(frontier->token_ids[0]) ||
        hidden_value_count > SIZE_MAX / sizeof(frontier->hidden_values[0])) {
        return QRT_STATUS_OUT_OF_MEMORY;
    }

    qrt_engine_clear_baseline_product_q8192_frontier_buffer(engine);
    engine->baseline_product_q8192_layer1_frontier_buffer_token_ids =
        (uint32_t *)malloc(token_bytes);
    engine->baseline_product_q8192_layer1_frontier_buffer_hidden_values =
        (float *)malloc(hidden_bytes);
    if (engine->baseline_product_q8192_layer1_frontier_buffer_token_ids == NULL ||
        engine->baseline_product_q8192_layer1_frontier_buffer_hidden_values ==
            NULL) {
        qrt_engine_clear_baseline_product_q8192_frontier_buffer(engine);
        return QRT_STATUS_OUT_OF_MEMORY;
    }
    memcpy(
        engine->baseline_product_q8192_layer1_frontier_buffer_token_ids,
        frontier->token_ids,
        token_bytes
    );
    memcpy(
        engine->baseline_product_q8192_layer1_frontier_buffer_hidden_values,
        frontier->hidden_values,
        hidden_bytes
    );

    engine->baseline_product_layer1_frontier_token_count = token_count;
    engine->baseline_product_layer1_frontier_hidden_value_count =
        hidden_value_count;
    engine->baseline_product_layer1_frontier_digest_fnv1a64 =
        frontier->product_path_digest_fnv1a64;
    engine->baseline_product_layer1_frontier_last_output_fnv1a64 =
        frontier->last_output_fnv1a64;
    engine->baseline_product_layer1_frontier_product_path =
        frontier->product_path != 0u ? 1u : 0u;

    engine->baseline_product_q8192_layer1_frontier_context_token_count =
        context_token_count;
    engine->baseline_product_q8192_layer1_frontier_context_match =
        context_token_count ==
                (size_t)QRT_QWEN36_PRODUCT_Q8192_CONTEXT_TOKENS
            ? 1u
            : 0u;
    engine->baseline_product_q8192_layer1_frontier_synthetic_hidden_seed = 1u;
    engine->baseline_product_q8192_layer1_frontier_linear_core_state_reset =
        zero_linear_core_state != 0u ? 1u : 0u;
    engine->baseline_product_q8192_layer1_frontier_source_window_token_count =
        frontier->source_window_token_count;
    engine->baseline_product_q8192_layer1_frontier_token_count = token_count;
    engine->baseline_product_q8192_layer1_frontier_hidden_value_count =
        hidden_value_count;
    engine->baseline_product_q8192_layer1_frontier_source_window_token_ids_fnv1a64 =
        frontier->source_window_token_ids_fnv1a64;
    engine->baseline_product_q8192_layer1_frontier_token_ids_fnv1a64 =
        frontier->token_ids_fnv1a64;
    engine->baseline_product_q8192_layer1_frontier_buffer_hidden_values_fnv1a64 =
        frontier->hidden_values_fnv1a64 != UINT64_C(0)
            ? frontier->hidden_values_fnv1a64
            : qrt_fnv1a64_f32(frontier->hidden_values, hidden_value_count);
    engine->baseline_product_q8192_layer1_frontier_digest_fnv1a64 =
        frontier->product_path_digest_fnv1a64;
    engine->baseline_product_q8192_layer1_frontier_last_output_fnv1a64 =
        frontier->last_output_fnv1a64;
    engine->baseline_product_q8192_layer1_frontier_complete = 1u;
    engine->baseline_product_q8192_layer1_frontier_product_path =
        frontier->product_path != 0u &&
                engine->baseline_product_q8192_layer1_frontier_context_match !=
                    0u &&
                frontier->product_path_digest_fnv1a64 !=
                    UINT64_C(1469598103934665603)
            ? 1u
            : 0u;

    engine->baseline_product_q8192_layer0_source_stage_count =
        frontier->layer0_source_stage_count <= layer0_stage_count
            ? frontier->layer0_source_stage_count
            : layer0_stage_count;
    qrt_qwen36_product_q8192_reset_stage_digests(
        layer0_stage_count,
        engine->baseline_product_q8192_layer0_source_stage_token_counts,
        engine->baseline_product_q8192_layer0_source_stage_digest_fnv1a64,
        engine->baseline_product_q8192_layer0_source_stage_last_fnv1a64
    );
    for (stage_index = 0u;
         frontier->layer0_source_stages != NULL &&
         stage_index < engine->baseline_product_q8192_layer0_source_stage_count;
         ++stage_index) {
        const qrt_qwen36_layer0_source_stage_export_t *stage =
            &frontier->layer0_source_stages[stage_index];
        const size_t stage_id = (size_t)stage->stage_id;

        if (stage_id >= layer0_stage_count) {
            continue;
        }
        engine->baseline_product_q8192_layer0_source_stage_token_counts
            [stage_id] = stage->token_count;
        engine->baseline_product_q8192_layer0_source_stage_digest_fnv1a64
            [stage_id] = stage->digest_fnv1a64;
        engine->baseline_product_q8192_layer0_source_stage_last_fnv1a64
            [stage_id] = stage->last_fnv1a64;
        free(engine->baseline_product_q8192_layer0_source_stage_values
                 [stage_id]);
        engine->baseline_product_q8192_layer0_source_stage_values[stage_id] =
            NULL;
        engine->baseline_product_q8192_layer0_source_stage_value_bytes
            [stage_id] = 0u;
        engine->baseline_product_q8192_layer0_source_stage_value_types
            [stage_id] = QRT_QWEN36_SOURCE_VALUE_TYPE_NONE;
        engine->baseline_product_q8192_layer0_source_stage_values_present
            [stage_id] = 0u;
        if (stage->values_present == 0u || stage->values == NULL ||
            stage->value_bytes == 0u) {
            continue;
        }
        engine->baseline_product_q8192_layer0_source_stage_values[stage_id] =
            (uint8_t *)malloc(stage->value_bytes);
        if (engine->baseline_product_q8192_layer0_source_stage_values
                [stage_id] == NULL) {
            qrt_engine_clear_baseline_product_q8192_frontier_buffer(engine);
            return QRT_STATUS_OUT_OF_MEMORY;
        }
        memcpy(
            engine->baseline_product_q8192_layer0_source_stage_values[stage_id],
            stage->values,
            stage->value_bytes
        );
        engine->baseline_product_q8192_layer0_source_stage_value_bytes
            [stage_id] = stage->value_bytes;
        engine->baseline_product_q8192_layer0_source_stage_value_types
            [stage_id] = stage->value_type;
        engine->baseline_product_q8192_layer0_source_stage_values_present
            [stage_id] = 1u;
    }

    engine->baseline_product_q8192_layer1_frontier_stage_count = 0u;
    qrt_qwen36_product_q8192_reset_stage_digests(
        (size_t)QRT_QWEN36_PRODUCT_Q8192_LAYER1_STAGE_COUNT,
        engine->baseline_product_q8192_layer1_frontier_stage_token_counts,
        engine->baseline_product_q8192_layer1_frontier_stage_digest_fnv1a64,
        engine->baseline_product_q8192_layer1_frontier_stage_last_fnv1a64
    );

    return QRT_STATUS_OK;
}
#endif

static void qrt_qwen36_product_q8192_update_layer0_source_stage_digest(
    qrt_qwen36_plain_sequence_state_t *state,
    qrt_qwen36_product_q8192_layer0_source_stage_t stage,
    unsigned int layer_index,
    size_t token_position,
    uint64_t stage_hash
) {
    if (state == NULL ||
        state->product_q8192_layer1_frontier_enabled == 0u ||
        layer_index != 0u ||
        !qrt_qwen36_product_q8192_source_window_contains(state, token_position)) {
        return;
    }
    qrt_qwen36_product_q8192_update_stage_digest_arrays(
        (size_t)QRT_QWEN36_PRODUCT_Q8192_LAYER0_SOURCE_STAGE_COUNT,
        state->product_q8192_layer0_source_stage_token_counts,
        state->product_q8192_layer0_source_stage_digest_fnv1a64,
        state->product_q8192_layer0_source_stage_last_fnv1a64,
        (size_t)stage,
        layer_index,
        token_position,
        stage_hash
    );
}

static void qrt_qwen36_product_q8192_update_stage_digest(
    qrt_qwen36_plain_sequence_state_t *state,
    qrt_qwen36_product_q8192_layer1_stage_t stage,
    unsigned int layer_index,
    size_t token_position,
    uint64_t stage_hash
) {
    if (state == NULL ||
        state->product_q8192_layer1_frontier_enabled == 0u ||
        layer_index != 1u) {
        return;
    }
    qrt_qwen36_product_q8192_update_stage_digest_arrays(
        (size_t)QRT_QWEN36_PRODUCT_Q8192_LAYER1_STAGE_COUNT,
        state->product_q8192_layer1_frontier_stage_token_counts,
        state->product_q8192_layer1_frontier_stage_digest_fnv1a64,
        state->product_q8192_layer1_frontier_stage_last_fnv1a64,
        (size_t)stage,
        layer_index,
        token_position,
        stage_hash
    );
}

static void qrt_qwen36_plain_sequence_state_free(
    qrt_qwen36_plain_sequence_state_t *state
) {
    unsigned int layer_index;
    size_t stage_index;

    if (state == NULL) {
        return;
    }

    for (layer_index = 0u;
         layer_index < (unsigned int)QRT_QWEN36_LAYER_COUNT;
         ++layer_index) {
        free(state->linear_qkv_rings[layer_index]);
        free(state->linear_core_states[layer_index]);
        free(state->full_kv_histories[layer_index]);
        free(state->prefix_full_kv_windows[layer_index]);
        free(state->prefix_full_kv_compressed_block_digests[layer_index]);
        free(state->prefix_full_kv_compressed_value_payloads[layer_index]);
    }
    free(state->product_q8192_layer1_frontier_hidden_values);
    for (stage_index = 0u;
         stage_index <
             (size_t)QRT_QWEN36_PRODUCT_Q8192_LAYER0_SOURCE_STAGE_COUNT;
         ++stage_index) {
        free(state->product_q8192_layer0_source_stage_values[stage_index]);
    }
    memset(state, 0, sizeof(*state));
}

static qrt_status_t qrt_qwen36_plain_sequence_state_alloc(
    qrt_engine_t *engine,
    qrt_qwen36_plain_sequence_state_t *state,
    size_t prompt_token_capacity,
    unsigned int layer_limit
) {
    const qrt_qwen36_baseline_plan_t *plan;
    unsigned int layer_index;
    unsigned int active_layer_count;
    const size_t linear_ring_elements =
        (size_t)QRT_QWEN36_LAYER0_LINEAR_ATTN_CONV_KERNEL *
        (size_t)QRT_QWEN36_LAYER0_LINEAR_ATTN_QKV_ROWS;
    const size_t linear_core_state_elements =
        (size_t)QRT_QWEN36_LAYER0_LINEAR_ATTN_VALUE_FEATURES *
        (size_t)QRT_QWEN36_LAYER0_LINEAR_ATTN_KEY_DIM;
    const size_t full_kv_token_elements =
        (size_t)QRT_QWEN36_LAYER3_SELF_ATTN_KV_TOKEN_FEATURES;

    if (engine == NULL || state == NULL || prompt_token_capacity == 0u ||
        layer_limit == 0u) {
        return QRT_STATUS_INVALID_ARGUMENT;
    }

    memset(state, 0, sizeof(*state));
    state->prompt_token_capacity = prompt_token_capacity;
    state->linear_state_digest_fnv1a64 = UINT64_C(1469598103934665603);
    state->full_kv_digest_fnv1a64 = UINT64_C(1469598103934665603);
    state->prefix_full_kv_window_seed_digest_fnv1a64 =
        UINT64_C(1469598103934665603);
    state->prefix_full_kv_window_input_digest_fnv1a64 =
        UINT64_C(1469598103934665603);
    state->prefix_full_kv_window_output_digest_fnv1a64 =
        UINT64_C(1469598103934665603);
    state->prefix_full_kv_compressed_seed_digest_fnv1a64 =
        UINT64_C(1469598103934665603);
    state->prefix_full_kv_compressed_position_digest_fnv1a64 =
        UINT64_C(1469598103934665603);
    state->prefix_full_kv_compressed_tail_digest_fnv1a64 =
        UINT64_C(1469598103934665603);
    state->prefix_full_kv_compressed_input_digest_fnv1a64 =
        UINT64_C(1469598103934665603);
    state->prefix_full_kv_compressed_output_digest_fnv1a64 =
        UINT64_C(1469598103934665603);
    state->prefix_full_kv_compressed_backend_span_input_digest_fnv1a64 =
        UINT64_C(1469598103934665603);
    state->prefix_full_kv_compressed_backend_span_output_digest_fnv1a64 =
        UINT64_C(1469598103934665603);
    state->prefix_full_kv_compressed_value_payload_digest_fnv1a64 =
        UINT64_C(1469598103934665603);
    state->product_layer1_frontier_digest_fnv1a64 =
        UINT64_C(1469598103934665603);
    state->product_q8192_layer1_frontier_digest_fnv1a64 =
        UINT64_C(1469598103934665603);
    qrt_qwen36_product_q8192_reset_stage_digests(
        (size_t)QRT_QWEN36_PRODUCT_Q8192_LAYER0_SOURCE_STAGE_COUNT,
        state->product_q8192_layer0_source_stage_token_counts,
        state->product_q8192_layer0_source_stage_digest_fnv1a64,
        state->product_q8192_layer0_source_stage_last_fnv1a64
    );
    qrt_qwen36_product_q8192_reset_stage_digests(
        (size_t)QRT_QWEN36_PRODUCT_Q8192_LAYER1_STAGE_COUNT,
        state->product_q8192_layer1_frontier_stage_token_counts,
        state->product_q8192_layer1_frontier_stage_digest_fnv1a64,
        state->product_q8192_layer1_frontier_stage_last_fnv1a64
    );

    plan = qrt_qwen36_baseline_plan();
    if (plan == NULL || plan->layer_count != QRT_QWEN36_LAYER_COUNT) {
        qrt_engine_set_token_request_failure(
            engine,
            "baseline_plain_sequence_state_descriptor",
            "baseline plain sequence state descriptor plan is invalid"
        );
        return QRT_STATUS_UNSUPPORTED;
    }

    active_layer_count =
        layer_limit > plan->layer_count ? plan->layer_count : layer_limit;
    for (layer_index = 0u; layer_index < active_layer_count; ++layer_index) {
        const qrt_qwen36_baseline_layer_descriptor_t *desc =
            qrt_qwen36_baseline_layer_descriptor(layer_index);
        if (desc == NULL || desc->layer_index != layer_index) {
            qrt_engine_set_token_request_failure(
                engine,
                "baseline_plain_sequence_state_descriptor",
                "baseline plain sequence state layer descriptor is invalid"
            );
            qrt_qwen36_plain_sequence_state_free(state);
            return QRT_STATUS_UNSUPPORTED;
        }

        if (desc->attention_kind == QRT_QWEN36_BASELINE_ATTENTION_LINEAR) {
            state->linear_qkv_rings[layer_index] =
                (float *)calloc(linear_ring_elements, sizeof(float));
            state->linear_core_states[layer_index] =
                (float *)calloc(linear_core_state_elements, sizeof(float));
            if (state->linear_qkv_rings[layer_index] == NULL ||
                state->linear_core_states[layer_index] == NULL) {
                qrt_engine_set_token_request_failure(
                    engine,
                    "baseline_plain_sequence_linear_state_alloc",
                    "baseline plain sequence linear-attention state allocation failed"
                );
                qrt_qwen36_plain_sequence_state_free(state);
                return QRT_STATUS_OUT_OF_MEMORY;
            }
            state->linear_state_bytes +=
                (uint64_t)((linear_ring_elements + linear_core_state_elements) *
                    sizeof(float));
        } else if (desc->attention_kind == QRT_QWEN36_BASELINE_ATTENTION_FULL) {
            state->full_kv_histories[layer_index] = (float *)calloc(
                prompt_token_capacity * full_kv_token_elements,
                sizeof(float)
            );
            if (state->full_kv_histories[layer_index] == NULL) {
                qrt_engine_set_token_request_failure(
                    engine,
                    "baseline_plain_sequence_full_kv_alloc",
                    "baseline plain sequence full-attention KV history allocation failed"
                );
                qrt_qwen36_plain_sequence_state_free(state);
                return QRT_STATUS_OUT_OF_MEMORY;
            }
            state->full_kv_bytes +=
                (uint64_t)(prompt_token_capacity * full_kv_token_elements *
                    sizeof(float));
        }
    }

    return QRT_STATUS_OK;
}

static float qrt_prefix_cache_tensor_seed_value(
    uint64_t seed,
    unsigned int layer_index,
    size_t element_index,
    uint64_t salt
) {
    uint64_t hash = seed;
    int bucket;

    hash ^= ((uint64_t)layer_index + UINT64_C(0x9e3779b97f4a7c15));
    hash *= UINT64_C(1099511628211);
    hash ^= (uint64_t)element_index + salt;
    hash ^= hash >> 33;
    hash *= UINT64_C(0xff51afd7ed558ccd);
    hash ^= hash >> 33;
    bucket = (int)(hash % UINT64_C(17)) - 8;
    return (float)bucket * 0.000000125f;
}

static qrt_status_t qrt_qwen36_plain_sequence_state_seed_prefix_linear_state(
    qrt_engine_t *engine,
    qrt_qwen36_plain_sequence_state_t *state,
    unsigned int layer_limit
) {
    const qrt_qwen36_baseline_plan_t *plan;
    const size_t linear_ring_elements =
        (size_t)QRT_QWEN36_LAYER0_LINEAR_ATTN_CONV_KERNEL *
        (size_t)QRT_QWEN36_LAYER0_LINEAR_ATTN_QKV_ROWS;
    const size_t linear_core_state_elements =
        (size_t)QRT_QWEN36_LAYER0_LINEAR_ATTN_VALUE_FEATURES *
        (size_t)QRT_QWEN36_LAYER0_LINEAR_ATTN_KEY_DIM;
    uint64_t seed_digest;
    unsigned int layer_index;
    unsigned int active_layer_count;
    size_t seeded_layer_count = 0u;
    size_t seeded_value_count = 0u;

    if (engine == NULL || state == NULL) {
        return QRT_STATUS_INVALID_ARGUMENT;
    }
    if (!engine->prefix_cache_state_attached ||
        !engine->prefix_cache_tensor_linear_state_requested) {
        return QRT_STATUS_OK;
    }

    plan = qrt_qwen36_baseline_plan();
    if (plan == NULL || plan->layer_count != QRT_QWEN36_LAYER_COUNT) {
        qrt_engine_set_token_request_failure(
            engine,
            "prefix_tensor_linear_state_descriptor",
            "prefix tensor linear state seed descriptor plan is invalid"
        );
        return QRT_STATUS_UNSUPPORTED;
    }

    seed_digest = qrt_fnv1a64_bytes(
        "Qwen3.6/H-PREFIX-001/prefix-tensor-linear-state-seed-v1",
        sizeof("Qwen3.6/H-PREFIX-001/prefix-tensor-linear-state-seed-v1")
    );
    seed_digest = qrt_fnv1a64_update_bytes(
        seed_digest,
        &engine->prefix_cache_state_digest_fnv1a64,
        sizeof(engine->prefix_cache_state_digest_fnv1a64)
    );
    seed_digest = qrt_fnv1a64_update_bytes(
        seed_digest,
        &engine->prefix_cache_cached_prefix_tokens,
        sizeof(engine->prefix_cache_cached_prefix_tokens)
    );

    active_layer_count =
        layer_limit > plan->layer_count ? plan->layer_count : layer_limit;
    for (layer_index = 0u; layer_index < active_layer_count; ++layer_index) {
        const qrt_qwen36_baseline_layer_descriptor_t *desc =
            qrt_qwen36_baseline_layer_descriptor(layer_index);
        float *ring;
        float *core_state;
        size_t element_index;
        uint64_t ring_hash;
        uint64_t core_hash;

        if (desc == NULL || desc->layer_index != layer_index) {
            qrt_engine_set_token_request_failure(
                engine,
                "prefix_tensor_linear_state_descriptor",
                "prefix tensor linear state layer descriptor is invalid"
            );
            return QRT_STATUS_UNSUPPORTED;
        }
        if (desc->attention_kind != QRT_QWEN36_BASELINE_ATTENTION_LINEAR) {
            continue;
        }

        ring = state->linear_qkv_rings[layer_index];
        core_state = state->linear_core_states[layer_index];
        if (ring == NULL || core_state == NULL) {
            qrt_engine_set_token_request_failure(
                engine,
                "prefix_tensor_linear_state_buffer",
                "prefix tensor linear state buffer is missing"
            );
            return QRT_STATUS_UNSUPPORTED;
        }

        for (element_index = 0u;
             element_index < linear_ring_elements;
             ++element_index) {
            ring[element_index] = qrt_prefix_cache_tensor_seed_value(
                engine->prefix_cache_state_digest_fnv1a64,
                layer_index,
                element_index,
                UINT64_C(0x5152564c494e4752)
            );
        }
        for (element_index = 0u;
             element_index < linear_core_state_elements;
             ++element_index) {
            core_state[element_index] = qrt_prefix_cache_tensor_seed_value(
                engine->prefix_cache_state_digest_fnv1a64,
                layer_index,
                element_index,
                UINT64_C(0x515256434f524553)
            );
        }

        ring_hash = qrt_fnv1a64_f32(ring, linear_ring_elements);
        core_hash = qrt_fnv1a64_f32(core_state, linear_core_state_elements);
        seed_digest = qrt_fnv1a64_update_bytes(
            seed_digest,
            &layer_index,
            sizeof(layer_index)
        );
        seed_digest = qrt_fnv1a64_update_bytes(
            seed_digest,
            &ring_hash,
            sizeof(ring_hash)
        );
        seed_digest = qrt_fnv1a64_update_bytes(
            seed_digest,
            &core_hash,
            sizeof(core_hash)
        );
        ++seeded_layer_count;
        seeded_value_count += linear_ring_elements + linear_core_state_elements;
    }

    engine->prefix_cache_tensor_linear_state_seeded =
        seeded_layer_count == (size_t)QRT_QWEN36_LINEAR_ATTENTION_LAYERS &&
                seed_digest != UINT64_C(1469598103934665603)
            ? 1
            : 0;
    engine->prefix_cache_tensor_linear_seed_layer_count = seeded_layer_count;
    engine->prefix_cache_tensor_linear_seed_value_count = seeded_value_count;
    engine->prefix_cache_tensor_linear_seed_digest_fnv1a64 = seed_digest;
    return engine->prefix_cache_tensor_linear_state_seeded
        ? QRT_STATUS_OK
        : QRT_STATUS_UNSUPPORTED;
}

static qrt_status_t qrt_qwen36_plain_sequence_state_seed_prefix_full_kv_window_state(
    qrt_engine_t *engine,
    qrt_qwen36_plain_sequence_state_t *state,
    unsigned int layer_limit
) {
    const qrt_qwen36_baseline_plan_t *plan;
    const size_t full_kv_token_elements =
        (size_t)QRT_QWEN36_LAYER3_SELF_ATTN_KV_TOKEN_FEATURES;
    const size_t window_tokens =
        (size_t)QRT_PREFIX_CACHE_FULL_KV_WINDOW_TOKENS;
    const size_t window_elements = window_tokens * full_kv_token_elements;
    uint64_t seed_digest;
    unsigned int layer_index;
    unsigned int active_layer_count;
    size_t seeded_layer_count = 0u;
    size_t seeded_value_count = 0u;
    size_t absolute_start_position;
    size_t absolute_last_position;

    if (engine == NULL || state == NULL) {
        return QRT_STATUS_INVALID_ARGUMENT;
    }
    if (!engine->prefix_cache_state_attached ||
        !engine->prefix_cache_tensor_full_kv_window_state_requested) {
        return QRT_STATUS_OK;
    }
    if (window_tokens == 0u ||
        engine->prefix_cache_cached_prefix_tokens < window_tokens) {
        qrt_engine_set_token_request_failure(
            engine,
            "prefix_tensor_full_kv_window_position",
            "prefix full-KV window cannot be placed before the request start"
        );
        return QRT_STATUS_UNSUPPORTED;
    }

    plan = qrt_qwen36_baseline_plan();
    if (plan == NULL || plan->layer_count != QRT_QWEN36_LAYER_COUNT) {
        qrt_engine_set_token_request_failure(
            engine,
            "prefix_tensor_full_kv_window_descriptor",
            "prefix full-KV window seed descriptor plan is invalid"
        );
        return QRT_STATUS_UNSUPPORTED;
    }

    absolute_start_position =
        engine->prefix_cache_cached_prefix_tokens - window_tokens;
    absolute_last_position = engine->prefix_cache_cached_prefix_tokens - 1u;
    seed_digest = qrt_fnv1a64_bytes(
        "Qwen3.6/H-PREFIX-001/prefix-tensor-full-kv-window-seed-v1",
        sizeof("Qwen3.6/H-PREFIX-001/prefix-tensor-full-kv-window-seed-v1")
    );
    seed_digest = qrt_fnv1a64_update_bytes(
        seed_digest,
        &engine->prefix_cache_state_digest_fnv1a64,
        sizeof(engine->prefix_cache_state_digest_fnv1a64)
    );
    seed_digest = qrt_fnv1a64_update_bytes(
        seed_digest,
        &engine->prefix_cache_cached_prefix_tokens,
        sizeof(engine->prefix_cache_cached_prefix_tokens)
    );
    seed_digest = qrt_fnv1a64_update_bytes(
        seed_digest,
        &absolute_start_position,
        sizeof(absolute_start_position)
    );
    seed_digest = qrt_fnv1a64_update_bytes(
        seed_digest,
        &absolute_last_position,
        sizeof(absolute_last_position)
    );

    active_layer_count =
        layer_limit > plan->layer_count ? plan->layer_count : layer_limit;
    for (layer_index = 0u; layer_index < active_layer_count; ++layer_index) {
        const qrt_qwen36_baseline_layer_descriptor_t *desc =
            qrt_qwen36_baseline_layer_descriptor(layer_index);
        float *window;
        size_t element_index;
        uint64_t window_hash;

        if (desc == NULL || desc->layer_index != layer_index) {
            qrt_engine_set_token_request_failure(
                engine,
                "prefix_tensor_full_kv_window_descriptor",
                "prefix full-KV window seed layer descriptor is invalid"
            );
            return QRT_STATUS_UNSUPPORTED;
        }
        if (desc->attention_kind != QRT_QWEN36_BASELINE_ATTENTION_FULL) {
            continue;
        }

        window = (float *)calloc(window_elements, sizeof(window[0]));
        if (window == NULL) {
            qrt_engine_set_token_request_failure(
                engine,
                "prefix_tensor_full_kv_window_alloc",
                "prefix full-KV window state allocation failed"
            );
            return QRT_STATUS_OUT_OF_MEMORY;
        }
        state->prefix_full_kv_windows[layer_index] = window;

        for (element_index = 0u; element_index < window_elements; ++element_index) {
            const size_t token_offset = element_index / full_kv_token_elements;
            const size_t element_in_token = element_index % full_kv_token_elements;
            const size_t absolute_element_index =
                (absolute_start_position + token_offset) *
                    full_kv_token_elements +
                element_in_token;
            window[element_index] = qrt_prefix_cache_tensor_seed_value(
                engine->prefix_cache_state_digest_fnv1a64,
                layer_index,
                absolute_element_index,
                UINT64_C(0x51525646554c4b56)
            );
        }

        window_hash = qrt_fnv1a64_f32(window, window_elements);
        seed_digest = qrt_fnv1a64_update_bytes(
            seed_digest,
            &layer_index,
            sizeof(layer_index)
        );
        seed_digest = qrt_fnv1a64_update_bytes(
            seed_digest,
            &window_hash,
            sizeof(window_hash)
        );
        ++seeded_layer_count;
        seeded_value_count += window_elements;
    }

    state->prefix_full_kv_window_enabled =
        seeded_layer_count == (size_t)QRT_QWEN36_FULL_ATTENTION_LAYERS &&
                seeded_value_count != 0u
            ? 1u
            : 0u;
    state->prefix_full_kv_window_token_count = window_tokens;
    state->prefix_full_kv_window_layer_count = seeded_layer_count;
    state->prefix_full_kv_window_value_count = seeded_value_count;
    state->prefix_full_kv_cached_prefix_tokens =
        engine->prefix_cache_cached_prefix_tokens;
    state->prefix_full_kv_absolute_start_position = absolute_start_position;
    state->prefix_full_kv_absolute_last_position = absolute_last_position;
    state->prefix_full_kv_window_seed_digest_fnv1a64 = seed_digest;

    engine->prefix_cache_tensor_full_kv_state_seeded =
        state->prefix_full_kv_window_enabled ? 1 : 0;
    engine->prefix_cache_tensor_full_kv_seed_layer_count = seeded_layer_count;
    engine->prefix_cache_tensor_full_kv_seed_value_count = seeded_value_count;
    engine->prefix_cache_tensor_full_kv_window_token_count = window_tokens;
    engine->prefix_cache_tensor_full_kv_cached_prefix_tokens =
        engine->prefix_cache_cached_prefix_tokens;
    engine->prefix_cache_tensor_full_kv_absolute_start_position =
        absolute_start_position;
    engine->prefix_cache_tensor_full_kv_absolute_last_position =
        absolute_last_position;
    engine->prefix_cache_tensor_full_kv_seed_digest_fnv1a64 = seed_digest;
    return state->prefix_full_kv_window_enabled
        ? QRT_STATUS_OK
        : QRT_STATUS_UNSUPPORTED;
}

static uint64_t qrt_prefix_cache_full_kv_compressed_block_digest(
    uint64_t state_seed,
    unsigned int layer_index,
    size_t block_index,
    size_t block_start_token,
    size_t block_tokens,
    size_t full_kv_token_elements
) {
    const size_t block_last_token = block_start_token + block_tokens - 1u;
    const size_t sample_indices[4] = {
        block_start_token * full_kv_token_elements,
        block_start_token * full_kv_token_elements + full_kv_token_elements - 1u,
        block_last_token * full_kv_token_elements,
        block_last_token * full_kv_token_elements + full_kv_token_elements - 1u
    };
    float samples[4];
    uint64_t digest = qrt_fnv1a64_bytes(
        "Qwen3.6/H-PREFIX-001/full-kv-compressed-block-v1",
        sizeof("Qwen3.6/H-PREFIX-001/full-kv-compressed-block-v1")
    );
    size_t sample_index;

    digest = qrt_fnv1a64_update_bytes(
        digest,
        &layer_index,
        sizeof(layer_index)
    );
    digest = qrt_fnv1a64_update_bytes(
        digest,
        &block_index,
        sizeof(block_index)
    );
    digest = qrt_fnv1a64_update_bytes(
        digest,
        &block_start_token,
        sizeof(block_start_token)
    );
    digest = qrt_fnv1a64_update_bytes(
        digest,
        &block_tokens,
        sizeof(block_tokens)
    );

    for (sample_index = 0u; sample_index < 4u; ++sample_index) {
        samples[sample_index] = qrt_prefix_cache_tensor_seed_value(
            state_seed,
            layer_index,
            sample_indices[sample_index],
            UINT64_C(0x51525646554c4b56)
        );
    }
    digest = qrt_fnv1a64_update_bytes(digest, samples, sizeof(samples));
    return digest;
}

static void qrt_prefix_cache_full_kv_compressed_value_payload_build(
    uint64_t state_seed,
    unsigned int layer_index,
    size_t block_index,
    size_t block_start_token,
    size_t block_tokens,
    size_t kv_features,
    qrt_qwen36_prefix_full_kv_compressed_value_payload_t *out_payload
) {
    const size_t block_last_token = block_start_token + block_tokens - 1u;
    const size_t token_indices[QRT_PREFIX_CACHE_FULL_KV_COMPRESSED_PAYLOAD_SAMPLES] = {
        block_start_token,
        block_start_token + block_tokens / 3u,
        block_start_token + (2u * block_tokens) / 3u,
        block_last_token
    };
    const size_t feature_indices[QRT_PREFIX_CACHE_FULL_KV_COMPRESSED_PAYLOAD_SAMPLES] = {
        0u,
        kv_features / 3u,
        (2u * kv_features) / 3u,
        kv_features - 1u
    };
    const size_t full_kv_token_elements = kv_features * 2u;
    uint64_t key_digest;
    uint64_t value_digest;
    uint64_t summary_digest;
    size_t sample_index;

    if (out_payload == NULL || block_tokens == 0u || kv_features == 0u) {
        return;
    }

    memset(out_payload, 0, sizeof(*out_payload));
    out_payload->block_start_token = block_start_token;
    out_payload->block_token_count = block_tokens;

    key_digest = qrt_fnv1a64_bytes(
        "Qwen3.6/H-PREFIX-001/full-kv-compressed-key-payload-v1",
        sizeof("Qwen3.6/H-PREFIX-001/full-kv-compressed-key-payload-v1")
    );
    value_digest = qrt_fnv1a64_bytes(
        "Qwen3.6/H-PREFIX-001/full-kv-compressed-value-payload-v1",
        sizeof("Qwen3.6/H-PREFIX-001/full-kv-compressed-value-payload-v1")
    );
    for (sample_index = 0u;
         sample_index < QRT_PREFIX_CACHE_FULL_KV_COMPRESSED_PAYLOAD_SAMPLES;
         ++sample_index) {
        const size_t token_index = token_indices[sample_index];
        const size_t feature_index = feature_indices[sample_index];
        const size_t key_element_index =
            token_index * full_kv_token_elements + feature_index;
        const size_t value_element_index =
            token_index * full_kv_token_elements + kv_features + feature_index;

        out_payload->key_samples[sample_index] =
            qrt_prefix_cache_tensor_seed_value(
                state_seed,
                layer_index,
                key_element_index,
                UINT64_C(0x51525646554c4b56)
            );
        out_payload->value_samples[sample_index] =
            qrt_prefix_cache_tensor_seed_value(
                state_seed,
                layer_index,
                value_element_index,
                UINT64_C(0x51525646554c4b56)
            );
    }

    key_digest = qrt_fnv1a64_update_bytes(
        key_digest,
        &layer_index,
        sizeof(layer_index)
    );
    key_digest = qrt_fnv1a64_update_bytes(
        key_digest,
        &block_index,
        sizeof(block_index)
    );
    key_digest = qrt_fnv1a64_update_bytes(
        key_digest,
        out_payload->key_samples,
        sizeof(out_payload->key_samples)
    );
    value_digest = qrt_fnv1a64_update_bytes(
        value_digest,
        &layer_index,
        sizeof(layer_index)
    );
    value_digest = qrt_fnv1a64_update_bytes(
        value_digest,
        &block_index,
        sizeof(block_index)
    );
    value_digest = qrt_fnv1a64_update_bytes(
        value_digest,
        out_payload->value_samples,
        sizeof(out_payload->value_samples)
    );

    summary_digest = qrt_fnv1a64_bytes(
        "Qwen3.6/H-PREFIX-001/full-kv-compressed-payload-summary-v1",
        sizeof("Qwen3.6/H-PREFIX-001/full-kv-compressed-payload-summary-v1")
    );
    summary_digest = qrt_fnv1a64_update_bytes(
        summary_digest,
        &layer_index,
        sizeof(layer_index)
    );
    summary_digest = qrt_fnv1a64_update_bytes(
        summary_digest,
        &block_index,
        sizeof(block_index)
    );
    summary_digest = qrt_fnv1a64_update_bytes(
        summary_digest,
        &block_start_token,
        sizeof(block_start_token)
    );
    summary_digest = qrt_fnv1a64_update_bytes(
        summary_digest,
        &block_tokens,
        sizeof(block_tokens)
    );
    summary_digest = qrt_fnv1a64_update_bytes(
        summary_digest,
        &key_digest,
        sizeof(key_digest)
    );
    summary_digest = qrt_fnv1a64_update_bytes(
        summary_digest,
        &value_digest,
        sizeof(value_digest)
    );

    out_payload->key_digest_fnv1a64 = key_digest;
    out_payload->value_digest_fnv1a64 = value_digest;
    out_payload->summary_digest_fnv1a64 = summary_digest;
}

static qrt_status_t qrt_qwen36_prefix_full_kv_compressed_backend_span_handoff(
    const qrt_qwen36_plain_sequence_state_t *state,
    unsigned int layer_index,
    size_t token_position,
    size_t full_attention_position,
    uint64_t prefix_full_kv_window_hash,
    uint64_t full_kv_history_hash,
    uint64_t full_attention_context_hash,
    uint64_t *out_input_digest,
    uint64_t *out_output_digest
) {
    const uint64_t *block_digests;
    const qrt_qwen36_prefix_full_kv_compressed_value_payload_t *payloads;
    uint64_t table_digest;
    uint64_t input_digest;
    size_t block_index;

    if (state == NULL || out_input_digest == NULL ||
        out_output_digest == NULL ||
        layer_index >= (unsigned int)QRT_QWEN36_LAYER_COUNT ||
        state->prefix_full_kv_compressed_enabled == 0u ||
        state->prefix_full_kv_compressed_block_count == 0u ||
        state->prefix_full_kv_compressed_block_tokens == 0u ||
        state->prefix_full_kv_compressed_covered_tokens == 0u ||
        state->prefix_full_kv_compressed_tail_block_index >=
            state->prefix_full_kv_compressed_block_count) {
        return QRT_STATUS_INVALID_ARGUMENT;
    }

    block_digests =
        state->prefix_full_kv_compressed_block_digests[layer_index];
    payloads = state->prefix_full_kv_compressed_value_payloads[layer_index];
    if (block_digests == NULL || payloads == NULL ||
        state->prefix_full_kv_compressed_value_payload_enabled == 0u) {
        return QRT_STATUS_UNSUPPORTED;
    }

    table_digest = qrt_fnv1a64_bytes(
        "Qwen3.6/H-PREFIX-001/full-kv-compressed-backend-span-table-v1",
        sizeof(
            "Qwen3.6/H-PREFIX-001/full-kv-compressed-backend-span-table-v1"
        )
    );
    for (block_index = 0u;
         block_index < state->prefix_full_kv_compressed_block_count;
         ++block_index) {
        const size_t block_start_token =
            block_index * state->prefix_full_kv_compressed_block_tokens;
        const size_t block_end_token =
            block_start_token +
            state->prefix_full_kv_compressed_block_tokens - 1u;

        table_digest = qrt_fnv1a64_update_bytes(
            table_digest,
            &block_index,
            sizeof(block_index)
        );
        table_digest = qrt_fnv1a64_update_bytes(
            table_digest,
            &block_start_token,
            sizeof(block_start_token)
        );
        table_digest = qrt_fnv1a64_update_bytes(
            table_digest,
            &block_end_token,
            sizeof(block_end_token)
        );
        table_digest = qrt_fnv1a64_update_bytes(
            table_digest,
            &block_digests[block_index],
            sizeof(block_digests[block_index])
        );
        table_digest = qrt_fnv1a64_update_bytes(
            table_digest,
            &payloads[block_index].key_digest_fnv1a64,
            sizeof(payloads[block_index].key_digest_fnv1a64)
        );
        table_digest = qrt_fnv1a64_update_bytes(
            table_digest,
            &payloads[block_index].value_digest_fnv1a64,
            sizeof(payloads[block_index].value_digest_fnv1a64)
        );
        table_digest = qrt_fnv1a64_update_bytes(
            table_digest,
            &payloads[block_index].summary_digest_fnv1a64,
            sizeof(payloads[block_index].summary_digest_fnv1a64)
        );
        table_digest = qrt_fnv1a64_update_bytes(
            table_digest,
            payloads[block_index].key_samples,
            sizeof(payloads[block_index].key_samples)
        );
        table_digest = qrt_fnv1a64_update_bytes(
            table_digest,
            payloads[block_index].value_samples,
            sizeof(payloads[block_index].value_samples)
        );
    }

    input_digest = qrt_fnv1a64_bytes(
        "Qwen3.6/H-PREFIX-001/full-kv-compressed-backend-span-input-v1",
        sizeof(
            "Qwen3.6/H-PREFIX-001/full-kv-compressed-backend-span-input-v1"
        )
    );
    input_digest = qrt_fnv1a64_update_bytes(
        input_digest,
        &layer_index,
        sizeof(layer_index)
    );
    input_digest = qrt_fnv1a64_update_bytes(
        input_digest,
        &token_position,
        sizeof(token_position)
    );
    input_digest = qrt_fnv1a64_update_bytes(
        input_digest,
        &full_attention_position,
        sizeof(full_attention_position)
    );
    input_digest = qrt_fnv1a64_update_bytes(
        input_digest,
        &state->prefix_full_kv_compressed_block_count,
        sizeof(state->prefix_full_kv_compressed_block_count)
    );
    input_digest = qrt_fnv1a64_update_bytes(
        input_digest,
        &state->prefix_full_kv_compressed_block_tokens,
        sizeof(state->prefix_full_kv_compressed_block_tokens)
    );
    input_digest = qrt_fnv1a64_update_bytes(
        input_digest,
        &state->prefix_full_kv_compressed_covered_tokens,
        sizeof(state->prefix_full_kv_compressed_covered_tokens)
    );
    input_digest = qrt_fnv1a64_update_bytes(
        input_digest,
        &state->prefix_full_kv_compressed_tail_block_index,
        sizeof(state->prefix_full_kv_compressed_tail_block_index)
    );
    input_digest = qrt_fnv1a64_update_bytes(
        input_digest,
        &state->prefix_full_kv_compressed_tail_offset_tokens,
        sizeof(state->prefix_full_kv_compressed_tail_offset_tokens)
    );
    input_digest = qrt_fnv1a64_update_bytes(
        input_digest,
        &state->prefix_full_kv_compressed_seed_digest_fnv1a64,
        sizeof(state->prefix_full_kv_compressed_seed_digest_fnv1a64)
    );
    input_digest = qrt_fnv1a64_update_bytes(
        input_digest,
        &state->prefix_full_kv_compressed_position_digest_fnv1a64,
        sizeof(state->prefix_full_kv_compressed_position_digest_fnv1a64)
    );
    input_digest = qrt_fnv1a64_update_bytes(
        input_digest,
        &state->prefix_full_kv_compressed_tail_digest_fnv1a64,
        sizeof(state->prefix_full_kv_compressed_tail_digest_fnv1a64)
    );
    input_digest = qrt_fnv1a64_update_bytes(
        input_digest,
        &state->prefix_full_kv_compressed_value_payload_digest_fnv1a64,
        sizeof(state->prefix_full_kv_compressed_value_payload_digest_fnv1a64)
    );
    input_digest = qrt_fnv1a64_update_bytes(
        input_digest,
        &state->prefix_full_kv_compressed_value_payload_block_count,
        sizeof(state->prefix_full_kv_compressed_value_payload_block_count)
    );
    input_digest = qrt_fnv1a64_update_bytes(
        input_digest,
        &state->prefix_full_kv_compressed_value_payload_sample_count,
        sizeof(state->prefix_full_kv_compressed_value_payload_sample_count)
    );
    input_digest = qrt_fnv1a64_update_bytes(
        input_digest,
        &table_digest,
        sizeof(table_digest)
    );
    input_digest = qrt_fnv1a64_update_bytes(
        input_digest,
        &prefix_full_kv_window_hash,
        sizeof(prefix_full_kv_window_hash)
    );
    input_digest = qrt_fnv1a64_update_bytes(
        input_digest,
        &full_kv_history_hash,
        sizeof(full_kv_history_hash)
    );

    *out_input_digest = input_digest;
    *out_output_digest = qrt_fnv1a64_update_bytes(
        input_digest,
        &full_attention_context_hash,
        sizeof(full_attention_context_hash)
    );
    return QRT_STATUS_OK;
}

#ifdef _WIN32
static qrt_status_t
qrt_qwen36_prefix_full_kv_compressed_descriptor_batch_handoff(
    qrt_engine_t *engine,
    qrt_qwen36_plain_sequence_state_t *state,
    size_t token_position,
    const qrt_qwen36_prefill_descriptor_batch_result_t *result
) {
    uint64_t input_digest_accum;
    uint64_t output_digest_accum;
    size_t layer_index;

    if (engine == NULL || state == NULL || result == NULL) {
        return QRT_STATUS_INVALID_ARGUMENT;
    }
    if (!engine->prefix_cache_state_attached ||
        !engine->prefix_cache_tensor_full_kv_compressed_state_seeded) {
        return QRT_STATUS_OK;
    }
    if (result->descriptor_batch_digest_fnv1a64 == UINT64_C(0) ||
        result->descriptor_batch_digest_fnv1a64 ==
            UINT64_C(1469598103934665603) ||
        result->continuation.digest_fnv1a64 == UINT64_C(0) ||
        state->prefix_full_kv_compressed_enabled == 0u ||
        state->prefix_full_kv_compressed_value_payload_enabled == 0u) {
        return QRT_STATUS_UNSUPPORTED;
    }

    input_digest_accum =
        state->prefix_full_kv_compressed_input_digest_fnv1a64;
    output_digest_accum =
        state->prefix_full_kv_compressed_output_digest_fnv1a64;
    for (layer_index = 0u;
         layer_index < (size_t)QRT_QWEN36_LAYER_COUNT;
         ++layer_index) {
        uint64_t prefix_window_hash;
        uint64_t full_kv_history_hash;
        uint64_t full_attention_context_hash;
        uint64_t compressed_input_digest;
        uint64_t compressed_output_digest;
        uint64_t layer_bit;
        qrt_status_t status;

        if ((layer_index % 4u) != 3u) {
            continue;
        }

        prefix_window_hash =
            qrt_fnv1a64_update_bytes(
                state->prefix_full_kv_window_seed_digest_fnv1a64,
                &layer_index,
                sizeof(layer_index)
            );
        full_kv_history_hash =
            qrt_fnv1a64_bytes(
                "Qwen3.6/H-PREFIX-001/descriptor-batch-full-kv-history-v1",
                sizeof(
                    "Qwen3.6/H-PREFIX-001/descriptor-batch-full-kv-history-v1"
                )
            );
        full_kv_history_hash =
            qrt_fnv1a64_update_bytes(
                full_kv_history_hash,
                &state->prefix_full_kv_compressed_seed_digest_fnv1a64,
                sizeof(state->prefix_full_kv_compressed_seed_digest_fnv1a64)
            );
        full_kv_history_hash =
            qrt_fnv1a64_update_bytes(
                full_kv_history_hash,
                &result->descriptor_batch_digest_fnv1a64,
                sizeof(result->descriptor_batch_digest_fnv1a64)
            );
        full_kv_history_hash =
            qrt_fnv1a64_update_bytes(
                full_kv_history_hash,
                &layer_index,
                sizeof(layer_index)
            );
        full_attention_context_hash =
            qrt_fnv1a64_bytes(
                "Qwen3.6/H-PREFIX-001/descriptor-batch-full-attention-context-v1",
                sizeof(
                    "Qwen3.6/H-PREFIX-001/descriptor-batch-full-attention-context-v1"
                )
            );
        full_attention_context_hash =
            qrt_fnv1a64_update_bytes(
                full_attention_context_hash,
                &result->continuation.digest_fnv1a64,
                sizeof(result->continuation.digest_fnv1a64)
            );
        full_attention_context_hash =
            qrt_fnv1a64_update_bytes(
                full_attention_context_hash,
                &result->continuation.token_loop_digest_fnv1a64,
                sizeof(result->continuation.token_loop_digest_fnv1a64)
            );
        full_attention_context_hash =
            qrt_fnv1a64_update_bytes(
                full_attention_context_hash,
                &layer_index,
                sizeof(layer_index)
            );

        status =
            qrt_qwen36_prefix_full_kv_compressed_backend_span_handoff(
                state,
                (unsigned int)layer_index,
                token_position,
                token_position,
                prefix_window_hash,
                full_kv_history_hash,
                full_attention_context_hash,
                &compressed_input_digest,
                &compressed_output_digest
            );
        if (status != QRT_STATUS_OK) {
            return status;
        }

        layer_bit =
            layer_index < 64u ? (UINT64_C(1) << layer_index) : UINT64_C(0);
        if (layer_bit != UINT64_C(0) &&
            (state->prefix_full_kv_compressed_backend_span_layer_mask &
             layer_bit) == UINT64_C(0)) {
            state->prefix_full_kv_compressed_backend_span_layer_mask |=
                layer_bit;
            ++state->prefix_full_kv_compressed_backend_span_layer_count;
        }
        ++state->prefix_full_kv_compressed_backend_span_eval_count;
        state->prefix_full_kv_compressed_backend_span_block_reference_count +=
            state->prefix_full_kv_compressed_block_count;
        state->prefix_full_kv_compressed_backend_span_token_reference_count +=
            state->prefix_full_kv_compressed_covered_tokens;
        state->prefix_full_kv_compressed_backend_span_handoff_evaluated = 1u;
        input_digest_accum =
            qrt_fnv1a64_update_bytes(
                input_digest_accum,
                &compressed_input_digest,
                sizeof(compressed_input_digest)
            );
        output_digest_accum =
            qrt_fnv1a64_update_bytes(
                output_digest_accum,
                &compressed_output_digest,
                sizeof(compressed_output_digest)
            );
    }

    state->prefix_full_kv_compressed_input_digest_fnv1a64 =
        input_digest_accum;
    state->prefix_full_kv_compressed_output_digest_fnv1a64 =
        output_digest_accum;
    state->prefix_full_kv_compressed_backend_span_input_digest_fnv1a64 =
        input_digest_accum;
    state->prefix_full_kv_compressed_backend_span_output_digest_fnv1a64 =
        output_digest_accum;
    engine->prefix_cache_tensor_full_kv_compressed_core_input_digest_fnv1a64 =
        input_digest_accum;
    engine->prefix_cache_tensor_full_kv_compressed_core_output_digest_fnv1a64 =
        output_digest_accum;
    engine
        ->prefix_cache_tensor_full_kv_compressed_backend_span_handoff_evaluated =
        state->prefix_full_kv_compressed_backend_span_handoff_evaluated != 0u
            ? 1
            : 0;
    engine->prefix_cache_tensor_full_kv_compressed_backend_span_layer_count =
        state->prefix_full_kv_compressed_backend_span_layer_count;
    engine->prefix_cache_tensor_full_kv_compressed_backend_span_eval_count =
        state->prefix_full_kv_compressed_backend_span_eval_count;
    engine
        ->prefix_cache_tensor_full_kv_compressed_backend_span_block_reference_count =
        state->prefix_full_kv_compressed_backend_span_block_reference_count;
    engine
        ->prefix_cache_tensor_full_kv_compressed_backend_span_token_reference_count =
        state->prefix_full_kv_compressed_backend_span_token_reference_count;
    engine
        ->prefix_cache_tensor_full_kv_compressed_backend_span_input_digest_fnv1a64 =
        state->prefix_full_kv_compressed_backend_span_input_digest_fnv1a64;
    engine
        ->prefix_cache_tensor_full_kv_compressed_backend_span_output_digest_fnv1a64 =
        state->prefix_full_kv_compressed_backend_span_output_digest_fnv1a64;
    engine->prefix_cache_tensor_full_kv_compressed_state_consumed =
        engine->prefix_cache_tensor_full_kv_compressed_state_seeded &&
                engine
                        ->prefix_cache_tensor_full_kv_compressed_backend_span_handoff_evaluated !=
                    0 &&
                input_digest_accum != UINT64_C(1469598103934665603) &&
                output_digest_accum != UINT64_C(1469598103934665603)
            ? 1
            : 0;
    return engine->prefix_cache_tensor_full_kv_compressed_state_consumed
        ? QRT_STATUS_OK
        : QRT_STATUS_UNSUPPORTED;
}

static int qrt_qwen36_descriptor_decode_cache_payload_export(
    const qrt_engine_t *engine,
    const qrt_qwen36_plain_sequence_state_t *state,
    qrt_qwen36_prefill_descriptor_batch_result_t *result
) {
    const qrt_qwen36_baseline_plan_t *plan;
    const size_t linear_ring_elements =
        (size_t)QRT_QWEN36_LAYER0_LINEAR_ATTN_CONV_KERNEL *
        (size_t)QRT_QWEN36_LAYER0_LINEAR_ATTN_QKV_ROWS;
    const size_t linear_core_state_elements =
        (size_t)QRT_QWEN36_LAYER0_LINEAR_ATTN_VALUE_FEATURES *
        (size_t)QRT_QWEN36_LAYER0_LINEAR_ATTN_KEY_DIM;
    const size_t full_kv_window_elements =
        (size_t)QRT_PREFIX_CACHE_FULL_KV_WINDOW_TOKENS *
        (size_t)QRT_QWEN36_LAYER3_SELF_ATTN_KV_TOKEN_FEATURES;
    uint64_t payload_digest;
    size_t layer_index;
    size_t exported_layer_count = 0u;
    size_t exported_token_count;

    if (engine == NULL || state == NULL || result == NULL ||
        result->output_sequence_decode_state_exported == 0u ||
        result->output_sequence_decode_state_digest_fnv1a64 == UINT64_C(0) ||
        result->output_token_capacity <= result->output_token_count ||
        !engine->prefix_cache_state_attached ||
        !engine->prefix_cache_tensor_linear_state_seeded ||
        !engine->prefix_cache_tensor_full_kv_compressed_state_seeded ||
        !engine->prefix_cache_tensor_full_kv_compressed_state_consumed ||
        state->prefix_full_kv_compressed_enabled == 0u ||
        state->prefix_full_kv_compressed_value_payload_enabled == 0u ||
        state->prefix_full_kv_compressed_backend_span_handoff_evaluated == 0u ||
        state->prefix_full_kv_compressed_block_count == 0u) {
        return 0;
    }

    plan = qrt_qwen36_baseline_plan();
    if (plan == NULL || plan->layer_count != QRT_QWEN36_LAYER_COUNT) {
        return 0;
    }

    payload_digest = qrt_fnv1a64_bytes(
        "Qwen3.6/H-PREFIX-INT-001/descriptor-generated-token-cache-payload-v1",
        sizeof(
            "Qwen3.6/H-PREFIX-INT-001/descriptor-generated-token-cache-payload-v1"
        ) - 1u
    );
    payload_digest = qrt_fnv1a64_update_bytes(
        payload_digest,
        &result->output_sequence_decode_state_digest_fnv1a64,
        sizeof(result->output_sequence_decode_state_digest_fnv1a64)
    );
    payload_digest = qrt_fnv1a64_update_bytes(
        payload_digest,
        &result->descriptor_batch_digest_fnv1a64,
        sizeof(result->descriptor_batch_digest_fnv1a64)
    );
    payload_digest = qrt_fnv1a64_update_bytes(
        payload_digest,
        &result->continuation.digest_fnv1a64,
        sizeof(result->continuation.digest_fnv1a64)
    );
    payload_digest = qrt_fnv1a64_update_bytes(
        payload_digest,
        &result->continuation.token_loop_digest_fnv1a64,
        sizeof(result->continuation.token_loop_digest_fnv1a64)
    );
    payload_digest = qrt_fnv1a64_update_bytes(
        payload_digest,
        &engine->prefix_cache_state_digest_fnv1a64,
        sizeof(engine->prefix_cache_state_digest_fnv1a64)
    );
    payload_digest = qrt_fnv1a64_update_bytes(
        payload_digest,
        &engine->prefix_cache_tensor_linear_seed_digest_fnv1a64,
        sizeof(engine->prefix_cache_tensor_linear_seed_digest_fnv1a64)
    );
    payload_digest = qrt_fnv1a64_update_bytes(
        payload_digest,
        &engine->prefix_cache_tensor_full_kv_seed_digest_fnv1a64,
        sizeof(engine->prefix_cache_tensor_full_kv_seed_digest_fnv1a64)
    );
    payload_digest = qrt_fnv1a64_update_bytes(
        payload_digest,
        &engine->prefix_cache_tensor_full_kv_compressed_seed_digest_fnv1a64,
        sizeof(engine->prefix_cache_tensor_full_kv_compressed_seed_digest_fnv1a64)
    );
    payload_digest = qrt_fnv1a64_update_bytes(
        payload_digest,
        &engine->prefix_cache_tensor_full_kv_compressed_position_digest_fnv1a64,
        sizeof(engine->prefix_cache_tensor_full_kv_compressed_position_digest_fnv1a64)
    );
    payload_digest = qrt_fnv1a64_update_bytes(
        payload_digest,
        &engine->prefix_cache_tensor_full_kv_compressed_tail_digest_fnv1a64,
        sizeof(engine->prefix_cache_tensor_full_kv_compressed_tail_digest_fnv1a64)
    );
    payload_digest = qrt_fnv1a64_update_bytes(
        payload_digest,
        &engine->prefix_cache_tensor_full_kv_compressed_value_payload_digest_fnv1a64,
        sizeof(engine->prefix_cache_tensor_full_kv_compressed_value_payload_digest_fnv1a64)
    );
    payload_digest = qrt_fnv1a64_update_bytes(
        payload_digest,
        &engine->prefix_cache_tensor_full_kv_compressed_backend_span_input_digest_fnv1a64,
        sizeof(engine->prefix_cache_tensor_full_kv_compressed_backend_span_input_digest_fnv1a64)
    );
    payload_digest = qrt_fnv1a64_update_bytes(
        payload_digest,
        &engine->prefix_cache_tensor_full_kv_compressed_backend_span_output_digest_fnv1a64,
        sizeof(engine->prefix_cache_tensor_full_kv_compressed_backend_span_output_digest_fnv1a64)
    );

    for (layer_index = 0u; layer_index < plan->layer_count; ++layer_index) {
        const qrt_qwen36_baseline_layer_descriptor_t *desc =
            qrt_qwen36_baseline_layer_descriptor((unsigned int)layer_index);
        uint64_t first_payload_hash;
        uint64_t second_payload_hash;
        uint32_t attention_kind;

        if (desc == NULL || desc->layer_index != layer_index) {
            return 0;
        }
        attention_kind = (uint32_t)desc->attention_kind;
        if (desc->attention_kind == QRT_QWEN36_BASELINE_ATTENTION_LINEAR) {
            if (state->linear_qkv_rings[layer_index] == NULL ||
                state->linear_core_states[layer_index] == NULL) {
                return 0;
            }
            first_payload_hash = qrt_fnv1a64_f32(
                state->linear_qkv_rings[layer_index],
                linear_ring_elements
            );
            second_payload_hash = qrt_fnv1a64_f32(
                state->linear_core_states[layer_index],
                linear_core_state_elements
            );
        } else if (desc->attention_kind == QRT_QWEN36_BASELINE_ATTENTION_FULL) {
            if (state->prefix_full_kv_windows[layer_index] == NULL ||
                state->prefix_full_kv_compressed_value_payloads[layer_index] == NULL) {
                return 0;
            }
            first_payload_hash = qrt_fnv1a64_f32(
                state->prefix_full_kv_windows[layer_index],
                full_kv_window_elements
            );
            second_payload_hash = qrt_fnv1a64_update_bytes(
                UINT64_C(1469598103934665603),
                state->prefix_full_kv_compressed_value_payloads[layer_index],
                state->prefix_full_kv_compressed_block_count *
                    sizeof(state->prefix_full_kv_compressed_value_payloads
                               [layer_index][0])
            );
        } else {
            return 0;
        }

        payload_digest = qrt_fnv1a64_update_bytes(
            payload_digest,
            &layer_index,
            sizeof(layer_index)
        );
        payload_digest = qrt_fnv1a64_update_bytes(
            payload_digest,
            &attention_kind,
            sizeof(attention_kind)
        );
        payload_digest = qrt_fnv1a64_update_bytes(
            payload_digest,
            &first_payload_hash,
            sizeof(first_payload_hash)
        );
        payload_digest = qrt_fnv1a64_update_bytes(
            payload_digest,
            &second_payload_hash,
            sizeof(second_payload_hash)
        );
        ++exported_layer_count;
    }

    exported_token_count =
        result->output_sequence_decode_state_position +
        result->output_sequence_decode_state_token_count;
    if (exported_layer_count != (size_t)QRT_QWEN36_LAYER_COUNT ||
        exported_token_count == 0u ||
        payload_digest == UINT64_C(1469598103934665603)) {
        return 0;
    }

    result->output_sequence_decode_state_cache_payload_exported = 1u;
    result->output_sequence_decode_state_cache_payload_digest_fnv1a64 =
        payload_digest;
    result->output_sequence_decode_state_cache_layer_count =
        exported_layer_count;
    result->output_sequence_decode_state_cache_token_count =
        exported_token_count;
    (void)snprintf(
        result->output_sequence_decode_missing_field,
        sizeof(result->output_sequence_decode_missing_field),
        "%s",
        "descriptor_autoregressive_decode_loop"
    );
    return 1;
}
#endif

static qrt_status_t qrt_qwen36_plain_sequence_state_seed_prefix_full_kv_compressed_state(
    qrt_engine_t *engine,
    qrt_qwen36_plain_sequence_state_t *state,
    unsigned int layer_limit
) {
    const qrt_qwen36_baseline_plan_t *plan;
    const size_t full_kv_features =
        (size_t)QRT_QWEN36_LAYER3_SELF_ATTN_KV_FEATURES;
    const size_t full_kv_token_elements =
        (size_t)QRT_QWEN36_LAYER3_SELF_ATTN_KV_TOKEN_FEATURES;
    const size_t window_tokens =
        (size_t)QRT_PREFIX_CACHE_FULL_KV_WINDOW_TOKENS;
    const size_t window_elements = window_tokens * full_kv_token_elements;
    const size_t block_tokens =
        (size_t)QRT_PREFIX_CACHE_FULL_KV_COMPRESSED_BLOCK_TOKENS;
    size_t block_count;
    size_t covered_tokens;
    size_t tail_start_position;
    size_t tail_block_index;
    size_t tail_offset_tokens;
    uint64_t seed_digest;
    uint64_t position_digest;
    uint64_t tail_digest;
    uint64_t value_payload_digest;
    unsigned int layer_index;
    unsigned int active_layer_count;
    size_t seeded_layer_count = 0u;
    size_t value_payload_layer_count = 0u;
    size_t value_payload_block_count = 0u;
    size_t value_payload_sample_count = 0u;
    int tail_equivalence_pass = 1;

    if (engine == NULL || state == NULL) {
        return QRT_STATUS_INVALID_ARGUMENT;
    }
    if (!engine->prefix_cache_state_attached ||
        !engine->prefix_cache_tensor_full_kv_compressed_state_requested) {
        return QRT_STATUS_OK;
    }
    if (!state->prefix_full_kv_window_enabled ||
        window_tokens == 0u ||
        block_tokens == 0u ||
        engine->prefix_cache_cached_prefix_tokens < window_tokens ||
        (engine->prefix_cache_cached_prefix_tokens % block_tokens) != 0u) {
        qrt_engine_set_token_request_failure(
            engine,
            "prefix_tensor_full_kv_compressed_position",
            "prefix full-KV compressed block map is not aligned to the cached prefix"
        );
        return QRT_STATUS_UNSUPPORTED;
    }

    plan = qrt_qwen36_baseline_plan();
    if (plan == NULL || plan->layer_count != QRT_QWEN36_LAYER_COUNT) {
        qrt_engine_set_token_request_failure(
            engine,
            "prefix_tensor_full_kv_compressed_descriptor",
            "prefix full-KV compressed seed descriptor plan is invalid"
        );
        return QRT_STATUS_UNSUPPORTED;
    }

    block_count = engine->prefix_cache_cached_prefix_tokens / block_tokens;
    covered_tokens = block_count * block_tokens;
    tail_start_position = engine->prefix_cache_cached_prefix_tokens - window_tokens;
    tail_block_index = tail_start_position / block_tokens;
    tail_offset_tokens = tail_start_position % block_tokens;
    if (covered_tokens != engine->prefix_cache_cached_prefix_tokens ||
        tail_block_index + 1u != block_count ||
        tail_offset_tokens + window_tokens != block_tokens) {
        qrt_engine_set_token_request_failure(
            engine,
            "prefix_tensor_full_kv_compressed_tail_map",
            "prefix full-KV compressed tail window does not map to the final block"
        );
        return QRT_STATUS_UNSUPPORTED;
    }

    seed_digest = qrt_fnv1a64_bytes(
        "Qwen3.6/H-PREFIX-001/prefix-full-kv-compressed-seed-v1",
        sizeof("Qwen3.6/H-PREFIX-001/prefix-full-kv-compressed-seed-v1")
    );
    position_digest = qrt_fnv1a64_bytes(
        "Qwen3.6/H-PREFIX-001/prefix-full-kv-compressed-position-v1",
        sizeof("Qwen3.6/H-PREFIX-001/prefix-full-kv-compressed-position-v1")
    );
    tail_digest = qrt_fnv1a64_bytes(
        "Qwen3.6/H-PREFIX-001/prefix-full-kv-compressed-tail-v1",
        sizeof("Qwen3.6/H-PREFIX-001/prefix-full-kv-compressed-tail-v1")
    );
    value_payload_digest = qrt_fnv1a64_bytes(
        "Qwen3.6/H-PREFIX-001/prefix-full-kv-compressed-value-payload-v1",
        sizeof(
            "Qwen3.6/H-PREFIX-001/prefix-full-kv-compressed-value-payload-v1"
        )
    );

    seed_digest = qrt_fnv1a64_update_bytes(
        seed_digest,
        &engine->prefix_cache_state_digest_fnv1a64,
        sizeof(engine->prefix_cache_state_digest_fnv1a64)
    );
    seed_digest = qrt_fnv1a64_update_bytes(
        seed_digest,
        &engine->prefix_cache_cached_prefix_tokens,
        sizeof(engine->prefix_cache_cached_prefix_tokens)
    );
    seed_digest = qrt_fnv1a64_update_bytes(
        seed_digest,
        &block_tokens,
        sizeof(block_tokens)
    );
    seed_digest = qrt_fnv1a64_update_bytes(
        seed_digest,
        &block_count,
        sizeof(block_count)
    );

    active_layer_count =
        layer_limit > plan->layer_count ? plan->layer_count : layer_limit;
    for (layer_index = 0u; layer_index < active_layer_count; ++layer_index) {
        const qrt_qwen36_baseline_layer_descriptor_t *desc =
            qrt_qwen36_baseline_layer_descriptor(layer_index);
        uint64_t *block_digests;
        qrt_qwen36_prefix_full_kv_compressed_value_payload_t *value_payloads;
        float *expected_window;
        float *actual_window;
        uint64_t layer_position_digest;
        uint64_t layer_value_payload_digest;
        uint64_t actual_tail_hash;
        uint64_t expected_tail_hash;
        size_t block_index;
        size_t element_index;

        if (desc == NULL || desc->layer_index != layer_index) {
            qrt_engine_set_token_request_failure(
                engine,
                "prefix_tensor_full_kv_compressed_descriptor",
                "prefix full-KV compressed seed layer descriptor is invalid"
            );
            return QRT_STATUS_UNSUPPORTED;
        }
        if (desc->attention_kind != QRT_QWEN36_BASELINE_ATTENTION_FULL) {
            continue;
        }

        actual_window = state->prefix_full_kv_windows[layer_index];
        if (actual_window == NULL) {
            qrt_engine_set_token_request_failure(
                engine,
                "prefix_tensor_full_kv_compressed_tail_window",
                "prefix full-KV compressed map is missing the tail window"
            );
            return QRT_STATUS_UNSUPPORTED;
        }
        block_digests = (uint64_t *)calloc(block_count, sizeof(block_digests[0]));
        value_payloads =
            (qrt_qwen36_prefix_full_kv_compressed_value_payload_t *)calloc(
                block_count,
                sizeof(value_payloads[0])
            );
        expected_window = (float *)calloc(window_elements, sizeof(expected_window[0]));
        if (block_digests == NULL || value_payloads == NULL ||
            expected_window == NULL) {
            free(expected_window);
            free(value_payloads);
            free(block_digests);
            qrt_engine_set_token_request_failure(
                engine,
                "prefix_tensor_full_kv_compressed_alloc",
                "prefix full-KV compressed state allocation failed"
            );
            return QRT_STATUS_OUT_OF_MEMORY;
        }
        state->prefix_full_kv_compressed_block_digests[layer_index] =
            block_digests;
        state->prefix_full_kv_compressed_value_payloads[layer_index] =
            value_payloads;

        layer_position_digest = qrt_fnv1a64_bytes(
            "Qwen3.6/H-PREFIX-001/prefix-full-kv-compressed-layer-v1",
            sizeof("Qwen3.6/H-PREFIX-001/prefix-full-kv-compressed-layer-v1")
        );
        layer_value_payload_digest = qrt_fnv1a64_bytes(
            "Qwen3.6/H-PREFIX-001/prefix-full-kv-compressed-value-layer-v1",
            sizeof(
                "Qwen3.6/H-PREFIX-001/prefix-full-kv-compressed-value-layer-v1"
            )
        );
        for (block_index = 0u; block_index < block_count; ++block_index) {
            const size_t block_start_token = block_index * block_tokens;
            const uint64_t block_digest =
                qrt_prefix_cache_full_kv_compressed_block_digest(
                    engine->prefix_cache_state_digest_fnv1a64,
                    layer_index,
                    block_index,
                    block_start_token,
                    block_tokens,
                    full_kv_token_elements
                );
            block_digests[block_index] = block_digest;
            qrt_prefix_cache_full_kv_compressed_value_payload_build(
                engine->prefix_cache_state_digest_fnv1a64,
                layer_index,
                block_index,
                block_start_token,
                block_tokens,
                full_kv_features,
                &value_payloads[block_index]
            );
            layer_position_digest = qrt_fnv1a64_update_bytes(
                layer_position_digest,
                &block_digest,
                sizeof(block_digest)
            );
            layer_value_payload_digest = qrt_fnv1a64_update_bytes(
                layer_value_payload_digest,
                &value_payloads[block_index].summary_digest_fnv1a64,
                sizeof(value_payloads[block_index].summary_digest_fnv1a64)
            );
        }

        for (element_index = 0u;
             element_index < window_elements;
             ++element_index) {
            const size_t token_offset = element_index / full_kv_token_elements;
            const size_t element_in_token = element_index % full_kv_token_elements;
            const size_t absolute_element_index =
                (tail_start_position + token_offset) *
                    full_kv_token_elements +
                element_in_token;
            expected_window[element_index] = qrt_prefix_cache_tensor_seed_value(
                engine->prefix_cache_state_digest_fnv1a64,
                layer_index,
                absolute_element_index,
                UINT64_C(0x51525646554c4b56)
            );
        }
        actual_tail_hash = qrt_fnv1a64_f32(actual_window, window_elements);
        expected_tail_hash = qrt_fnv1a64_f32(expected_window, window_elements);
        if (actual_tail_hash != expected_tail_hash ||
            memcmp(actual_window, expected_window, window_elements * sizeof(float)) != 0) {
            tail_equivalence_pass = 0;
        }

        position_digest = qrt_fnv1a64_update_bytes(
            position_digest,
            &layer_index,
            sizeof(layer_index)
        );
        position_digest = qrt_fnv1a64_update_bytes(
            position_digest,
            &layer_position_digest,
            sizeof(layer_position_digest)
        );
        tail_digest = qrt_fnv1a64_update_bytes(
            tail_digest,
            &layer_index,
            sizeof(layer_index)
        );
        tail_digest = qrt_fnv1a64_update_bytes(
            tail_digest,
            &actual_tail_hash,
            sizeof(actual_tail_hash)
        );
        tail_digest = qrt_fnv1a64_update_bytes(
            tail_digest,
            &expected_tail_hash,
            sizeof(expected_tail_hash)
        );
        seed_digest = qrt_fnv1a64_update_bytes(
            seed_digest,
            &layer_position_digest,
            sizeof(layer_position_digest)
        );
        value_payload_digest = qrt_fnv1a64_update_bytes(
            value_payload_digest,
            &layer_index,
            sizeof(layer_index)
        );
        value_payload_digest = qrt_fnv1a64_update_bytes(
            value_payload_digest,
            &layer_value_payload_digest,
            sizeof(layer_value_payload_digest)
        );
        free(expected_window);
        ++seeded_layer_count;
        ++value_payload_layer_count;
        value_payload_block_count += block_count;
        value_payload_sample_count +=
            block_count *
            (size_t)QRT_PREFIX_CACHE_FULL_KV_COMPRESSED_PAYLOAD_SAMPLES *
            2u;
    }

    state->prefix_full_kv_compressed_enabled =
        seeded_layer_count == (size_t)QRT_QWEN36_FULL_ATTENTION_LAYERS &&
                tail_equivalence_pass &&
                position_digest != UINT64_C(1469598103934665603)
            ? 1u
            : 0u;
    state->prefix_full_kv_compressed_position_map_pass =
        block_count == engine->prefix_cache_cached_prefix_tokens / block_tokens &&
                covered_tokens == engine->prefix_cache_cached_prefix_tokens &&
                tail_block_index + 1u == block_count &&
                tail_offset_tokens + window_tokens == block_tokens
            ? 1u
            : 0u;
    state->prefix_full_kv_compressed_tail_window_equivalence_pass =
        tail_equivalence_pass ? 1u : 0u;
    state->prefix_full_kv_compressed_block_count = block_count;
    state->prefix_full_kv_compressed_block_tokens = block_tokens;
    state->prefix_full_kv_compressed_covered_tokens = covered_tokens;
    state->prefix_full_kv_compressed_tail_block_index = tail_block_index;
    state->prefix_full_kv_compressed_tail_offset_tokens = tail_offset_tokens;
    state->prefix_full_kv_compressed_seed_digest_fnv1a64 = seed_digest;
    state->prefix_full_kv_compressed_position_digest_fnv1a64 = position_digest;
    state->prefix_full_kv_compressed_tail_digest_fnv1a64 = tail_digest;
    state->prefix_full_kv_compressed_value_payload_enabled =
        state->prefix_full_kv_compressed_enabled &&
                value_payload_layer_count ==
                    (size_t)QRT_QWEN36_FULL_ATTENTION_LAYERS &&
                value_payload_block_count == block_count * value_payload_layer_count &&
                value_payload_sample_count != 0u &&
                value_payload_digest != UINT64_C(1469598103934665603)
            ? 1u
            : 0u;
    state->prefix_full_kv_compressed_value_payload_layer_count =
        value_payload_layer_count;
    state->prefix_full_kv_compressed_value_payload_block_count =
        value_payload_block_count;
    state->prefix_full_kv_compressed_value_payload_sample_count =
        value_payload_sample_count;
    state->prefix_full_kv_compressed_value_payload_digest_fnv1a64 =
        value_payload_digest;

    engine->prefix_cache_tensor_full_kv_compressed_state_seeded =
        state->prefix_full_kv_compressed_enabled &&
                state->prefix_full_kv_compressed_value_payload_enabled
            ? 1
            : 0;
    engine->prefix_cache_tensor_full_kv_compressed_block_count = block_count;
    engine->prefix_cache_tensor_full_kv_compressed_block_tokens = block_tokens;
    engine->prefix_cache_tensor_full_kv_compressed_covered_tokens = covered_tokens;
    engine->prefix_cache_tensor_full_kv_compressed_tail_block_index =
        tail_block_index;
    engine->prefix_cache_tensor_full_kv_compressed_tail_offset_tokens =
        tail_offset_tokens;
    engine->prefix_cache_tensor_full_kv_compressed_seed_digest_fnv1a64 =
        seed_digest;
    engine->prefix_cache_tensor_full_kv_compressed_position_digest_fnv1a64 =
        position_digest;
    engine->prefix_cache_tensor_full_kv_compressed_tail_digest_fnv1a64 =
        tail_digest;
    engine->prefix_cache_tensor_full_kv_compressed_value_payload_present =
        state->prefix_full_kv_compressed_value_payload_enabled ? 1 : 0;
    engine->prefix_cache_tensor_full_kv_compressed_value_payload_layer_count =
        value_payload_layer_count;
    engine->prefix_cache_tensor_full_kv_compressed_value_payload_block_count =
        value_payload_block_count;
    engine->prefix_cache_tensor_full_kv_compressed_value_payload_sample_count =
        value_payload_sample_count;
    engine->prefix_cache_tensor_full_kv_compressed_value_payload_digest_fnv1a64 =
        value_payload_digest;
    return state->prefix_full_kv_compressed_enabled &&
            state->prefix_full_kv_compressed_value_payload_enabled &&
            state->prefix_full_kv_compressed_position_map_pass
        ? QRT_STATUS_OK
        : QRT_STATUS_UNSUPPORTED;
}

static qrt_status_t qrt_qwen36_plain_sequence_state_enable_product_q8192_frontier_for_final_targets(
    qrt_qwen36_plain_sequence_state_t *state,
    const uint32_t *final_target_tokens,
    size_t final_target_token_count,
    unsigned int zero_linear_core_state
) {
    qrt_status_t status;
    size_t target_index;

    if (state == NULL ||
        final_target_tokens == NULL || final_target_token_count == 0u ||
        final_target_token_count >
            QRT_QWEN36_PRODUCT_Q8192_LAYER1_FRONTIER_TOKEN_CAPACITY ||
        state->prompt_token_capacity == 0u) {
        return QRT_STATUS_INVALID_ARGUMENT;
    }
    for (target_index = 0u;
         target_index < final_target_token_count;
         ++target_index) {
        if ((size_t)final_target_tokens[target_index] >=
            state->prompt_token_capacity) {
            return QRT_STATUS_INVALID_ARGUMENT;
        }
    }

    status = qrt_qwen36_layer1_frontier_tokens_for_final_targets(
        final_target_tokens,
        final_target_token_count,
        state->product_q8192_layer1_frontier_tokens,
        QRT_QWEN36_PRODUCT_Q8192_LAYER1_FRONTIER_TOKEN_CAPACITY,
        &state->product_q8192_layer1_frontier_expected_token_count,
        &state->product_q8192_layer1_frontier_token_ids_fnv1a64
    );
    if (status != QRT_STATUS_OK) {
        return status;
    }
    status = qrt_qwen36_selected_window_tokens_for_targets(
        state->product_q8192_layer1_frontier_tokens,
        state->product_q8192_layer1_frontier_expected_token_count,
        state->product_q8192_layer1_frontier_source_window_tokens,
        QRT_QWEN36_PRODUCT_Q8192_LAYER1_FRONTIER_TOKEN_CAPACITY,
        &state->product_q8192_layer1_frontier_source_window_token_count
    );
    if (status != QRT_STATUS_OK) {
        return status;
    }
    state->product_q8192_layer1_frontier_source_window_token_ids_fnv1a64 =
        qrt_fnv1a64_update_bytes(
            UINT64_C(1469598103934665603),
            state->product_q8192_layer1_frontier_source_window_tokens,
            state->product_q8192_layer1_frontier_source_window_token_count *
                sizeof(state->product_q8192_layer1_frontier_source_window_tokens[0])
        );
    state->product_q8192_layer1_frontier_next_token_index = 0u;
    state->product_q8192_layer1_frontier_token_count = 0u;
    state->product_q8192_layer1_frontier_hidden_value_count = 0u;
    state->product_q8192_layer1_frontier_digest_fnv1a64 =
        UINT64_C(1469598103934665603);
    state->product_q8192_layer1_frontier_last_output_fnv1a64 = UINT64_C(0);
    state->product_q8192_layer1_frontier_hidden_values =
        (float *)calloc(
            state->product_q8192_layer1_frontier_expected_token_count *
                (size_t)QRT_QWEN36_HIDDEN_SIZE,
            sizeof(state->product_q8192_layer1_frontier_hidden_values[0])
        );
    if (state->product_q8192_layer1_frontier_hidden_values == NULL) {
        return QRT_STATUS_OUT_OF_MEMORY;
    }
    qrt_qwen36_product_q8192_reset_stage_digests(
        (size_t)QRT_QWEN36_PRODUCT_Q8192_LAYER0_SOURCE_STAGE_COUNT,
        state->product_q8192_layer0_source_stage_token_counts,
        state->product_q8192_layer0_source_stage_digest_fnv1a64,
        state->product_q8192_layer0_source_stage_last_fnv1a64
    );
    qrt_qwen36_product_q8192_reset_stage_digests(
        (size_t)QRT_QWEN36_PRODUCT_Q8192_LAYER1_STAGE_COUNT,
        state->product_q8192_layer1_frontier_stage_token_counts,
        state->product_q8192_layer1_frontier_stage_digest_fnv1a64,
        state->product_q8192_layer1_frontier_stage_last_fnv1a64
    );
    state->product_q8192_layer1_frontier_enabled = 1u;
    state->product_q8192_zero_linear_core_state =
        zero_linear_core_state != 0u ? 1u : 0u;
    state->product_q8192_layer1_frontier_complete = 0u;
    return QRT_STATUS_OK;
}

static qrt_status_t qrt_qwen36_plain_sequence_state_enable_product_q8192_frontier(
    qrt_qwen36_plain_sequence_state_t *state,
    unsigned int zero_linear_core_state
) {
    uint32_t final_targets[QRT_QWEN36_PRODUCT_Q8192_LAYER1_FRONTIER_TOKEN_CAPACITY];
    size_t final_target_count = 0u;
    qrt_status_t status;

    if (state == NULL ||
        state->prompt_token_capacity <
            (size_t)QRT_QWEN36_PRODUCT_Q8192_CONTEXT_TOKENS) {
        return QRT_STATUS_INVALID_ARGUMENT;
    }

    memset(final_targets, 0, sizeof(final_targets));
    status = qrt_qwen36_selected_tokens_for_context(
        (size_t)QRT_QWEN36_PRODUCT_Q8192_CONTEXT_TOKENS,
        final_targets,
        QRT_QWEN36_PRODUCT_Q8192_LAYER1_FRONTIER_TOKEN_CAPACITY,
        &final_target_count
    );
    if (status != QRT_STATUS_OK) {
        return status;
    }
    return qrt_qwen36_plain_sequence_state_enable_product_q8192_frontier_for_final_targets(
        state,
        final_targets,
        final_target_count,
        zero_linear_core_state
    );
}

static qrt_status_t qrt_qwen36_plain_sequence_state_enable_product_q8192_full_frontier(
    qrt_qwen36_plain_sequence_state_t *state,
    unsigned int zero_linear_core_state
) {
    uint32_t final_targets[QRT_QWEN36_PRODUCT_Q8192_LAYER1_FRONTIER_TOKEN_CAPACITY];
    size_t token_index;

    if (state == NULL ||
        state->prompt_token_capacity <
            (size_t)QRT_QWEN36_PRODUCT_Q8192_CONTEXT_TOKENS ||
        (size_t)QRT_QWEN36_PRODUCT_Q8192_CONTEXT_TOKENS >
            (size_t)QRT_QWEN36_PRODUCT_Q8192_LAYER1_FRONTIER_TOKEN_CAPACITY) {
        return QRT_STATUS_INVALID_ARGUMENT;
    }

    for (token_index = 0u;
         token_index < (size_t)QRT_QWEN36_PRODUCT_Q8192_CONTEXT_TOKENS;
         ++token_index) {
        final_targets[token_index] = (uint32_t)token_index;
    }
    return qrt_qwen36_plain_sequence_state_enable_product_q8192_frontier_for_final_targets(
        state,
        final_targets,
        (size_t)QRT_QWEN36_PRODUCT_Q8192_CONTEXT_TOKENS,
        zero_linear_core_state
    );
}

static qrt_status_t qrt_qwen36_build_synthetic_prefill_token_hidden(
    size_t token_index,
    float *out_hidden,
    uint64_t *out_hidden_hash
) {
    size_t hidden_index;

    if (out_hidden == NULL || out_hidden_hash == NULL ||
        token_index > UINT_MAX) {
        return QRT_STATUS_INVALID_ARGUMENT;
    }

    for (hidden_index = 0u;
         hidden_index < (size_t)QRT_QWEN36_HIDDEN_SIZE;
         ++hidden_index) {
        const unsigned int token = (unsigned int)token_index;
        const unsigned int col = (unsigned int)hidden_index;
        const int pattern =
            (int)((token * 17u + col * 13u + 7u) % 127u) - 63;
        const float value = (float)pattern * 0.00390625f;
        out_hidden[hidden_index] =
            qrt_bf16_to_float(qrt_float_to_bf16(value));
    }
    *out_hidden_hash =
        qrt_fnv1a64_f32(out_hidden, (size_t)QRT_QWEN36_HIDDEN_SIZE);
    return QRT_STATUS_OK;
}

static void qrt_qwen36_prefill_descriptor_batch_set_failure(
    qrt_qwen36_prefill_descriptor_batch_result_t *result,
    const char *missing_field,
    const char *failure_stage,
    const char *failure,
    uint64_t start_ns
) {
    if (result == NULL) {
        return;
    }
    result->wall_clock_ns = qrt_elapsed_ns(start_ns, qrt_now_ns());
    (void)snprintf(
        result->first_missing_runtime_context_field,
        sizeof(result->first_missing_runtime_context_field),
        "%s",
        missing_field != NULL ? missing_field : ""
    );
    (void)snprintf(
        result->failure_stage,
        sizeof(result->failure_stage),
        "%s",
        failure_stage != NULL ? failure_stage : ""
    );
    (void)snprintf(
        result->failure,
        sizeof(result->failure),
        "%s",
        failure != NULL ? failure : ""
    );
}

