        memset(&qkv_pack, 0, sizeof(qkv_pack));
        qkv_pack.desc = &runtime_desc;
        qkv_pack.qkv_weight = qkv_weight;
        qkv_pack.input_norm = input_norm;
        qkv_pack.qkv_projection = qkv_projection;
        qkv_pack.qkv_elapsed_ns = &qkv_elapsed_ns;
