    out_result->report_output_head_top1_token_id =
        report->baseline_output_head_sampled_token_id;
    out_result->report_output_head_token_emitted =
        report->baseline_output_head_token_emitted;
    out_result->request_execution_elapsed_ns =
        report->last_request_elapsed_ns != UINT64_C(0)
            ? report->last_request_elapsed_ns
            : out_result->request_execution_elapsed_ns;
    out_result->ttft_elapsed_ns = report->last_request_ttft_elapsed_ns;
    out_result->tpot_elapsed_ns = report->last_request_tpot_elapsed_ns;
    out_result->tpot_sample_count = report->last_request_tpot_sample_count;
