        layer_body_repeated_moe_expert_cache[QRT_QWEN36_MOE_EXPERT_COUNT];
    qrt_moe_expert_cache_entry_t
        layer_body_full_attention_moe_expert_cache[QRT_QWEN36_MOE_EXPERT_COUNT];
    uint64_t input_norm_weight_hash = UINT64_C(0);
    uint64_t weight_bytes_read = UINT64_C(0);
    uint64_t qkv_projection_weight_hash = UINT64_C(0);
    uint64_t qkv_projection_weight_bytes_read = UINT64_C(0);
    uint64_t z_projection_weight_hash = UINT64_C(0);
    uint64_t a_projection_weight_hash = UINT64_C(0);
    uint64_t b_projection_weight_hash = UINT64_C(0);
