    engine->layer2_moe_expert_routed_fnv1a64 =
        layer_body_repeated_moe_expert.routed_hash;
    engine->last_layer2_moe_expert_routed_fnv1a64 =
        layer_body_repeated_moe_expert.last_routed_hash;
    engine->layer2_moe_expert_selected_ids_fnv1a64 =
        layer_body_repeated_moe_expert.selected_ids_hash;
    engine->layer2_moe_expert_gate_up_weight_fnv1a64 =
        layer_body_repeated_moe_expert.gate_up_weight_hash;
    engine->layer2_moe_expert_down_weight_fnv1a64 =
        layer_body_repeated_moe_expert.down_weight_hash;
    engine->layer2_moe_expert_weight_bytes_read =
        layer_body_repeated_moe_expert.weight_bytes_read;
    engine->layer2_moe_shared_expert_applied =
        layer_body_repeated_moe_shared.materialized_count ==
            input_token_count ? 1 : 0;
    engine->layer2_moe_shared_expert_materialized_count =
        layer_body_repeated_moe_shared.materialized_count;
    engine->layer2_moe_shared_expert_elapsed_ns +=
        layer_body_repeated_moe_shared.shared_elapsed_ns;
    engine->layer2_moe_shared_expert_fnv1a64 =
        layer_body_repeated_moe_shared.shared_hash;
    engine->last_layer2_moe_shared_expert_fnv1a64 =
        layer_body_repeated_moe_shared.last_shared_hash;
    engine->layer2_moe_combined_fnv1a64 =
        layer_body_repeated_moe_shared.combined_hash;
    engine->last_layer2_moe_combined_fnv1a64 =
        layer_body_repeated_moe_shared.last_combined_hash;
    engine->layer2_moe_shared_gate_fnv1a64 =
        layer_body_repeated_moe_shared.gate_hash;
    engine->last_layer2_moe_shared_gate_fnv1a64 =
        layer_body_repeated_moe_shared.last_gate_hash;
    engine->layer2_moe_shared_gate_weight_fnv1a64 =
        layer_body_repeated_moe_shared.gate_weight_hash;
    engine->layer2_moe_shared_gate_proj_weight_fnv1a64 =
        layer_body_repeated_moe_shared.gate_proj_weight_hash;
    engine->layer2_moe_shared_up_proj_weight_fnv1a64 =
        layer_body_repeated_moe_shared.up_proj_weight_hash;
    engine->layer2_moe_shared_down_weight_fnv1a64 =
        layer_body_repeated_moe_shared.down_weight_hash;
    engine->layer2_moe_shared_expert_weight_bytes_read =
        layer_body_repeated_moe_shared.weight_bytes_read;
    engine->layer2_output_residual_applied =
        layer_body_repeated_output_residual.materialized_count ==
            input_token_count ? 1 : 0;
    engine->layer2_output_residual_materialized_count =
        layer_body_repeated_output_residual.materialized_count;
    engine->layer2_output_residual_elapsed_ns +=
        layer_body_repeated_output_residual.output_residual_elapsed_ns;
    engine->layer2_output_residual_fnv1a64 =
        layer_body_repeated_output_residual.output_residual_hash;
    engine->last_layer2_output_residual_fnv1a64 =
        layer_body_repeated_output_residual.last_output_residual_hash;
    qrt_engine_set_token_request_failure(
        engine,
        "hprefix_l9_attention_missing",
        "H-PREFIX descriptor layer-9 input RMSNorm computed; attention body is missing"
    );
    status = QRT_STATUS_UNSUPPORTED;

finish:
    engine->qwen36_descriptor_layer_batch_elapsed_ns +=
        qrt_elapsed_ns(start_ns, qrt_now_ns());
    qrt_qwen36_free_moe_shared_weights(
        &layer_body_full_attention_moe_shared_weights
    );
    qrt_qwen36_free_moe_shared_weights(
        &layer_body_repeated_moe_shared_weights
    );
    qrt_qwen36_free_moe_shared_weights(&layer_body_moe_shared_weights);
    qrt_qwen36_free_moe_shared_weights(&moe_shared_weights);
    qrt_free_moe_expert_cache(layer_body_full_attention_moe_expert_cache);
    qrt_free_moe_expert_cache(layer_body_repeated_moe_expert_cache);
