static qrt_status_t qrt_qwen36_try_whole_provider_direct_entry(
    qrt_engine_t *engine,
    const uint32_t *input_tokens,
    size_t input_token_count,
    uint32_t *output_tokens,
    size_t output_token_capacity,
    size_t *out_output_token_count,
    int *out_handled
) {
    uint64_t request_start_ns;
    uint64_t provider_start_ns;
    qrt_status_t status;
    int provider_handled = 0;

    if (out_handled != NULL) {
        *out_handled = 0;
    }
    if (engine == NULL || input_tokens == NULL || output_tokens == NULL ||
        out_output_token_count == NULL || out_handled == NULL) {
        return QRT_STATUS_INVALID_ARGUMENT;
    }
    if (!qrt_qwen36_whole_provider_direct_entry_enabled()) {
        return QRT_STATUS_OK;
    }

    request_start_ns = qrt_now_ns();
    ++engine->qwen36_whole_provider_direct_entry_attempt_count;
    engine->qwen36_whole_provider_direct_entry_last_entry =
        QRT_QWEN36_WHOLE_PROVIDER_REQUEST_ENTRY_DIRECT;
    engine->qwen36_whole_provider_direct_entry_last_status =
        (int32_t)QRT_STATUS_INVALID_ARGUMENT;
    engine->qwen36_whole_provider_direct_entry_last_prologue_elapsed_ns =
        UINT64_C(0);
    engine->qwen36_whole_provider_direct_entry_last_total_elapsed_ns =
        UINT64_C(0);
    engine->qwen36_whole_provider_direct_entry_last_provider_ttft_elapsed_ns =
        UINT64_C(0);
    engine->qwen36_whole_provider_last_provider_call_start_elapsed_ns =
        UINT64_C(0);
    engine->qwen36_whole_provider_last_provider_return_elapsed_ns =
        UINT64_C(0);
    engine->qwen36_whole_provider_last_provider_to_direct_entry_elapsed_ns =
        UINT64_C(0);
    engine->qwen36_whole_provider_last_direct_pre_layer_stack_elapsed_ns =
        UINT64_C(0);
    engine->qwen36_whole_provider_last_direct_layer_stack_elapsed_ns =
        UINT64_C(0);
    engine->qwen36_whole_provider_last_direct_post_layer_stack_elapsed_ns =
        UINT64_C(0);
    engine
        ->qwen36_whole_provider_last_provider_post_direct_to_reported_wall_elapsed_ns =
        UINT64_C(0);
    engine->qwen36_whole_provider_last_provider_phase_accounted_elapsed_ns =
        UINT64_C(0);
    engine->qwen36_whole_provider_last_provider_phase_accounting_error_ns =
        UINT64_C(0);

    if (!qrt_qwen36_whole_provider_direct_entry_eligible(
            engine,
            input_token_count,
            output_token_capacity)) {
        ++engine->qwen36_whole_provider_direct_entry_fallback_count;
        engine->qwen36_whole_provider_direct_entry_last_entry =
            QRT_QWEN36_WHOLE_PROVIDER_REQUEST_ENTRY_FALLBACK;
        engine->qwen36_whole_provider_direct_entry_last_status =
            (int32_t)QRT_STATUS_UNSUPPORTED;
        engine->qwen36_whole_provider_direct_entry_last_total_elapsed_ns =
            qrt_elapsed_ns(request_start_ns, qrt_now_ns());
        return QRT_STATUS_OK;
    }

    *out_handled = 1;
    qrt_qwen36_prepare_whole_provider_direct_request(
        engine,
        input_tokens,
        input_token_count,
        output_tokens,
        out_output_token_count
    );
    provider_start_ns = qrt_now_ns();
    engine->qwen36_whole_provider_direct_entry_last_prologue_elapsed_ns =
        qrt_elapsed_ns(request_start_ns, provider_start_ns);
    status = qrt_qwen36_try_whole_provider_prefill_request(
        engine,
        input_tokens,
        input_token_count,
        output_tokens,
        output_token_capacity,
        out_output_token_count,
        request_start_ns,
        &provider_handled
    );
    engine->qwen36_whole_provider_direct_entry_last_total_elapsed_ns =
        qrt_elapsed_ns(request_start_ns, qrt_now_ns());
    engine->qwen36_whole_provider_direct_entry_last_provider_ttft_elapsed_ns =
        engine->last_request_ttft_elapsed_ns;
    engine->qwen36_whole_provider_direct_entry_last_status = (int32_t)status;
    if (!provider_handled) {
        ++engine->qwen36_whole_provider_direct_entry_fallback_count;
        engine->qwen36_whole_provider_direct_entry_last_entry =
            QRT_QWEN36_WHOLE_PROVIDER_REQUEST_ENTRY_FALLBACK;
        engine->qwen36_whole_provider_direct_entry_last_status =
            (int32_t)QRT_STATUS_UNSUPPORTED;
        return QRT_STATUS_UNSUPPORTED;
    }
    if (status == QRT_STATUS_OK) {
        ++engine->qwen36_whole_provider_direct_entry_completion_count;
    }
    return status;
}
#endif

qrt_status_t qrt_engine_request_tokens(
    qrt_engine_t *engine,
    const uint32_t *input_tokens,
    size_t input_token_count,
    uint32_t *output_tokens,
    size_t output_token_capacity,
    size_t *out_output_token_count
) {
    qrt_status_t status;
    if (engine == NULL || input_tokens == NULL || input_token_count == 0u ||
        output_tokens == NULL || output_token_capacity == 0u ||
        out_output_token_count == NULL) {
        return QRT_STATUS_INVALID_ARGUMENT;
    }
#ifdef _WIN32
    {
        int direct_entry_handled = 0;
        qrt_status_t status =
            qrt_qwen36_try_whole_provider_direct_entry(
                engine,
                input_tokens,
                input_token_count,
                output_tokens,
                output_token_capacity,
                out_output_token_count,
                &direct_entry_handled
            );
        if (direct_entry_handled) {
            return status;
        }
        if (engine->qwen36_whole_provider_requested &&
            input_token_count ==
                (size_t)QRT_QWEN36_PRODUCT_Q8192_CONTEXT_TOKENS &&
            output_token_capacity <=
                (size_t)QRT_QWEN36_WHOLE_PROVIDER_MAX_OUTPUT_TOKENS) {
            ++engine->qwen36_whole_provider_legacy_entry_count;
            if (!qrt_qwen36_whole_provider_direct_entry_enabled()) {
                engine->qwen36_whole_provider_direct_entry_last_entry =
                    QRT_QWEN36_WHOLE_PROVIDER_REQUEST_ENTRY_LEGACY;
            }
        }
    }
#endif
    status = qrt_engine_request_tokens_legacy(
        engine,
        input_tokens,
        input_token_count,
        output_tokens,
        output_token_capacity,
        out_output_token_count
    );
#ifdef _WIN32
    if (engine->qwen36_whole_provider_requested &&
        input_token_count ==
            (size_t)QRT_QWEN36_PRODUCT_Q8192_CONTEXT_TOKENS &&
        output_token_capacity <=
            (size_t)QRT_QWEN36_WHOLE_PROVIDER_MAX_OUTPUT_TOKENS &&
        !qrt_qwen36_whole_provider_direct_entry_enabled()) {
        engine->qwen36_whole_provider_direct_entry_last_status =
            (int32_t)status;
    }
#endif
    return status;
}

