static void qrt_resident_prefix_cache_result_init(
    qrt_qwen36_resident_prefix_cache_result_v1_t *out_result
) {
    if (out_result == NULL) {
        return;
    }
    memset(out_result, 0, sizeof(*out_result));
    out_result->struct_size = (uint32_t)sizeof(*out_result);
    out_result->abi_version =
        QRT_QWEN36_RESIDENT_PREFIX_CACHE_ABI_VERSION;
    out_result->status = (int32_t)QRT_STATUS_INVALID_ARGUMENT;
}

static qrt_status_t qrt_resident_prefix_cache_result_failure(
    qrt_engine_t *engine,
    qrt_qwen36_resident_prefix_cache_result_v1_t *out_result,
    qrt_status_t status,
    const char *stage,
    const char *message
) {
    if (out_result != NULL) {
        out_result->struct_size = (uint32_t)sizeof(*out_result);
        out_result->abi_version =
            QRT_QWEN36_RESIDENT_PREFIX_CACHE_ABI_VERSION;
        out_result->status = (int32_t)status;
        out_result->completed = 0u;
        (void)snprintf(
            out_result->failure_stage,
            sizeof(out_result->failure_stage),
            "%s",
            stage != NULL ? stage : "resident_prefix_cache"
        );
        (void)snprintf(
            out_result->failure,
            sizeof(out_result->failure),
            "%s",
            message != NULL
                ? message
                : "resident prefix-cache request failed"
        );
    }
    if (engine != NULL) {
        qrt_engine_set_token_request_failure(
            engine,
            stage != NULL ? stage : "resident_prefix_cache",
            message != NULL
                ? message
                : "resident prefix-cache request failed"
        );
    }
    return status;
}

static void qrt_resident_prefix_cache_reset_result_init(
    qrt_qwen36_resident_prefix_cache_reset_result_v1_t *out_result
) {
    if (out_result == NULL) {
        return;
    }
    memset(out_result, 0, sizeof(*out_result));
    out_result->struct_size = (uint32_t)sizeof(*out_result);
    out_result->abi_version =
        QRT_QWEN36_RESIDENT_PREFIX_CACHE_RESET_ABI_VERSION;
    out_result->status = (int32_t)QRT_STATUS_INVALID_ARGUMENT;
}

static qrt_status_t qrt_resident_prefix_cache_reset_result_failure(
    qrt_engine_t *engine,
    qrt_qwen36_resident_prefix_cache_reset_result_v1_t *out_result,
    qrt_status_t status,
    const char *stage,
    const char *message
) {
    if (out_result != NULL) {
        out_result->struct_size = (uint32_t)sizeof(*out_result);
        out_result->abi_version =
            QRT_QWEN36_RESIDENT_PREFIX_CACHE_RESET_ABI_VERSION;
        out_result->status = (int32_t)status;
        out_result->completed = 0u;
        (void)snprintf(
            out_result->failure_stage,
            sizeof(out_result->failure_stage),
            "%s",
            stage != NULL ? stage : "resident_prefix_cache_reset"
        );
        (void)snprintf(
            out_result->failure,
            sizeof(out_result->failure),
            "%s",
            message != NULL
                ? message
                : "resident prefix-cache reset failed"
        );
    }
    if (engine != NULL) {
        qrt_engine_set_token_request_failure(
            engine,
            stage != NULL ? stage : "resident_prefix_cache_reset",
            message != NULL
                ? message
                : "resident prefix-cache reset failed"
        );
    }
    return status;
}

#ifdef _WIN32
static void qrt_engine_clear_resident_prefix_cache_identity(
    qrt_engine_t *engine,
    int release_token_storage
) {
    if (engine == NULL) {
        return;
    }
    engine->resident_prefix_cache_session_valid = 0;
    engine->resident_prefix_cache_token_count = 0u;
    engine->resident_prefix_cache_session_generation = UINT64_C(0);
    engine->resident_prefix_cache_prompt_token_ids_fnv1a64 = UINT64_C(0);
    if (release_token_storage) {
        free(engine->resident_prefix_cache_tokens);
        engine->resident_prefix_cache_tokens = NULL;
        engine->resident_prefix_cache_token_capacity = 0u;
    }
}
#endif

static qrt_status_t qrt_engine_request_tokens_prefix_v1_unlocked(
    qrt_engine_t *engine,
    const uint32_t *input_tokens,
    size_t input_token_count,
    size_t prefix_hit_token_count,
    uint32_t *output_tokens,
    size_t output_token_capacity,
    qrt_qwen36_resident_prefix_cache_result_v1_t *out_result,
    int stream_output_events
) {
    uint64_t input_digest;
    uint64_t prefix_digest;
    uint64_t suffix_digest;
    size_t token_index;

    if (out_result == NULL) {
        return QRT_STATUS_INVALID_ARGUMENT;
    }
    qrt_resident_prefix_cache_result_init(out_result);
    if (engine == NULL || input_tokens == NULL || output_tokens == NULL ||
        input_token_count == 0u || prefix_hit_token_count == 0u ||
        prefix_hit_token_count >= input_token_count ||
        prefix_hit_token_count > (size_t)UINT32_MAX ||
        input_token_count - prefix_hit_token_count >
            (size_t)QRT_QWEN36_RESIDENT_PREFIX_CACHE_MAX_SUFFIX_TOKENS ||
        output_token_capacity == 0u ||
        output_token_capacity >
            (size_t)QRT_QWEN36_WHOLE_PROVIDER_MAX_OUTPUT_TOKENS ||
        input_token_count - prefix_hit_token_count +
                output_token_capacity - 1u >
            (size_t)QRT_QWEN36_RESIDENT_PREFIX_CACHE_MAX_TAIL_TOKENS ||
        (stream_output_events
             ? (!engine->token_stream_active ||
                engine->token_stream_callback == NULL)
             : engine->token_stream_active)) {
        return qrt_resident_prefix_cache_result_failure(
            engine,
            out_result,
            QRT_STATUS_INVALID_ARGUMENT,
            "resident_prefix_cache_request",
            "resident prefix-cache request received an invalid token, prefix, output, or streaming shape"
        );
    }
    for (token_index = 0u; token_index < input_token_count; ++token_index) {
        if (input_tokens[token_index] >=
            (uint32_t)QRT_QWEN36_VOCAB_SIZE) {
            return qrt_resident_prefix_cache_result_failure(
                engine,
                out_result,
                QRT_STATUS_INVALID_ARGUMENT,
                "resident_prefix_cache_token",
                "resident prefix-cache request contains an out-of-vocabulary token"
            );
        }
    }

    input_digest = qrt_fnv1a64_bytes(
        input_tokens,
        input_token_count * sizeof(input_tokens[0])
    );
    prefix_digest = qrt_fnv1a64_bytes(
        input_tokens,
        prefix_hit_token_count * sizeof(input_tokens[0])
    );
    suffix_digest = qrt_fnv1a64_bytes(
        input_tokens + prefix_hit_token_count,
        (input_token_count - prefix_hit_token_count) *
            sizeof(input_tokens[0])
    );
    out_result->batch_size = 1u;
    out_result->prefix_token_count = (uint32_t)prefix_hit_token_count;
    out_result->suffix_token_count =
        (uint32_t)(input_token_count - prefix_hit_token_count);
    out_result->output_token_capacity =
        (uint32_t)output_token_capacity;
    out_result->input_token_ids_fnv1a64 = input_digest;
    out_result->prompt_token_ids_fnv1a64 = prefix_digest;
    out_result->suffix_token_ids_fnv1a64 = suffix_digest;

    if (!engine->ready || !engine->manifest_loaded ||
        !engine->resident_prefix_cache_session_valid ||
        engine->resident_prefix_cache_tokens == NULL ||
        engine->resident_prefix_cache_token_count !=
            prefix_hit_token_count ||
        memcmp(
            engine->resident_prefix_cache_tokens,
            input_tokens,
            prefix_hit_token_count * sizeof(input_tokens[0])
        ) != 0 ||
        engine->resident_prefix_cache_session_generation == UINT64_C(0) ||
        engine->resident_prefix_cache_prompt_token_ids_fnv1a64 !=
            prefix_digest) {
        return qrt_resident_prefix_cache_result_failure(
            engine,
            out_result,
            QRT_STATUS_UNSUPPORTED,
            "resident_prefix_cache_identity",
            "resident prefix-cache request does not exactly match the live cached-prefix token identity"
        );
    }
    out_result->exact_prefix_match = 1u;
    out_result->session_generation =
        engine->resident_prefix_cache_session_generation;

#ifndef _WIN32
    return qrt_resident_prefix_cache_result_failure(
        engine,
        out_result,
        QRT_STATUS_UNSUPPORTED,
        "resident_prefix_cache_platform",
        "resident prefix-cache inference is available only through the native Windows whole provider"
    );
#else
    {
        qrt_qwen36_whole_provider_prefix_request_v1_t provider_request;
        qrt_qwen36_resident_prefix_cache_result_v1_t provider_result;
        qrt_qwen36_token_stream_bridge_t token_stream_bridge;
        const char *ignore_eos_env;
        uint64_t request_start_ns;
        uint64_t caller_elapsed_ns;
        uint64_t expected_teacher_digest;
        uint64_t expected_output_digest;
        uint64_t previous_output_end_ns;
        int output_timing_valid;
        int provider_ok;

        if (!qrt_win32_qwen36_whole_provider_backend_load(engine) ||
            engine->qwen36_whole_provider_prefix == NULL) {
            return qrt_resident_prefix_cache_result_failure(
                engine,
                out_result,
                QRT_STATUS_UNSUPPORTED,
                "resident_prefix_cache_provider",
                engine->qwen36_whole_provider_failure[0] != '\0'
                    ? engine->qwen36_whole_provider_failure
                    : "whole-provider DLL does not export resident prefix-cache v1"
            );
        }

        memset(&provider_request, 0, sizeof(provider_request));
        memset(&provider_result, 0, sizeof(provider_result));
        provider_request.struct_size =
            (uint32_t)sizeof(provider_request);
        provider_request.abi_version =
            QRT_QWEN36_RESIDENT_PREFIX_CACHE_ABI_VERSION;
        ignore_eos_env = getenv(
            "QRT_QWEN36_RESIDENT_PREFIX_CACHE_IGNORE_EOS"
        );
        provider_request.flags =
            ignore_eos_env != NULL && strcmp(ignore_eos_env, "1") == 0
                ? QRT_QWEN36_RESIDENT_PREFIX_CACHE_FLAG_IGNORE_EOS
                : QRT_QWEN36_RESIDENT_PREFIX_CACHE_FLAG_NONE;
        provider_request.batch_size = 1u;
        provider_request.expected_prefix_token_count =
            (uint32_t)prefix_hit_token_count;
        provider_request.suffix_token_count =
            (uint32_t)(input_token_count - prefix_hit_token_count);
        provider_request.output_token_capacity =
            (uint32_t)output_token_capacity;
        provider_request.expected_base_committed_token_count = 0u;
        provider_request.expected_session_generation =
            engine->resident_prefix_cache_session_generation;
        provider_request.expected_prompt_token_ids_fnv1a64 =
            engine->resident_prefix_cache_prompt_token_ids_fnv1a64;
        provider_request.expected_suffix_token_ids_fnv1a64 =
            suffix_digest;
        provider_request.suffix_tokens =
            input_tokens + prefix_hit_token_count;
        provider_request.input_token_count =
            (uint32_t)input_token_count;
        provider_request.expected_input_token_ids_fnv1a64 =
            input_digest;
        provider_request.input_tokens = input_tokens;
        memset(&token_stream_bridge, 0, sizeof(token_stream_bridge));
        token_stream_bridge.engine = engine;
        token_stream_bridge.expected_session_generation =
            engine->resident_prefix_cache_session_generation;
        provider_request.emit_callback =
            stream_output_events
                ? qrt_qwen36_whole_provider_prefix_token_stream_bridge
                : NULL;
        provider_request.emit_user_data =
            stream_output_events ? &token_stream_bridge : NULL;

        ++engine->request_count;
        ++engine->token_request_count;
        qrt_engine_set_token_request_failure(engine, "", "");
        request_start_ns = qrt_now_ns();
        provider_ok = engine->qwen36_whole_provider_prefix(
            &provider_request,
            &provider_result
        );
        caller_elapsed_ns =
            qrt_elapsed_ns(request_start_ns, qrt_now_ns());
        provider_result.failure_stage[
            sizeof(provider_result.failure_stage) - 1u
        ] = '\0';
        provider_result.failure[
            sizeof(provider_result.failure) - 1u
        ] = '\0';

        expected_teacher_digest =
            provider_result.teacher_forced_prediction_count <=
                    QRT_QWEN36_RESIDENT_PREFIX_CACHE_MAX_SUFFIX_TOKENS
                ? qrt_fnv1a64_bytes(
                      provider_result.teacher_forced_prediction_tokens,
                      (size_t)provider_result
                              .teacher_forced_prediction_count *
                          sizeof(
                              provider_result
                                  .teacher_forced_prediction_tokens[0]
                          )
                  )
                : UINT64_C(0);
        expected_output_digest =
            provider_result.output_token_count <=
                    QRT_QWEN36_WHOLE_PROVIDER_MAX_OUTPUT_TOKENS
                ? qrt_fnv1a64_bytes(
                      provider_result.output_tokens,
                      (size_t)provider_result.output_token_count *
                          sizeof(provider_result.output_tokens[0])
                  )
                : UINT64_C(0);
        output_timing_valid =
            provider_result.output_token_count != 0u &&
            provider_result.output_token_count <=
                QRT_QWEN36_WHOLE_PROVIDER_MAX_OUTPUT_TOKENS &&
            provider_result.output_timing_count ==
                provider_result.output_token_count &&
            provider_result.output_token_step_elapsed_ns[0] ==
                provider_result.ttft_elapsed_ns &&
            provider_result.output_token_end_elapsed_ns[0] == UINT64_C(0);
        previous_output_end_ns = UINT64_C(0);
        for (token_index = 1u;
             output_timing_valid &&
             token_index < (size_t)provider_result.output_timing_count;
             ++token_index) {
            const uint64_t step_ns =
                provider_result.output_token_step_elapsed_ns[token_index];
            const uint64_t end_ns =
                provider_result.output_token_end_elapsed_ns[token_index];
            if (step_ns == UINT64_C(0) ||
                end_ns <= previous_output_end_ns ||
                end_ns - previous_output_end_ns != step_ns) {
                output_timing_valid = 0;
                break;
            }
            previous_output_end_ns = end_ns;
        }
        if (output_timing_valid &&
            (previous_output_end_ns != provider_result.tpot_elapsed_ns ||
             provider_result.tpot_elapsed_ns >
                 provider_result.decode_elapsed_ns)) {
            output_timing_valid = 0;
        }
        if (!provider_ok ||
            provider_result.struct_size !=
                (uint32_t)sizeof(provider_result) ||
            provider_result.abi_version !=
                QRT_QWEN36_RESIDENT_PREFIX_CACHE_ABI_VERSION ||
            provider_result.status != (int32_t)QRT_STATUS_OK ||
            provider_result.completed == 0u ||
            provider_result.provider_invoked == 0u ||
            provider_result.copy_on_write_transaction == 0u ||
            provider_result.state_restored == 0u ||
            provider_result.batch_size != 1u ||
            provider_result.prefix_token_count !=
                (uint32_t)prefix_hit_token_count ||
            provider_result.suffix_token_count !=
                (uint32_t)(input_token_count - prefix_hit_token_count) ||
            provider_result.output_token_capacity !=
                (uint32_t)output_token_capacity ||
            provider_result.output_token_count !=
                (uint32_t)output_token_capacity ||
            provider_result.teacher_forced_prediction_count !=
                provider_result.suffix_token_count ||
            provider_result.base_committed_token_count != 0u ||
            provider_result.mutated_committed_token_count !=
                provider_result.suffix_token_count +
                    provider_result.output_token_count - 1u ||
            provider_result.restored_committed_token_count != 0u ||
            provider_result.session_generation !=
                engine->resident_prefix_cache_session_generation ||
            provider_result.prompt_token_ids_fnv1a64 != prefix_digest ||
            provider_result.suffix_token_ids_fnv1a64 != suffix_digest ||
            provider_result.teacher_forced_prediction_ids_fnv1a64 !=
                expected_teacher_digest ||
            provider_result.output_token_ids_fnv1a64 !=
                expected_output_digest ||
            provider_result.shadow_bytes == UINT64_C(0) ||
            provider_result.ttft_elapsed_ns == UINT64_C(0) ||
            provider_result.total_elapsed_ns <
                provider_result.ttft_elapsed_ns ||
            provider_result.tpot_sample_count !=
                output_token_capacity - 1u ||
            !output_timing_valid) {
            const char *failure_stage =
                provider_result.failure_stage[0] != '\0'
                    ? provider_result.failure_stage
                    : "resident_prefix_cache_provider_contract";
            const char *failure_message =
                provider_result.failure[0] != '\0'
                    ? provider_result.failure
                    : "whole-provider resident prefix-cache result violated its state, token, timing, or rollback contract";
            *out_result = provider_result;
            out_result->input_token_ids_fnv1a64 = input_digest;
            out_result->exact_prefix_match = 1u;
            if (provider_result.state_restored == 0u) {
                /*
                 * A failed provider transaction that did not restore state
                 * invalidates the entire core-side identity, not only its
                 * valid bit.  Leaving the token count, generation, or prompt
                 * digest behind creates an internally inconsistent empty
                 * identity and prevents an owner-aware reset from reaching
                 * the provider.
                 *
                 * Keep the token allocation for a later seed, but clear every
                 * field that participates in cache ownership.
                 */
                qrt_engine_clear_resident_prefix_cache_identity(engine, 0);
            }
            engine->last_request_elapsed_ns = caller_elapsed_ns;
            engine->last_request_ttft_elapsed_ns = UINT64_C(0);
            engine->last_request_tpot_elapsed_ns = UINT64_C(0);
            engine->last_request_tpot_sample_count = 0u;
            engine->last_request_output_token_count = 0u;
            engine->request_elapsed_ns += caller_elapsed_ns;
            return qrt_resident_prefix_cache_result_failure(
                engine,
                out_result,
                QRT_STATUS_UNSUPPORTED,
                failure_stage,
                failure_message
            );
        }
        *out_result = provider_result;
        out_result->exact_prefix_match = 1u;
        out_result->input_token_ids_fnv1a64 = input_digest;
        for (token_index = 0u;
             token_index <
                 (size_t)provider_result.teacher_forced_prediction_count;
             ++token_index) {
            if (provider_result
                    .teacher_forced_prediction_tokens[token_index] >=
                (uint32_t)QRT_QWEN36_VOCAB_SIZE) {
                return qrt_resident_prefix_cache_result_failure(
                    engine,
                    out_result,
                    QRT_STATUS_UNSUPPORTED,
                    "resident_prefix_cache_teacher_token",
                    "whole-provider resident prefix-cache result returned an invalid teacher-forced token"
                );
            }
        }
        for (token_index = 0u;
             token_index < (size_t)provider_result.output_token_count;
             ++token_index) {
            if (provider_result.output_tokens[token_index] >=
                (uint32_t)QRT_QWEN36_VOCAB_SIZE) {
                return qrt_resident_prefix_cache_result_failure(
                    engine,
                    out_result,
                    QRT_STATUS_UNSUPPORTED,
                    "resident_prefix_cache_output_token",
                    "whole-provider resident prefix-cache result returned an invalid output token"
                );
            }
        }

        memcpy(
            output_tokens,
            provider_result.output_tokens,
            output_token_capacity * sizeof(output_tokens[0])
        );
        engine->last_request_elapsed_ns =
            provider_result.total_elapsed_ns != UINT64_C(0)
                ? provider_result.total_elapsed_ns
                : caller_elapsed_ns;
        engine->last_request_ttft_elapsed_ns =
            provider_result.ttft_elapsed_ns;
        engine->last_request_tpot_elapsed_ns =
            provider_result.tpot_elapsed_ns;
        engine->last_request_tpot_sample_count =
            provider_result.tpot_sample_count;
        engine->last_request_output_token_count =
            provider_result.output_token_count;
        engine->last_request_descriptor_output_prefill_sample_count = 1u;
        engine->last_request_descriptor_output_decode_token_count =
            provider_result.output_token_count - 1u;
        engine->last_request_descriptor_output_autoregressive_decode =
            provider_result.output_token_count > 1u ? 1u : 0u;
        engine->request_elapsed_ns += engine->last_request_elapsed_ns;
        if (engine->request_count == 1u) {
            engine->first_request_elapsed_ns =
                engine->last_request_elapsed_ns;
        }
        return QRT_STATUS_OK;
    }
#endif
}

qrt_status_t qrt_engine_request_tokens_prefix_v1(
    qrt_engine_t *engine,
    const uint32_t *input_tokens,
    size_t input_token_count,
    size_t prefix_hit_token_count,
    uint32_t *output_tokens,
    size_t output_token_capacity,
    qrt_qwen36_resident_prefix_cache_result_v1_t *out_result
) {
#ifdef _WIN32
    qrt_engine_request_serialization_guard_t guard;
    qrt_status_t status;

    if (engine == NULL) {
        return qrt_engine_request_tokens_prefix_v1_unlocked(
            engine,
            input_tokens,
            input_token_count,
            prefix_hit_token_count,
            output_tokens,
            output_token_capacity,
            out_result,
            0
        );
    }
    if (!qrt_engine_request_serialization_acquire(
            engine,
            QRT_QWEN36_REQUEST_SERIALIZATION_OPERATION_PREFIX,
            &guard)) {
        if (out_result != NULL) {
            qrt_resident_prefix_cache_result_init(out_result);
        }
        return qrt_resident_prefix_cache_result_failure(
            engine,
            out_result,
            QRT_STATUS_UNSUPPORTED,
            "resident_prefix_cache_request_serialization",
            "resident prefix-cache request could not acquire the per-engine serialization boundary"
        );
    }
    status = qrt_engine_request_tokens_prefix_v1_unlocked(
        engine,
        input_tokens,
        input_token_count,
        prefix_hit_token_count,
        output_tokens,
        output_token_capacity,
        out_result,
        0
    );
    qrt_engine_request_serialization_release(&guard);
    return status;
#else
    return qrt_engine_request_tokens_prefix_v1_unlocked(
        engine,
        input_tokens,
        input_token_count,
        prefix_hit_token_count,
        output_tokens,
        output_token_capacity,
        out_result,
        0
    );
#endif
}

static qrt_status_t qrt_engine_request_tokens_prefix_stream_v1_unlocked(
    qrt_engine_t *engine,
    const uint32_t *input_tokens,
    size_t input_token_count,
    size_t prefix_hit_token_count,
    uint32_t *output_tokens,
    size_t output_token_capacity,
    qrt_qwen36_resident_prefix_cache_result_v1_t *out_result,
    qrt_token_stream_callback_v1_t callback,
    void *user_data
) {
    qrt_status_t status;
#ifdef _WIN32
    size_t output_index;
#endif

    if (engine == NULL || callback == NULL || engine->token_stream_active) {
        if (out_result != NULL) {
            qrt_resident_prefix_cache_result_init(out_result);
        }
        return qrt_resident_prefix_cache_result_failure(
            engine,
            out_result,
            QRT_STATUS_INVALID_ARGUMENT,
            "resident_prefix_stream_request",
            "resident prefix stream requires an engine, callback, and idle stream state"
        );
    }

    engine->token_stream_callback = callback;
    engine->token_stream_user_data = user_data;
    engine->token_stream_request_start_ns = qrt_now_ns();
    engine->token_stream_last_request_elapsed_ns = UINT64_C(0);
    engine->token_stream_callback_count = 0u;
    memset(
        engine->token_stream_emitted_tokens,
        0,
        sizeof(engine->token_stream_emitted_tokens)
    );
    engine->token_stream_cancelled = 0;
    engine->token_stream_contract_failed = 0;
    engine->token_stream_active = 1;

    status = qrt_engine_request_tokens_prefix_v1_unlocked(
        engine,
        input_tokens,
        input_token_count,
        prefix_hit_token_count,
        output_tokens,
        output_token_capacity,
        out_result,
        1
    );
    engine->token_stream_active = 0;
#ifdef _WIN32
    if (status == QRT_STATUS_OK) {
        if (engine->token_stream_cancelled ||
            engine->token_stream_contract_failed ||
            engine->token_stream_callback_count != output_token_capacity) {
            engine->token_stream_contract_failed = 1;
        } else {
            for (output_index = 0u;
                 output_index < output_token_capacity;
                 ++output_index) {
                if (engine->token_stream_emitted_tokens[output_index] !=
                    output_tokens[output_index]) {
                    engine->token_stream_contract_failed = 1;
                    break;
                }
            }
        }
        if (engine->token_stream_contract_failed) {
            status = qrt_resident_prefix_cache_result_failure(
                engine,
                out_result,
                QRT_STATUS_UNSUPPORTED,
                "resident_prefix_stream_completion_contract",
                "resident prefix stream callbacks did not exactly match the completed output and timing sequence"
            );
        }
    }
#endif

    engine->token_stream_active = 0;
    engine->token_stream_callback = NULL;
    engine->token_stream_user_data = NULL;
    return status;
}

qrt_status_t qrt_engine_request_tokens_prefix_stream_v1(
    qrt_engine_t *engine,
    const uint32_t *input_tokens,
    size_t input_token_count,
    size_t prefix_hit_token_count,
    uint32_t *output_tokens,
    size_t output_token_capacity,
    qrt_qwen36_resident_prefix_cache_result_v1_t *out_result,
    qrt_token_stream_callback_v1_t callback,
    void *user_data
) {
#ifdef _WIN32
    qrt_engine_request_serialization_guard_t guard;
    qrt_status_t status;

    if (engine == NULL) {
        return qrt_engine_request_tokens_prefix_stream_v1_unlocked(
            engine,
            input_tokens,
            input_token_count,
            prefix_hit_token_count,
            output_tokens,
            output_token_capacity,
            out_result,
            callback,
            user_data
        );
    }
    if (!qrt_engine_request_serialization_acquire(
            engine,
            QRT_QWEN36_REQUEST_SERIALIZATION_OPERATION_STREAM,
            &guard)) {
        if (out_result != NULL) {
            qrt_resident_prefix_cache_result_init(out_result);
        }
        return qrt_resident_prefix_cache_result_failure(
            engine,
            out_result,
            QRT_STATUS_UNSUPPORTED,
            "resident_prefix_stream_serialization",
            "resident prefix stream could not acquire the per-engine serialization boundary"
        );
    }
    status = qrt_engine_request_tokens_prefix_stream_v1_unlocked(
        engine,
        input_tokens,
        input_token_count,
        prefix_hit_token_count,
        output_tokens,
        output_token_capacity,
        out_result,
        callback,
        user_data
    );
    qrt_engine_request_serialization_release(&guard);
    return status;
#else
    return qrt_engine_request_tokens_prefix_stream_v1_unlocked(
        engine,
        input_tokens,
        input_token_count,
        prefix_hit_token_count,
        output_tokens,
        output_token_capacity,
        out_result,
        callback,
        user_data
    );
#endif
}

static qrt_status_t qrt_engine_reset_resident_prefix_cache_v1_unlocked(
    qrt_engine_t *engine,
    qrt_qwen36_resident_prefix_cache_reset_result_v1_t *out_result
) {
    uint32_t core_valid_before;
    uint32_t core_prefix_tokens_before;
    uint64_t core_generation_before;
    uint64_t core_prompt_digest_before;

    if (out_result == NULL) {
        return QRT_STATUS_INVALID_ARGUMENT;
    }
    qrt_resident_prefix_cache_reset_result_init(out_result);
    if (engine == NULL || !engine->ready || !engine->manifest_loaded ||
        engine->token_stream_active) {
        return qrt_resident_prefix_cache_reset_result_failure(
            engine,
            out_result,
            QRT_STATUS_INVALID_ARGUMENT,
            "resident_prefix_cache_reset_request",
            "resident prefix-cache reset requires a ready non-streaming engine"
        );
    }

    core_valid_before =
        engine->resident_prefix_cache_session_valid ? 1u : 0u;
    if ((core_valid_before != 0u &&
         (engine->resident_prefix_cache_tokens == NULL ||
          engine->resident_prefix_cache_token_count == 0u ||
          engine->resident_prefix_cache_token_count > (size_t)UINT32_MAX ||
          engine->resident_prefix_cache_session_generation == UINT64_C(0) ||
          engine->resident_prefix_cache_prompt_token_ids_fnv1a64 ==
              UINT64_C(0))) ||
        (core_valid_before == 0u &&
         (engine->resident_prefix_cache_token_count != 0u ||
          engine->resident_prefix_cache_session_generation != UINT64_C(0) ||
          engine->resident_prefix_cache_prompt_token_ids_fnv1a64 !=
              UINT64_C(0)))) {
        return qrt_resident_prefix_cache_reset_result_failure(
            engine,
            out_result,
            QRT_STATUS_UNSUPPORTED,
            "resident_prefix_cache_reset_core_identity",
            "resident prefix-cache core identity is internally inconsistent"
        );
    }
    core_prefix_tokens_before =
        (uint32_t)engine->resident_prefix_cache_token_count;
    core_generation_before =
        engine->resident_prefix_cache_session_generation;
    core_prompt_digest_before =
        engine->resident_prefix_cache_prompt_token_ids_fnv1a64;
    out_result->core_session_valid_before = core_valid_before;
    out_result->core_prefix_token_count_before =
        core_prefix_tokens_before;
    out_result->core_session_generation_before =
        core_generation_before;
    out_result->core_prompt_token_ids_fnv1a64_before =
        core_prompt_digest_before;

#ifndef _WIN32
    return qrt_resident_prefix_cache_reset_result_failure(
        engine,
        out_result,
        QRT_STATUS_UNSUPPORTED,
        "resident_prefix_cache_reset_platform",
        "resident prefix-cache reset is available only through the native Windows whole provider"
    );
#else
    {
        qrt_qwen36_resident_prefix_cache_reset_request_v1_t
            provider_request;
        qrt_qwen36_resident_prefix_cache_reset_result_v1_t
            provider_result;
        uint64_t request_start_ns;
        uint64_t caller_elapsed_ns;
        int provider_ok;
        int provider_contract_ok;

        if (!qrt_win32_qwen36_whole_provider_backend_load(engine) ||
            engine->qwen36_whole_provider_prefix_reset == NULL) {
            return qrt_resident_prefix_cache_reset_result_failure(
                engine,
                out_result,
                QRT_STATUS_UNSUPPORTED,
                "resident_prefix_cache_reset_provider",
                engine->qwen36_whole_provider_failure[0] != '\0'
                    ? engine->qwen36_whole_provider_failure
                    : "whole-provider DLL does not export resident prefix-cache reset v1"
            );
        }

        memset(&provider_request, 0, sizeof(provider_request));
        memset(&provider_result, 0, sizeof(provider_result));
        provider_request.struct_size =
            (uint32_t)sizeof(provider_request);
        provider_request.abi_version =
            QRT_QWEN36_RESIDENT_PREFIX_CACHE_RESET_ABI_VERSION;
        provider_request.flags =
            QRT_QWEN36_RESIDENT_PREFIX_CACHE_RESET_FLAG_NONE;
        provider_request.expected_session_valid = core_valid_before;
        provider_request.expected_owner_engine = engine;
        provider_request.expected_prefix_token_count =
            core_prefix_tokens_before;
        provider_request.expected_session_generation =
            core_generation_before;
        provider_request.expected_prompt_token_ids_fnv1a64 =
            core_prompt_digest_before;

        qrt_engine_set_token_request_failure(engine, "", "");
        request_start_ns = qrt_now_ns();
        provider_ok = engine->qwen36_whole_provider_prefix_reset(
            &provider_request,
            &provider_result
        );
        caller_elapsed_ns =
            qrt_elapsed_ns(request_start_ns, qrt_now_ns());
        provider_result.failure_stage[
            sizeof(provider_result.failure_stage) - 1u
        ] = '\0';
        provider_result.failure[
            sizeof(provider_result.failure) - 1u
        ] = '\0';

        provider_contract_ok =
            provider_ok &&
            provider_result.struct_size ==
                (uint32_t)sizeof(provider_result) &&
            provider_result.abi_version ==
                QRT_QWEN36_RESIDENT_PREFIX_CACHE_RESET_ABI_VERSION &&
            provider_result.status == (int32_t)QRT_STATUS_OK &&
            provider_result.completed != 0u &&
            provider_result.provider_invoked != 0u &&
            provider_result.provider_completed != 0u &&
            provider_result.provider_owner_match != 0u &&
            provider_result.idempotent ==
                (core_valid_before == 0u ? 1u : 0u) &&
            provider_result.provider_session_valid_before ==
                core_valid_before &&
            provider_result.provider_session_valid_after == 0u &&
            provider_result.provider_prefix_token_count_before ==
                core_prefix_tokens_before &&
            provider_result.provider_prefix_token_count_after == 0u &&
            provider_result.provider_committed_token_count_after == 0u &&
            provider_result.provider_session_generation_before ==
                core_generation_before &&
            provider_result.provider_session_generation_after ==
                UINT64_C(0) &&
            provider_result.provider_prompt_token_ids_fnv1a64_before ==
                core_prompt_digest_before &&
            provider_result.provider_prompt_token_ids_fnv1a64_after ==
                UINT64_C(0) &&
            provider_result.provider_generation_clock_after ==
                provider_result.provider_generation_clock_before &&
            provider_result.provider_resident_state_bytes_after ==
                UINT64_C(0) &&
            provider_result.provider_resident_state_bytes_released ==
                provider_result.provider_resident_state_bytes_before &&
            (core_valid_before == 0u ||
             provider_result.provider_resident_state_bytes_before >
                 UINT64_C(0)) &&
            provider_result.shared_model_weights_retained != 0u &&
            provider_result.provider_reset_elapsed_ns <=
                provider_result.total_elapsed_ns;

        *out_result = provider_result;
        out_result->core_session_valid_before = core_valid_before;
        out_result->core_prefix_token_count_before =
            core_prefix_tokens_before;
        out_result->core_session_generation_before =
            core_generation_before;
        out_result->core_prompt_token_ids_fnv1a64_before =
            core_prompt_digest_before;
        if (!provider_contract_ok) {
            /*
             * Once the provider reports a completed empty state, retaining
             * the core identity would create a stale split-brain cache even
             * if a later result field failed validation.
             */
            if (provider_result.provider_completed != 0u &&
                provider_result.provider_session_valid_after == 0u &&
                provider_result.provider_resident_state_bytes_after ==
                    UINT64_C(0)) {
                qrt_engine_clear_resident_prefix_cache_identity(engine, 1);
            }
            out_result->core_session_valid_after =
                engine->resident_prefix_cache_session_valid ? 1u : 0u;
            out_result->core_prefix_token_count_after =
                (uint32_t)engine->resident_prefix_cache_token_count;
            out_result->core_session_generation_after =
                engine->resident_prefix_cache_session_generation;
            out_result->core_prompt_token_ids_fnv1a64_after =
                engine->resident_prefix_cache_prompt_token_ids_fnv1a64;
            return qrt_resident_prefix_cache_reset_result_failure(
                engine,
                out_result,
                QRT_STATUS_UNSUPPORTED,
                provider_result.failure_stage[0] != '\0'
                    ? provider_result.failure_stage
                    : "resident_prefix_cache_reset_provider_contract",
                provider_result.failure[0] != '\0'
                    ? provider_result.failure
                    : "whole-provider resident prefix-cache reset violated its owner, identity, storage, or lifecycle contract"
            );
        }

        qrt_engine_clear_resident_prefix_cache_identity(engine, 1);
        out_result->core_session_valid_after = 0u;
        out_result->core_prefix_token_count_after = 0u;
        out_result->core_session_generation_after = UINT64_C(0);
        out_result->core_prompt_token_ids_fnv1a64_after = UINT64_C(0);
        out_result->total_elapsed_ns =
            provider_result.total_elapsed_ns != UINT64_C(0)
                ? provider_result.total_elapsed_ns
                : caller_elapsed_ns;
        out_result->status = (int32_t)QRT_STATUS_OK;
        out_result->completed = 1u;
        qrt_engine_set_token_request_failure(engine, "", "");
        return QRT_STATUS_OK;
    }
#endif
}

qrt_status_t qrt_engine_reset_resident_prefix_cache_v1(
    qrt_engine_t *engine,
    qrt_qwen36_resident_prefix_cache_reset_result_v1_t *out_result
) {
#ifdef _WIN32
    qrt_engine_request_serialization_guard_t guard;
    qrt_status_t status;

    if (engine == NULL) {
        return qrt_engine_reset_resident_prefix_cache_v1_unlocked(
            engine,
            out_result
        );
    }
    if (!qrt_engine_request_serialization_acquire(
            engine,
            QRT_QWEN36_REQUEST_SERIALIZATION_OPERATION_PREFIX_RESET,
            &guard)) {
        if (out_result != NULL) {
            qrt_resident_prefix_cache_reset_result_init(out_result);
        }
        return qrt_resident_prefix_cache_reset_result_failure(
            engine,
            out_result,
            QRT_STATUS_UNSUPPORTED,
            "resident_prefix_cache_reset_serialization",
            "resident prefix-cache reset could not acquire the per-engine serialization boundary"
        );
    }
    status = qrt_engine_reset_resident_prefix_cache_v1_unlocked(
        engine,
        out_result
    );
    qrt_engine_request_serialization_release(&guard);
    return status;
#else
    return qrt_engine_reset_resident_prefix_cache_v1_unlocked(
        engine,
        out_result
    );
#endif
}

